var e=JSON.parse(`[{"id":"aut.transcricao_ia.asr_modelos.0001","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Na arquitetura clássica de ASR, o léxico de pronúncia associa cada palavra à sua sequência de fonemas, fazendo a ligação entre o modelo acústico e o modelo de linguagem.","gabarito":"C","explicacao":"O modelo acústico trabalha com unidades sonoras (fonemas); o modelo de linguagem trabalha com palavras. O léxico de pronúncia é o dicionário que converte uma coisa na outra, e o decodificador combina os três componentes.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. No sistema clássico de transcrição automática, uma parte entende os sons e outra entende as palavras. O léxico de pronúncia é como um dicionário que diz quais sons formam cada palavra. Ele faz a ponte entre as duas partes.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês para reconhecimento automático de fala, tecnologia que transforma áudio de voz em texto escrito."},{"termo":"léxico de pronúncia","significado":"espécie de dicionário que informa quais sons, ou fonemas, formam cada palavra, ligando o som ao texto."},{"termo":"fonemas","significado":"os menores sons que distinguem palavras na fala, como o 'p' e o 'b' em 'pata' e 'bata'."},{"termo":"modelo acústico","significado":"parte do sistema que aprende a reconhecer os sons da fala a partir do áudio gravado."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais palavras e frases são mais prováveis, ajudando a escolher o texto certo."}],"exemplo":"A Câmara de Campos testa um sistema de transcrição. O técnico Rodrigo explica à colega Aline: o modelo acústico ouve os sons, o modelo de linguagem escolhe as palavras prováveis, e o léxico de pronúncia diz quais fonemas formam a palavra 'projeto'. Sem ele, os dois não se entendem."}},{"id":"aut.transcricao_ia.asr_modelos.0002","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Na arquitetura clássica de ASR, cabe ao modelo de linguagem relacionar o sinal acústico aos fonemas, enquanto o modelo acústico estima a probabilidade de sequências de palavras.","gabarito":"E","explicacao":"Os papéis estão invertidos. O modelo acústico relaciona o áudio a fonemas; o modelo de linguagem estima a probabilidade de sequências de palavras e favorece frases plausíveis.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. Os papéis estão trocados. O modelo acústico é quem liga o áudio aos sons da fala. O modelo de linguagem é quem avalia quais sequências de palavras são prováveis, ajudando a escolher frases que fazem sentido.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês para reconhecimento automático de fala, tecnologia que converte voz em texto."},{"termo":"modelo de linguagem","significado":"parte do sistema que estima quais palavras e frases são mais prováveis de aparecer em sequência."},{"termo":"sinal acústico","significado":"o áudio captado, a onda sonora da fala transformada em dados que o computador consegue analisar."},{"termo":"fonemas","significado":"os menores sons que distinguem palavras na fala, como o 'p' e o 'b'."},{"termo":"modelo acústico","significado":"parte do sistema que liga o áudio aos fonemas, aprendendo como cada som é produzido."}],"exemplo":"A analista Lorena montava um quadro sobre transcrição automática. Colocou: modelo acústico, que recebe o áudio e descobre os fonemas; e modelo de linguagem, que avalia se 'a lei foi votada' é mais provável que 'a lei foi botada'. O colega Heitor notou que a frase da prova trocava os papéis."}},{"id":"aut.transcricao_ia.asr_modelos.0003","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos modelos end-to-end de ASR, uma única rede neural é treinada para mapear diretamente o áudio para o texto, em regra sem léxico de pronúncia explícito.","gabarito":"C","explicacao":"É a diferença central em relação à arquitetura em módulos, na qual acústico, léxico e linguagem são componentes separados. Nos end-to-end, o aprendizado é conjunto e a saída pode ser composta por caracteres ou subpalavras.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. Nos modelos end-to-end, uma única rede neural aprende sozinha a ir direto do áudio para o texto. Eles dispensam, em geral, as peças separadas do sistema clássico, como o dicionário de pronúncia. Tudo é aprendido em conjunto.","teSitua":{"termos":[{"termo":"end-to-end","significado":"'de ponta a ponta'; modelo que faz todo o caminho, do áudio ao texto, em uma única rede, sem etapas separadas."},{"termo":"rede neural","significado":"programa de computador inspirado no cérebro, que aprende padrões a partir de muitos exemplos."},{"termo":"mapear","significado":"relacionar uma entrada a uma saída correspondente; aqui, ligar o áudio ao texto."},{"termo":"léxico de pronúncia","significado":"dicionário que informa quais sons formam cada palavra."}],"exemplo":"No tribunal, a equipe de TI comparou dois sistemas. O primeiro tinha módulos separados, incluindo léxico de pronúncia. O segundo, escolhido pelo analista Fábio, era end-to-end: uma só rede neural treinada recebia o áudio do plenário e entregava direto o texto, sem dicionário de pronúncia."}},{"id":"aut.transcricao_ia.asr_modelos.0004","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Os modelos end-to-end de ASR não admitem, em nenhuma hipótese, o acoplamento de um modelo de linguagem externo para melhorar o reconhecimento.","gabarito":"E","explicacao":"Generalização indevida. Modelos end-to-end podem ser combinados com modelo de linguagem externo (por exemplo, para reordenar hipóteses ou ponderar a decodificação), prática comum para melhorar a precisão em um domínio específico.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. A palavra 'nenhuma hipótese' torna a frase falsa. Modelos end-to-end podem, sim, receber um modelo de linguagem externo como reforço, por exemplo para reordenar as opções de texto. Isso é comum para melhorar a precisão em uma área específica.","teSitua":{"termos":[{"termo":"end-to-end","significado":"'de ponta a ponta'; modelo que faz todo o caminho, do áudio ao texto, em uma única rede."},{"termo":"acoplamento","significado":"ato de encaixar ou ligar uma peça a outra para trabalharem juntas."},{"termo":"modelo de linguagem externo","significado":"modelo separado que estima quais palavras são prováveis e que pode ser ligado ao sistema para melhorar o texto."},{"termo":"reconhecimento","significado":"capacidade do sistema de identificar o que foi falado e transformá-lo em texto."}],"exemplo":"A equipe da Assembleia usava um sistema end-to-end, mas ele errava nomes de municípios. A engenheira Priscila acrescentou um modelo de linguagem externo com textos da casa, e a precisão melhorou. Isso mostrou ao colega Ícaro que a frase 'em nenhuma hipótese' era falsa."}},{"id":"aut.transcricao_ia.asr_modelos.0005","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"No CTC, utiliza-se um símbolo especial chamado branco (blank) e a sequência final é obtida colapsando as repetições consecutivas e removendo os brancos.","gabarito":"C","explicacao":"O símbolo branco permite ao modelo emitir saída em quadros que não correspondem a rótulo novo, dispensando alinhamento prévio quadro a quadro. A regra de colapso de repetições e remoção dos brancos gera o texto final.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. No CTC, o modelo usa um símbolo especial chamado branco, que serve para dizer 'nada novo aqui'. Para chegar ao texto final, juntam-se as letras repetidas em sequência e tiram-se os brancos. Assim não é preciso alinhar cada pedaço do som com cada letra.","teSitua":{"termos":[{"termo":"CTC","significado":"sigla de um método de treinamento de reconhecimento de fala que dispensa alinhar cada trecho do som com cada letra."},{"termo":"branco","significado":"símbolo especial que o modelo emite quando não surge letra nova naquele instante, servindo de separador."},{"termo":"colapsando","significado":"juntando em um só elemento as repetições seguidas, como transformar 'aa' em 'a'."},{"termo":"repetições consecutivas","significado":"letras ou símbolos iguais que aparecem um logo depois do outro na saída do modelo."}],"exemplo":"O modelo do estagiário Bruno emitiu: c c _ a a _ s s a, onde '_' é o branco. A professora Telma ensinou a juntar as repetições seguidas e tirar os brancos. O resultado foi 'casa'. O branco ajudou o modelo a lidar com instantes sem letra nova."}},{"id":"aut.transcricao_ia.asr_modelos.0006","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"O RNN-Transducer se distingue do CTC por não possuir componente que modele os rótulos já emitidos, pois supõe independência condicional entre as saídas.","gabarito":"E","explicacao":"Inversão de conceitos. É o CTC que supõe independência condicional entre as saídas. O RNN-T inclui uma rede de predição, que consome os rótulos já emitidos e atua como modelo de linguagem interno.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. A frase trocou as coisas. Quem supõe que as saídas não dependem umas das outras é o CTC. O RNN-Transducer tem uma rede extra, que olha o que já foi escrito e ajuda a prever o próximo, como um modelo de linguagem interno.","teSitua":{"termos":[{"termo":"RNN-Transducer","significado":"tipo de modelo de reconhecimento de fala que combina o áudio com um histórico do que já foi escrito para prever a próxima palavra."},{"termo":"CTC","significado":"método de treinamento de reconhecimento de fala que supõe que cada saída não depende das anteriores."},{"termo":"rótulos","significado":"as unidades de saída do modelo, como letras ou pedaços de palavras, que formam o texto final."},{"termo":"independência condicional","significado":"suposição de que cada saída do modelo não depende das saídas anteriores, o que simplifica o cálculo."}],"exemplo":"A pesquisadora Gabriela explicou ao grupo: no CTC, o modelo escreve cada letra sem olhar o que já foi escrito. Já o RNN-Transducer tem uma rede que lembra as letras anteriores e ajuda a prever a próxima, como um modelo de linguagem interno. O colega Otávio percebeu a inversão na frase da prova."}},{"id":"aut.transcricao_ia.asr_portugues.0001","subtopico":"transcricao_ia.reconhecimento_fala.asr_portugues","tipo":"certo_errado","dificuldade":3,"enunciado":"A transcrição automática de sessões legislativas em português brasileiro enfrenta dificuldades como variação regional de sotaque, ruído de ambiente, sobreposição de vozes e vocabulário parlamentar, com siglas e nomes próprios.","gabarito":"C","explicacao":"São desafios típicos do domínio: a fala espontânea e rápida, os apartes e interrupções, a captação irregular e o vocabulário específico (siglas, nomes de parlamentares, expressões regimentais) elevam a taxa de erro de modelos genéricos.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. Transcrever sessões do Legislativo em português é difícil por vários motivos. Há sotaques diferentes, barulho no plenário, pessoas falando ao mesmo tempo e muitas siglas e nomes próprios. Tudo isso faz um modelo genérico errar mais.","teSitua":{"termos":[{"termo":"transcrição automática","significado":"conversão de áudio em texto escrito feita por um programa, sem digitação humana."},{"termo":"sessões legislativas","significado":"reuniões de parlamentares em que se debatem e votam leis e outros temas."},{"termo":"sobreposição de vozes","significado":"situação em que duas ou mais pessoas falam ao mesmo tempo, dificultando entender cada uma."},{"termo":"vocabulário parlamentar","significado":"palavras e expressões próprias do Legislativo, como 'requerimento', 'questão de ordem' e nomes de comissões."},{"termo":"siglas","significado":"abreviações formadas pelas letras iniciais de nomes, como CCJ ou PEC."}],"exemplo":"A Câmara Municipal de Itaúna testou a transcrição automática. Na sessão, a vereadora Sandra falava rápido, o vereador Pedro a interrompia e o ventilador fazia ruído. O sistema errou a sigla 'CCJ' e os sobrenomes. Foi preciso revisar tudo à mão."}},{"id":"aut.transcricao_ia.atas_resumos.0001","subtopico":"transcricao_ia.ia_parlamento.atas_resumos","tipo":"certo_errado","dificuldade":3,"enunciado":"A sumarização abstrativa apresenta menor risco de distorção do conteúdo do que a extrativa, por reescrever o texto com palavras próprias.","gabarito":"E","explicacao":"A relação é inversa: a extrativa recorta o original e preserva a literalidade; a abstrativa reescreve e, por isso, apresenta maior risco de imprecisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E IA no Parlamento)","mastigado":"Errado. É o contrário. O resumo extrativo recorta trechos do original e mantém as palavras como estavam. O abstrativo reescreve com outras palavras e, por isso, corre mais risco de errar ou distorcer o que foi dito.","teSitua":{"termos":[{"termo":"sumarização abstrativa","significado":"resumo em que o sistema reescreve o conteúdo com palavras novas, em vez de copiar trechos do original."},{"termo":"extrativa","significado":"resumo que seleciona e copia frases do texto original, sem reescrevê-las."},{"termo":"distorção","significado":"alteração do sentido do que foi dito, deixando o conteúdo diferente ou errado."}],"exemplo":"A equipe de comunicação testou dois resumos da sessão. O resumo extrativo da analista Ligia copiou frases do discurso. O abstrativo reescreveu, mas disse que o deputado 'apoiou' um projeto que ele só 'analisou'. Foi um exemplo do maior risco de distorção da abstrativa."}},{"id":"aut.transcricao_ia.busca_semantica.0001","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":3,"enunciado":"A geração aumentada por recuperação reduz a ocorrência de alucinação ao fundamentar a resposta em trechos previamente recuperados de uma base confiável.","gabarito":"C","explicacao":"É justamente essa ancoragem em fonte verificável que caracteriza a técnica e permite a citação da origem.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E IA no Parlamento)","mastigado":"Certo. Nessa técnica, o sistema primeiro busca trechos em uma base confiável e só depois responde, apoiado neles. Assim, ele inventa menos, o que se chama alucinação. Também fica fácil mostrar de onde veio a resposta.","teSitua":{"termos":[{"termo":"geração aumentada por recuperação","significado":"técnica em que o sistema busca trechos em uma base de documentos e os usa para montar a resposta, em vez de depender só da memória do modelo."},{"termo":"alucinação","significado":"erro em que a IA inventa informações falsas com aparência de verdade."},{"termo":"fundamentando","significado":"apoiando uma resposta em fontes ou provas, para que possa ser conferida."},{"termo":"base confiável","significado":"conjunto de documentos verificados e de boa qualidade, usado como fonte de consulta."}],"exemplo":"A assessora Raquel perguntou ao sistema do Senado qual é o prazo de um projeto. O programa buscou antes o trecho do regimento, na base de documentos confiáveis, e respondeu citando-o. Assim, inventou menos, ou seja, teve menos alucinações."}},{"id":"aut.transcricao_ia.busca_semantica.0002","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":3,"enunciado":"A busca semântica depende de que o usuário empregue exatamente as mesmas palavras presentes no documento procurado.","gabarito":"E","explicacao":"Essa é a limitação da busca léxica. A semântica recupera por proximidade de significado, independentemente da coincidência de palavras.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E IA no Parlamento)","mastigado":"Errado. Exigir as mesmas palavras do documento é a limitação da busca comum, que procura palavras iguais. A busca semântica procura por sentido parecido, então encontra o documento mesmo que as palavras sejam outras.","teSitua":{"termos":[{"termo":"busca semântica","significado":"forma de pesquisa que encontra documentos pelo sentido do que foi pedido, mesmo que as palavras sejam diferentes."},{"termo":"usuário","significado":"a pessoa que usa o sistema ou o programa de computador."},{"termo":"exatamente as mesmas palavras","significado":"condição de repetir letra por letra os termos do documento; é característica da busca comum por palavras-chave."}],"exemplo":"A servidora Eliane digitou 'dispensa de licitação' na busca do portal. O sistema semântico trouxe também um documento que usava 'contratação direta', pois o sentido é próximo. Uma busca comum, que exige as mesmas palavras, não o teria achado."}},{"id":"aut.transcricao_ia.busca_semantica.0003","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":3,"enunciado":"A indexação automática e a classificação temática de proposições são exemplos de aplicação de inteligência artificial em parlamentos.","gabarito":"C","explicacao":"Somam-se à transcrição, à sumarização, à busca semântica, à legendagem e ao apoio à acessibilidade.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E IA no Parlamento)","mastigado":"Certo. Organizar automaticamente documentos por assunto e classificar projetos por tema são usos de inteligência artificial em parlamentos. Também se usam a transcrição de falas, resumos, busca por sentido, legendas e acessibilidade.","teSitua":{"termos":[{"termo":"indexação automática","significado":"organização de documentos por programa de computador, que cria um índice de assuntos para facilitar a busca."},{"termo":"classificação temática","significado":"ato de separar textos em grupos por assunto, como saúde, educação ou segurança."},{"termo":"proposições","significado":"textos apresentados no Legislativo para debate e votação, como projetos de lei e emendas."},{"termo":"parlamentos","significado":"órgãos legislativos de um país ou estado, como Câmara e Senado."}],"exemplo":"A Câmara dos Deputados recebe milhares de projetos de lei. Um sistema de IA lê cada proposição e a classifica por tema, como saúde ou transporte, para que o servidor Lucas encontre rapidamente tudo o que se relaciona a um assunto. Isso é indexação automática."}},{"id":"aut.transcricao_ia.cat_vocabulario.0001","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"A adaptação do modelo de linguagem com textos do domínio parlamentar tende a melhorar o reconhecimento de termos pouco frequentes em dados genéricos, como siglas, nomes próprios e expressões regimentais.","gabarito":"C","explicacao":"Ao treinar ou ajustar o modelo com textos do Parlamento, esses termos passam a receber maior probabilidade, o que tende a reduzir o WER no domínio. A adaptação não elimina a necessidade de revisão humana.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Certo. Quando se ajusta o modelo com textos do Parlamento, ele passa a conhecer melhor siglas, nomes e expressões do dia a dia da casa. Palavras raras em textos gerais ficam mais prováveis, e os erros diminuem. Mesmo assim, ainda é preciso revisão humana.","teSitua":{"termos":[{"termo":"adaptação do modelo de linguagem","significado":"ajuste do modelo com textos de uma área específica para que reconheça melhor os termos daquele assunto."},{"termo":"domínio parlamentar","significado":"área de assunto do Parlamento, com seu vocabulário e seus tipos de documentos."},{"termo":"expressões regimentais","significado":"expressões ligadas ao regimento interno, como 'questão de ordem' e 'pedido de vista'."},{"termo":"dados genéricos","significado":"textos variados e sem foco em uma área, em geral usados para treinar modelos de uso amplo."}],"exemplo":"A equipe técnica do Senado ajustou o modelo com atas e discursos antigos. Antes, ele escrevia 'questão de ordem' como 'questão de horda'. Depois da adaptação ao domínio parlamentar, passou a acertar, e a revisora Luciana viu menos erros em siglas e nomes."}},{"id":"aut.transcricao_ia.cat_vocabulario.0002","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"O vocabulário personalizado exige sempre o retreinamento completo do modelo de reconhecimento e elimina, por si só, os erros de transcrição de nomes próprios e siglas.","gabarito":"E","explicacao":"O vocabulário personalizado é uma lista de termos e frases do domínio que aumenta a chance de reconhecimento, em geral sem retreinar o modelo. Não garante acerto, e a revisão humana continua necessária. O modelo adaptado é que envolve treinamento com texto ou áudio do domínio.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Errado. O vocabulário personalizado é só uma lista de termos e frases que ajuda o sistema a acertar mais, em geral sem treinar o modelo de novo. Ele não garante acerto, nem acaba com os erros em nomes e siglas. Revisar continua necessário.","teSitua":{"termos":[{"termo":"vocabulário personalizado","significado":"lista de palavras e frases de uma área, fornecida ao sistema para aumentar a chance de ele reconhecê-las."},{"termo":"retreinamento completo","significado":"treinar o modelo de novo desde o início ou em grande parte, o que é caro e demorado."},{"termo":"modelo de reconhecimento","significado":"programa que converte a fala em texto, aprendido a partir de muitos exemplos de áudio."},{"termo":"siglas","significado":"abreviações formadas pelas letras iniciais de nomes, como CCJ ou PEC."}],"exemplo":"A analista Marília enviou ao sistema uma lista com 'CCJ', 'PEC' e os nomes dos deputados da casa. Não foi preciso treinar nada de novo, e o programa passou a acertar mais. Mas ainda errou um sobrenome raro, e a revisora Camila teve de corrigi-lo."}},{"id":"aut.transcricao_ia.diarizacao.0001","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A diarização de falantes consiste em determinar quem falou e quando, atribuindo rótulos aos segmentos de fala, sem que isso implique conhecer a identidade real de cada falante.","gabarito":"C","explicacao":"A saída da diarização são rótulos anônimos (Falante 1, Falante 2 etc.) associados a intervalos de tempo. Descobrir quem é a pessoa por trás do rótulo é outra tarefa (identificação de falante) ou depende de informação externa à diarização.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. A diarização responde 'quem falou e quando', dando etiquetas como Falante 1 e Falante 2 a cada trecho. Ela não descobre o nome da pessoa. Saber quem é a pessoa de verdade é outra tarefa.","teSitua":{"termos":[{"termo":"diarização de falantes","significado":"tarefa de dividir uma gravação em trechos e marcar qual pessoa falou em cada um, sem dizer quem ela é."},{"termo":"rótulos","significado":"etiquetas, como 'Falante 1' e 'Falante 2', colocadas em cada trecho da fala."},{"termo":"segmentos de fala","significado":"trechos do áudio em que uma mesma pessoa fala sem pausa longa."},{"termo":"identidade real","significado":"o nome verdadeiro de quem fala, que a diarização, sozinha, não descobre."}],"exemplo":"Numa audiência gravada, o sistema marcou 'Falante 1' de 0 a 30 segundos, 'Falante 2' de 30 a 45, e voltou ao 'Falante 1'. O técnico Ivan viu que sabia quem falava e quando, mas não o nome das pessoas. Para isso, seria preciso outra etapa."}},{"id":"aut.transcricao_ia.diarizacao.0002","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A diarização de falantes tem por finalidade confirmar, a partir de modelo de voz previamente cadastrado, a identidade de um parlamentar; a identificação de falante, por sua vez, apenas agrupa as falas em rótulos anônimos.","gabarito":"E","explicacao":"Inversão de conceitos próximos. A diarização agrupa as falas em rótulos anônimos (quem falou quando); a identificação de falante compara a voz com modelos cadastrados para dizer quem é a pessoa.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. Os conceitos estão trocados. A diarização separa as falas em etiquetas anônimas, sem saber quem são. Já a identificação de falante compara a voz com vozes cadastradas para dizer quem é a pessoa.","teSitua":{"termos":[{"termo":"diarização de falantes","significado":"tarefa de dividir uma gravação em trechos e marcar quais foram falados pela mesma pessoa, sem dizer quem ela é."},{"termo":"modelo de voz","significado":"perfil digital de uma voz, usado para reconhecer a pessoa em novas gravações."},{"termo":"identificação de falante","significado":"tarefa de comparar uma voz com modelos cadastrados para descobrir quem é a pessoa."},{"termo":"rótulos anônimos","significado":"etiquetas sem nome, como 'Falante 1', que só separam as vozes."}],"exemplo":"A servidora Vanessa mostrou dois relatórios. No primeiro, a diarização rotulou trechos como 'Falante 1' e 'Falante 2', sem nomes. No segundo, a identificação de falante comparou a voz com as cadastradas e escreveu 'Deputada Rosa'. A prova trocou as duas funções."}},{"id":"aut.transcricao_ia.diarizacao.0003","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na diarização em tempo real, o sistema precisa atribuir o falante sem conhecer o áudio futuro, o que tende a torná-la menos precisa do que a diarização feita sobre a gravação completa.","gabarito":"C","explicacao":"Na diarização offline, o agrupamento pode considerar todo o áudio; na diarização online, a decisão é incremental e baseada apenas no que já foi ouvido. Esse é o compromisso entre latência e precisão, comum ao ASR em fluxo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. Em tempo real, o sistema precisa decidir quem fala sem saber o que virá depois. Na gravação completa, ele pode olhar todo o áudio e decidir melhor. Por isso, em geral, a diarização ao vivo é menos precisa.","teSitua":{"termos":[{"termo":"diarização em tempo real","significado":"marcação de quem fala feita enquanto a sessão acontece, sem esperar o fim da gravação."},{"termo":"áudio futuro","significado":"a parte da gravação que ainda não foi falada e, portanto, não está disponível para análise."},{"termo":"gravação completa","significado":"o arquivo de áudio inteiro, já terminado, que permite analisar todo o conteúdo de uma vez."}],"exemplo":"Durante a sessão ao vivo, o sistema precisava dizer na hora quem falava e errava ao começar um novo discurso. Depois, com a gravação completa, o analista Cleiton reprocessou e acertou mais, pois o programa conseguiu ouvir todo o áudio antes de decidir."}},{"id":"aut.transcricao_ia.diarizacao.0004","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Nenhuma abordagem de diarização é capaz de atribuir mais de um falante ao mesmo instante; por isso, a sobreposição de falas sempre se resolve com a escolha de um único rótulo por trecho.","gabarito":"E","explicacao":"Generalização indevida. Sistemas clássicos, com um rótulo por trecho, têm essa limitação, mas abordagens neurais mais recentes tratam a sobreposição, atribuindo mais de um falante ao mesmo intervalo de tempo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. 'Nenhuma abordagem' e 'sempre' tornam a frase falsa. Sistemas mais antigos dão um único rótulo por trecho, mas os mais novos, com redes neurais, conseguem tratar a sobreposição e marcar dois falantes ao mesmo tempo.","teSitua":{"termos":[{"termo":"diarização de falantes","significado":"tarefa de dividir uma gravação em trechos e marcar quais foram falados pela mesma pessoa."},{"termo":"sobreposição de falas","significado":"situação em que duas pessoas falam ao mesmo tempo, o que dificulta separar as vozes."},{"termo":"rótulo","significado":"etiqueta, como 'Falante 1', colocada em um trecho de fala para indicar quem falou."}],"exemplo":"Na votação, o deputado Nélson e a deputada Cléo falaram ao mesmo tempo. O sistema antigo escolheu só um rótulo para o trecho. Já o novo sistema neural, testado pela analista Ruth, marcou os dois falantes naquele intervalo, mostrando que a frase 'nenhuma abordagem' estava errada."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0001","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"O uso de ferramenta de inteligência artificial para gerar o resumo de uma sessão dispensa a indicação de que o conteúdo foi produzido com apoio automatizado, desde que haja revisão posterior.","gabarito":"E","explicacao":"A revisão não afasta o dever de transparência. A boa prática recomenda informar o emprego da ferramenta, sobretudo em conteúdo oficial.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Ética no Uso de IA)","mastigado":"Errado. Revisar o resumo não elimina o dever de transparência. A boa prática é avisar que o conteúdo foi feito com apoio de uma ferramenta automatizada, principalmente em material oficial.","teSitua":{"termos":[{"termo":"inteligência artificial","significado":"tecnologia que faz computadores realizarem tarefas que exigem raciocínio, como resumir textos."},{"termo":"apoio automatizado","significado":"ajuda de um programa que trabalha sozinho, sem intervenção humana a cada passo."},{"termo":"revisão posterior","significado":"conferência feita por uma pessoa depois que o conteúdo foi produzido."}],"exemplo":"A assessoria da Assembleia usou uma ferramenta de IA para resumir a sessão, e o redator Luiz revisou o texto. Mesmo assim, a chefe Beatriz mandou incluir no rodapé que o resumo foi feito com apoio de IA. A revisão não afasta o dever de avisar."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0002","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"A legislação autoral brasileira protege, de forma expressa e automática, as obras integralmente geradas por sistemas de inteligência artificial, sem participação criativa humana.","gabarito":"E","explicacao":"A tutela autoral pressupõe criação do espírito humano. Não há, no ordenamento, proteção automática e expressa para obra inteiramente gerada por máquina.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Ética no Uso de IA)","mastigado":"Errado. A proteção de direito autoral pressupõe uma criação humana. Uma obra feita inteiramente por máquina, sem participação criativa de uma pessoa, não tem proteção automática e expressa na lei brasileira.","teSitua":{"termos":[{"termo":"legislação autoral","significado":"conjunto de leis que protege os direitos de quem cria obras, como textos, músicas e imagens."},{"termo":"obras integralmente geradas","significado":"criações produzidas totalmente por um programa, sem ajuda criativa de uma pessoa."},{"termo":"participação criativa humana","significado":"contribuição de uma pessoa na criação, com ideias, escolhas e trabalho próprios."}],"exemplo":"A artista Pâmela pediu a uma IA que gerasse uma imagem, sem dar nenhuma orientação criativa. Quando quis registrar a obra, o advogado Flávio explicou que a lei autoral pressupõe uma criação humana. Uma obra feita inteiramente por máquina não tem proteção automática."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0003","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"O desenho com humano no circuito pressupõe revisão e validação humanas efetivas antes da publicação do conteúdo produzido pelo sistema.","gabarito":"C","explicacao":"É exatamente o que caracteriza o modelo e o diferencia da automação plena.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Ética no Uso de IA)","mastigado":"Certo. Humano no circuito quer dizer que uma pessoa realmente confere e valida o que o sistema produziu antes da publicação. É isso que o diferencia de uma automação completa, em que ninguém olha antes de publicar.","teSitua":{"termos":[{"termo":"humano no circuito","significado":"modelo de trabalho em que uma pessoa participa do processo, conferindo e aprovando o que o sistema produz."},{"termo":"validação","significado":"aprovação formal de um conteúdo depois de conferido, para que possa ser usado ou publicado."},{"termo":"revisão","significado":"conferência feita por uma pessoa para corrigir erros e aprovar o conteúdo antes de ele ser usado."}],"exemplo":"O portal da Câmara usa IA para transcrever sessões, mas a revisora Sônia lê e valida cada texto antes de publicar. É o desenho com humano no circuito. Se o texto fosse publicado direto, sem ninguém conferir, seria automação plena."}},{"id":"aut.transcricao_ia.ferramentas_apis.0001","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, é um modelo de reconhecimento de fala de código aberto, treinado com grande volume de dados multilíngues e multitarefa, capaz de transcrever em vários idiomas, traduzir para o inglês e identificar o idioma falado.","gabarito":"C","explicacao":"Código e pesos são distribuídos sob licença MIT. O treinamento supervisionado usou cerca de 680 mil horas de áudio multilíngue e multitarefa, o que sustenta as tarefas de transcrição, tradução para o inglês e identificação de idioma.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. O Whisper é um modelo aberto de reconhecimento de fala, treinado com muito áudio em vários idiomas e tarefas. Ele transcreve em vários idiomas, traduz para o inglês e descobre qual idioma está sendo falado.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala criado pela OpenAI, de código aberto, que transcreve áudio em vários idiomas."},{"termo":"código aberto","significado":"software cujo código pode ser visto, baixado, usado e modificado livremente por qualquer pessoa."},{"termo":"multilíngues","significado":"que reúnem ou funcionam em vários idiomas."},{"termo":"multitarefa","significado":"que aprende a fazer várias tarefas ao mesmo tempo, como transcrever, traduzir e reconhecer o idioma."}],"exemplo":"A pesquisadora Natália baixou o Whisper e testou em três áudios: um em português, que ele transcreveu, um em francês, que ele traduziu para o inglês, e um sem informação, em que ele identificou o idioma falado. Como é de código aberto, rodou no próprio computador."}},{"id":"aut.transcricao_ia.ferramentas_apis.0002","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper é um modelo proprietário da OpenAI, disponível exclusivamente por meio de API paga, sem possibilidade de execução local.","gabarito":"E","explicacao":"O Whisper é de código aberto (código e pesos sob licença MIT) e pode ser executado localmente. A API da OpenAI, com o modelo whisper-1, é apenas uma das formas de acesso.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. O Whisper é de código aberto, ou seja, qualquer pessoa pode baixar e rodar no próprio computador. A API paga da OpenAI é só uma das formas de usá-lo, e não a única.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala criado pela OpenAI, de código aberto, que transcreve áudio em vários idiomas."},{"termo":"modelo proprietário","significado":"programa cujo código pertence a uma empresa e não pode ser visto nem usado livremente."},{"termo":"API paga","significado":"serviço pelo qual um programa acessa recursos de outra empresa pela internet, mediante pagamento."},{"termo":"execução local","significado":"uso do programa no computador da própria pessoa, sem depender da internet ou de servidor externo."}],"exemplo":"O analista Sílvio achou que precisava pagar pela API da OpenAI para usar o Whisper. A colega Marta mostrou que o modelo é aberto: ela baixou o programa e o executou no próprio notebook, sem pagar nada. A API paga era só uma das formas de acesso."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0001","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"A transcrição automática é a saída bruta de um sistema de ASR, ao passo que a degravação é a passagem do registro oral para o texto escrito segundo as convenções do órgão.","gabarito":"C","explicacao":"A saída do ASR não passa por tratamento editorial. A degravação envolve identificação de oradores, normas de grafia e tratamento da oralidade, e depende de revisão humana para ser concluída.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Certo. A transcrição automática é o texto bruto que sai do sistema, sem tratamento. A degravação é passar a fala para o texto escrito seguindo as regras do órgão, como identificar quem fala e tratar a linguagem falada. Ela precisa de revisão humana.","teSitua":{"termos":[{"termo":"transcrição automática","significado":"conversão de áudio em texto escrito feita por programa, sem tratamento editorial."},{"termo":"saída bruta","significado":"resultado imediato do sistema, sem revisão nem ajuste."},{"termo":"degravação","significado":"passagem da fala gravada para o texto escrito, seguindo as regras do órgão e revisada por pessoa."},{"termo":"convenções do órgão","significado":"regras próprias de uma instituição para escrever e formatar seus textos."}],"exemplo":"O sistema da Assembleia gerou um texto corrido sem pontuação nem nomes, a saída bruta. A revisora Sueli fez a degravação: identificou os oradores, ajustou a grafia das siglas e tratou as hesitações, tudo conforme o manual do órgão."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0002","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"A degravação é a saída bruta do sistema de ASR, enquanto a transcrição automática é a versão revisada e formatada segundo as convenções do órgão.","gabarito":"E","explicacao":"Inversão de conceitos próximos. A transcrição automática é a saída bruta do sistema; a degravação é a passagem do registro oral para o texto escrito conforme as convenções do órgão, com revisão humana.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Errado. Os conceitos estão invertidos. A transcrição automática é o texto bruto do sistema. A degravação é a versão feita seguindo as regras do órgão e revisada por uma pessoa.","teSitua":{"termos":[{"termo":"degravação","significado":"passagem da fala gravada para o texto escrito, seguindo as regras do órgão e revisada por pessoa."},{"termo":"saída bruta","significado":"resultado imediato do sistema, sem revisão nem ajuste."},{"termo":"sistema de ASR","significado":"programa de reconhecimento automático de fala, que transforma voz em texto."},{"termo":"convenções do órgão","significado":"regras próprias de uma instituição para escrever e formatar seus textos."}],"exemplo":"O estagiário Wagner achou que a degravação era o texto direto do sistema. A chefe Márcia corrigiu: o que sai do ASR é a transcrição automática, bruta. A degravação é a versão revisada por uma pessoa e formatada conforme as regras do órgão."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0003","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"A revisão de uma transcrição deve preservar o sentido do que foi dito pelo orador, podendo tratar vícios de linguagem e repetições sem função que não alterem o conteúdo.","gabarito":"C","explicacao":"A fidelidade é ao conteúdo e ao registro do orador. Hesitações e repetições sem função são ruído da oralidade; já repetições com efeito retórico ou de sentido devem ser mantidas.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Certo. Quem revisa deve manter o sentido do que o orador disse. Pode limpar vícios de linguagem e repetições sem função, que são só ruído da fala. Repetições que servem para dar ênfase ou mudar o sentido devem ficar.","teSitua":{"termos":[{"termo":"revisão de uma transcrição","significado":"conferência do texto com o áudio para corrigir erros e ajustar a forma, sem mudar o que foi dito."},{"termo":"orador","significado":"pessoa que discursa ou fala em público; aqui, o parlamentar que faz o discurso."},{"termo":"vícios de linguagem","significado":"palavras ou expressões repetidas sem necessidade na fala, como 'né', 'tipo' e 'então' em excesso."},{"termo":"repetições sem função","significado":"palavras ou frases repetidas sem objetivo, que são só marca da fala espontânea."}],"exemplo":"O deputado Antero disse: 'Então, né, o projeto, o projeto é importante'. A revisora Cacilda tirou o 'né' e a repetição sem função, mantendo o sentido. Mas deixou 'nunca, nunca' em outra frase, porque a repetição era para dar ênfase."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0004","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"A marcação de apartes em transcrição parlamentar é dispensável, pois a fala do aparteante pode ser incorporada ao discurso do orador sem identificação.","gabarito":"E","explicacao":"Sem a identificação, atribui-se ao orador o que foi dito por outro parlamentar, o que compromete a fidelidade. A identificação de oradores e a marcação de apartes integram a formatação de transcrições parlamentares.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Errado. Se o aparte não for marcado, o que outro parlamentar disse parece ter sido falado pelo orador. Isso prejudica a fidelidade. Identificar quem fala e marcar os apartes faz parte da formatação da transcrição parlamentar.","teSitua":{"termos":[{"termo":"apartes","significado":"interrupções autorizadas em que um parlamentar fala durante o discurso de outro."},{"termo":"transcrição parlamentar","significado":"texto escrito feito a partir da gravação de sessões do Legislativo."},{"termo":"aparteante","significado":"o parlamentar que faz o aparte, ou seja, quem interrompe o orador com autorização para falar."},{"termo":"orador","significado":"pessoa que discursa ou fala em público; aqui, o parlamentar que tem a palavra."}],"exemplo":"Durante o discurso do deputado Nilton, a deputada Fátima fez um aparte e criticou o projeto. O revisor Gilmar não marcou a troca, e o texto parecia dizer que Nilton criticava o próprio projeto. A chefe Clarice mandou refazer, identificando quem falou."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0005","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"O pedal é o único meio de controlar a reprodução do áudio nos editores de transcrição, pois os atalhos de teclado não permitem pausar nem retroceder o áudio.","gabarito":"E","explicacao":"Generalização indevida. Os atalhos de teclado permitem tocar, pausar e voltar o áudio; o pedal é recurso complementar, que comanda a reprodução com os pés e mantém as mãos livres para digitar.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Errado. O pedal não é o único meio. Os atalhos do teclado também tocam, pausam e voltam o áudio. O pedal é um complemento, pois deixa as mãos livres para digitar enquanto os pés controlam a gravação.","teSitua":{"termos":[{"termo":"pedal","significado":"dispositivo acionado com o pé para tocar, pausar e voltar o áudio, deixando as mãos livres para digitar."},{"termo":"editores de transcrição","significado":"programas usados para ouvir e escrever o texto de uma gravação ao mesmo tempo."},{"termo":"atalhos de teclado","significado":"combinações de teclas que executam comandos rápidos, como pausar ou retroceder."}],"exemplo":"A degravadora Nice usa um pedal para pausar e voltar o áudio, deixando as mãos no teclado. O estagiário Caio não tinha pedal e usou os atalhos de teclado. Funcionou do mesmo jeito: o pedal é só um recurso complementar."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0006","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"A qualidade da captação do áudio, como a adequação dos microfones e o controle de ruído de ambiente, influencia diretamente a precisão da transcrição automática e, por consequência, o esforço de revisão.","gabarito":"C","explicacao":"A captura do áudio é a primeira etapa do fluxo. Ruído, microfone distante e sobreposição de vozes degradam o reconhecimento, e cada erro do sistema vira trabalho para a revisão humana.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Certo. Quanto melhor o som captado, melhor a transcrição automática. Microfone ruim, barulho e vozes sobrepostas fazem o sistema errar mais, e cada erro vira mais trabalho de revisão.","teSitua":{"termos":[{"termo":"captação do áudio","significado":"etapa de gravar o som de uma fala, usando microfones e equipamentos."},{"termo":"controle de ruído de ambiente","significado":"medidas para reduzir barulhos ao redor, como conversas, ventiladores ou eco."},{"termo":"transcrição automática","significado":"conversão de áudio em texto escrito feita por programa."},{"termo":"esforço de revisão","significado":"tempo e trabalho que uma pessoa precisa gastar para corrigir o texto."}],"exemplo":"Na sessão de terça, o microfone ficou longe do orador e havia ruído. O sistema errou muitas palavras, e o revisor Tales gastou horas corrigindo. Na quarta, com bom microfone e silêncio, o texto veio quase certo e a revisão foi rápida."}},{"id":"aut.transcricao_ia.human_in_the_loop.0001","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":3,"enunciado":"Em um fluxo assistido por IA com humano no circuito, a transcrição automática é conferida e corrigida por pessoa antes da validação do texto final.","gabarito":"C","explicacao":"As etapas são captura do áudio, transcrição automática, revisão, edição e validação. A revisão confere o texto com o áudio, e a validação final cabe a pessoa responsável, não ao sistema.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Certo. Nesse fluxo, o sistema transcreve e uma pessoa confere o texto com o áudio e corrige antes de dar o texto por pronto. A validação final é de gente, e não da máquina.","teSitua":{"termos":[{"termo":"humano no circuito","significado":"modelo de trabalho em que uma pessoa participa do processo, conferindo e aprovando o que o sistema produz."},{"termo":"fluxo assistido por IA","significado":"sequência de etapas de trabalho em que a inteligência artificial ajuda, mas não faz tudo sozinha."},{"termo":"transcrição automática","significado":"conversão de áudio em texto escrito feita por programa."},{"termo":"validação","significado":"aprovação formal do texto depois de conferido, liberando-o para uso ou publicação."}],"exemplo":"No Tribunal de Contas, o sistema transcreve a sessão. A revisora Patrícia confere o texto com o áudio, corrige nomes e números e, só depois, valida o documento final. Isso é um fluxo com humano no circuito, em que a decisão final é de uma pessoa."}},{"id":"aut.transcricao_ia.human_in_the_loop.0002","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":3,"enunciado":"Em fluxo com humano no circuito, a revisão pode ser dispensada sempre que o sistema de ASR apresentar pontuações de confiança elevadas, pois a validação do texto final é feita pelo próprio sistema.","gabarito":"E","explicacao":"Generalização indevida. A confiança do sistema não substitui a revisão: ela, no máximo, ajuda a priorizar o que conferir. A validação do texto final é etapa humana.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Errado. Mesmo quando o sistema mostra alta confiança, a revisão não pode ser dispensada. A confiança serve, no máximo, para ajudar a decidir o que conferir primeiro. A validação do texto final é sempre feita por uma pessoa.","teSitua":{"termos":[{"termo":"humano no circuito","significado":"modelo de trabalho em que uma pessoa participa do processo, conferindo e aprovando o que o sistema produz."},{"termo":"sistema de ASR","significado":"programa de reconhecimento automático de fala, que transforma voz em texto."},{"termo":"pontuações de confiança","significado":"notas que o sistema dá a si mesmo para indicar o quanto está seguro de cada palavra transcrita."},{"termo":"validação do texto final","significado":"aprovação final do documento, feita por uma pessoa responsável antes de sua publicação."}],"exemplo":"O sistema marcou 98% de confiança numa transcrição, e o estagiário Joel quis publicar sem revisar. A coordenadora Denise explicou que a confiança do sistema só ajuda a decidir o que conferir primeiro. A validação do texto final continua sendo uma etapa humana."}},{"id":"aut.transcricao_ia.ia_parlamentos.0001","subtopico":"transcricao_ia.ia_parlamento.ia_parlamentos","tipo":"certo_errado","dificuldade":3,"enunciado":"O emprego de ferramentas de inteligência artificial transfere ao sistema a responsabilidade pela fidelidade do registro oficial das sessões.","gabarito":"E","explicacao":"A ferramenta é apoio. A responsabilidade pela revisão e pela validação do registro permanece humana e institucional.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E IA no Parlamento)","mastigado":"Errado. A ferramenta é só um apoio. Quem continua responsável pela fidelidade do registro oficial das sessões são as pessoas e a instituição, que revisam e validam o resultado.","teSitua":{"termos":[{"termo":"inteligência artificial","significado":"tecnologia que faz computadores realizarem tarefas que exigem raciocínio, como transcrever e resumir."},{"termo":"fidelidade","significado":"qualidade de reproduzir com exatidão o que foi dito, sem acrescentar nem alterar."},{"termo":"registro oficial","significado":"documento que guarda, com valor institucional, o que foi dito e decidido em uma sessão."}],"exemplo":"A Câmara de Valença passou a usar IA para transcrever as sessões. Quando o texto saiu com uma frase trocada, o presidente Elias não culpou o programa: lembrou que a revisão e a validação do registro oficial são responsabilidade de pessoas da casa."}},{"id":"aut.transcricao_ia.lgpd_ia.0001","subtopico":"transcricao_ia.protecao_etica.lgpd_ia","tipo":"certo_errado","dificuldade":3,"enunciado":"O tratamento de dados pessoais pelo poder público para a execução de políticas públicas previstas em lei dispensa o consentimento do titular.","gabarito":"C","explicacao":"O consentimento é apenas uma das bases legais e não é a utilizada em regra pela Administração nessas hipóteses.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Proteção de Dados)","mastigado":"Certo. A lei de proteção de dados tem várias bases legais, e o consentimento é só uma delas. O poder público pode tratar dados pessoais para executar políticas públicas previstas em lei sem pedir o consentimento da pessoa.","teSitua":{"termos":[{"termo":"tratamento de dados pessoais","significado":"qualquer operação com informações de uma pessoa, como coletar, guardar, usar, compartilhar ou apagar."},{"termo":"poder público","significado":"conjunto de órgãos do governo, como prefeituras, ministérios, tribunais e casas legislativas."},{"termo":"políticas públicas","significado":"ações do governo para atender necessidades da população, como saúde, educação e segurança."},{"termo":"consentimento do titular","significado":"autorização dada pela pessoa a quem os dados se referem para que eles sejam usados."}],"exemplo":"A prefeitura de Betim usa o cadastro de moradores para distribuir uma vacina prevista em lei. A servidora Cecília perguntou se precisava pedir autorização a cada pessoa. O jurídico, Hélio, respondeu que, para executar política pública prevista em lei, o consentimento é dispensado."}},{"id":"aut.transcricao_ia.lgpd_ia.0002","subtopico":"transcricao_ia.protecao_etica.lgpd_ia","tipo":"certo_errado","dificuldade":3,"enunciado":"O dado pseudonimizado deixa de ser dado pessoal e sai do âmbito de aplicação da LGPD.","gabarito":"E","explicacao":"Quem sai do âmbito da lei, em regra, é o dado anonimizado. O pseudonimizado pode ser reassociado ao titular e continua protegido.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Proteção de Dados)","mastigado":"Errado. O dado pseudonimizado ainda pode ser ligado de volta à pessoa, então continua protegido pela lei. Em regra, quem sai do alcance da lei é o dado anonimizado, que não permite identificar ninguém.","teSitua":{"termos":[{"termo":"dado pseudonimizado","significado":"dado em que o nome foi trocado por um código, mas que pode ser religado à pessoa com informação guardada à parte."},{"termo":"dado pessoal","significado":"informação que identifica ou pode identificar uma pessoa, como nome, CPF ou endereço."},{"termo":"LGPD","significado":"Lei Geral de Proteção de Dados, que define as regras de uso de informações pessoais no Brasil."},{"termo":"âmbito de aplicação","significado":"campo de situações em que uma lei vale e deve ser obedecida."}],"exemplo":"O analista Danilo trocou os nomes de uma planilha por códigos, mas guardou a tabela que liga código e nome. A advogada Rafaela alertou: como ainda dá para voltar à pessoa, o dado é pseudonimizado e continua protegido pela LGPD. Só o dado anonimizado sairia da lei."}},{"id":"aut.transcricao_ia.lgpd_ia.0003","subtopico":"transcricao_ia.protecao_etica.lgpd_ia","tipo":"certo_errado","dificuldade":3,"enunciado":"Opinião política e convicção religiosa são classificadas pela LGPD como dados pessoais sensíveis.","gabarito":"C","explicacao":"Integram o rol do art. 5º, II, ao lado de origem racial ou étnica, filiação sindical, dado de saúde, vida sexual e dado genético ou biométrico.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Proteção de Dados)","mastigado":"Certo. A lei considera sensíveis os dados que podem gerar discriminação, e a opinião política e a convicção religiosa estão na lista. Também estão origem racial, saúde, vida sexual, dados genéticos ou biométricos e filiação a sindicato.","teSitua":{"termos":[{"termo":"LGPD","significado":"Lei Geral de Proteção de Dados, que define as regras de uso de informações pessoais no Brasil."},{"termo":"dados pessoais sensíveis","significado":"informações pessoais que podem gerar discriminação e exigem proteção maior, como saúde, religião e opinião política."},{"termo":"convicção religiosa","significado":"crença ou religião que uma pessoa professa."},{"termo":"opinião política","significado":"posicionamento de alguém sobre temas políticos, como partido ou candidato preferido."}],"exemplo":"A empresa Alfa recebeu o cadastro de uma entidade com a religião e o partido de cada associado. O encarregado de dados, Sérgio, avisou: religião e opinião política são dados sensíveis pela LGPD e exigem cuidado maior no tratamento."}},{"id":"aut.transcricao_ia.llms_audio.0001","subtopico":"transcricao_ia.reconhecimento_fala.llms_audio","tipo":"certo_errado","dificuldade":3,"enunciado":"Os LLMs multimodais de áudio nativo necessitam, obrigatoriamente, converter o áudio em texto por meio de um módulo de ASR independente antes de qualquer raciocínio sobre o conteúdo falado.","gabarito":"E","explicacao":"É justamente o contrário: o traço dos modelos de áudio nativo é processar o áudio diretamente, sem etapa separada de transcrição. A conversão prévia em texto caracteriza a arquitetura em cascata (ASR seguido de LLM).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. Os modelos de áudio nativo são justamente os que entendem o som direto, sem transformar tudo em texto antes. Converter primeiro o áudio em texto e só depois usar um modelo de linguagem é o sistema em cascata, que é outra arquitetura.","teSitua":{"termos":[{"termo":"LLMs multimodais","significado":"modelos de linguagem de grande porte que entendem mais de um tipo de conteúdo, como texto, áudio e imagem."},{"termo":"áudio nativo","significado":"capacidade de o modelo receber e entender o som diretamente, sem converter antes em texto."},{"termo":"módulo de ASR","significado":"parte separada do sistema que transforma voz em texto antes de o conteúdo passar para outro modelo."},{"termo":"raciocínio","significado":"capacidade de analisar informações e chegar a conclusões ou respostas."}],"exemplo":"A engenheira Taís testou dois sistemas com o mesmo áudio. O primeiro transcrevia em texto e depois mandava a um modelo, em cascata. O segundo, de áudio nativo, entendia o som direto, sem módulo de ASR. A afirmação da prova dizia o contrário."}},{"id":"aut.transcricao_ia.normalizacao.0001","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A normalização inversa de texto (ITN) converte a forma falada em forma escrita padronizada, como a passagem de \\"vinte por cento\\" para \\"20%\\".","gabarito":"C","explicacao":"A ITN é etapa de pós-processamento do ASR. A padronização final de números, siglas, datas, valores e termos técnicos segue o manual do órgão e é conferida na revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Certo. A normalização inversa transforma o que foi dito em forma escrita padrão. Por exemplo, 'vinte por cento' vira '20%'. É uma etapa feita depois da transcrição, e o resultado final segue o manual do órgão e é conferido na revisão.","teSitua":{"termos":[{"termo":"normalização inversa de texto","significado":"etapa que converte a forma falada de números, datas e valores na forma escrita padronizada."},{"termo":"ITN","significado":"sigla em inglês de normalização inversa de texto, a conversão da fala escrita por extenso para a forma padrão."},{"termo":"forma falada","significado":"maneira como algo é dito em voz alta, escrito por extenso, como 'vinte por cento'."},{"termo":"forma escrita padronizada","significado":"modo oficial de escrever algo conforme as regras de um manual, como '20%'."}],"exemplo":"O deputado Clóvis disse em plenário: 'O aumento foi de vinte por cento'. O sistema transcreveu por extenso. Na etapa de ITN, a revisora Neide converteu a expressão para '20%', seguindo o manual do órgão."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0001","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A pontuação e a capitalização do texto transcrito automaticamente podem ser obtidas por pós-processamento ou por modelos específicos, já que a fala, em si, não contém sinais de pontuação.","gabarito":"C","explicacao":"A pontuação é convenção da escrita; pausas e entonação não correspondem de forma exata a vírgulas e pontos. Por isso, muitos sistemas entregam texto sem pontuação ou com pontuação inserida automaticamente, que ainda precisa de revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. Quando falamos, não há vírgulas nem pontos; eles só existem na escrita. Por isso a pontuação e as letras maiúsculas em uma transcrição automática são colocadas depois, por um pós-processamento ou por modelos próprios.","teSitua":{"termos":[{"termo":"capitalização","significado":"uso de letras maiúsculas no início de frases e em nomes próprios."},{"termo":"pós-processamento","significado":"etapa feita depois da transcrição para ajustar o texto, como colocar pontuação e maiúsculas."},{"termo":"texto transcrito automaticamente","significado":"texto obtido da conversão de fala em escrita por um programa."},{"termo":"sinais de pontuação","significado":"símbolos como vírgula, ponto e interrogação, que organizam a escrita."}],"exemplo":"O sistema entregou o texto: 'senhor presidente peço a palavra'. Em seguida, um modelo de pós-processamento colocou maiúsculas e pontuação: 'Senhor Presidente, peço a palavra.' A estagiária Sibele notou que a fala não traz esses sinais, que são da escrita."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0002","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A pontuação inserida automaticamente por sistemas de ASR dispensa revisão humana, pois a pausa e a entonação da fala determinam de forma unívoca onde ficam as vírgulas e os pontos.","gabarito":"E","explicacao":"Generalização indevida. Pausas e entonação não correspondem de forma unívoca aos sinais de pontuação, e a pontuação automática pode alterar o sentido da frase. O resultado deve ser revisado por pessoa.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. Pausa e entonação da fala não indicam sempre onde vai uma vírgula ou um ponto. A pontuação automática pode até mudar o sentido da frase, por isso uma pessoa precisa revisar.","teSitua":{"termos":[{"termo":"pontuação","significado":"conjunto de sinais, como vírgulas e pontos, que organiza a escrita e dá sentido às frases."},{"termo":"sistemas de ASR","significado":"programas de reconhecimento automático de fala, que transformam voz em texto."},{"termo":"entonação","significado":"variação de tom da voz ao falar, que indica pergunta, afirmação ou ênfase."},{"termo":"unívoca","significado":"que tem um só sentido possível, sem margem para outra interpretação."}],"exemplo":"Em 'Não, quero ir', a vírgula muda tudo em relação a 'Não quero ir'. O sistema do assessor Reinaldo pontuou errado, e o sentido ficou trocado. A revisora Marlene mostrou que pausa e entonação não definem sozinhas onde vai a vírgula, e que a pontuação automática precisa de revisão."}},{"id":"aut.transcricao_ia.revisao_qualidade.0001","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Em respeito à correção gramatical, o revisor deve reescrever o discurso na norma culta formal, ainda que isso modifique o estilo e o registro do orador.","gabarito":"E","explicacao":"A correção gramatical ajusta deslizes sem descaracterizar a fala. O respeito ao registro do orador é critério de fidelidade e impede a uniformização que altere seu estilo e tom.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Errado. Corrigir a gramática é ajustar pequenos deslizes sem mudar a maneira de falar da pessoa. O revisor não deve reescrever tudo em língua formal, porque isso muda o estilo e o tom do orador, e quebra a fidelidade.","teSitua":{"termos":[{"termo":"correção gramatical","significado":"ajuste de erros de concordância, regência e ortografia, sem mudar o jeito de falar da pessoa."},{"termo":"revisor","significado":"pessoa que confere um texto e corrige erros antes da versão final."},{"termo":"norma culta formal","significado":"variedade da língua usada em textos formais, com regras estritas de gramática e vocabulário."},{"termo":"registro do orador","significado":"forma de falar de quem discursa, com seu vocabulário e seu tom."}],"exemplo":"O deputado Zeca falava de modo simples e direto. O revisor Anderson pensou em reescrever o discurso em linguagem rebuscada. A chefe Rosana não permitiu: corrigir a gramática não é trocar o estilo do orador, e a fidelidade ao registro dele deve ser respeitada."}},{"id":"aut.transcricao_ia.revisao_qualidade.0002","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Em trecho ininteligível da gravação, a transcrição deve registrar a indicação convencionada de inaudível, sem inserir palavras que o revisor apenas presume terem sido ditas.","gabarito":"C","explicacao":"Completar por conjectura atribui ao orador o que não se ouviu e fere a fidelidade. A marcação de trecho inaudível segue a convenção do órgão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Certo. Quando não dá para entender uma parte da gravação, a transcrição deve usar a marcação combinada para 'inaudível'. Não se deve completar com palavras que o revisor acha que foram ditas, pois isso atribui ao orador algo que não se ouviu.","teSitua":{"termos":[{"termo":"ininteligível","significado":"que não se consegue entender, por causa de ruído, voz baixa ou fala sobreposta."},{"termo":"inaudível","significado":"indicação usada no texto para marcar um trecho que não deu para ouvir."},{"termo":"convencionada","significado":"combinada de antemão por um órgão como padrão a ser seguido por todos."},{"termo":"presumem","significado":"supõem, acham que algo aconteceu ou foi dito, sem ter certeza."}],"exemplo":"Num trecho da gravação, a voz do vereador Osmar sumiu sob o barulho. A revisora Lúcia escreveu '[inaudível]', como manda a convenção da casa, em vez de adivinhar o que ele dissera. Assim, não atribuiu ao vereador uma frase que não se ouviu."}},{"id":"aut.transcricao_ia.revisao_qualidade.0003","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"O WER é calculado dividindo-se o número de erros (substituições, supressões e inserções) pelo número de palavras da transcrição gerada pelo sistema.","gabarito":"E","explicacao":"Troca do denominador. O divisor do WER é o número de palavras da referência (transcrição de comparação feita ou corrigida por pessoa), e não o da hipótese do sistema: WER = (S + D + I) / N.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Errado. Para calcular o WER, soma-se o número de erros e divide-se pelo número de palavras da referência, que é o texto de comparação feito ou corrigido por uma pessoa. A frase dividiu pelo texto gerado pelo sistema, e isso está errado.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavras, medida que compara a transcrição do sistema com um texto de referência."},{"termo":"substituições","significado":"erros em que o sistema escreve uma palavra no lugar de outra."},{"termo":"supressões","significado":"erros em que o sistema deixa de escrever uma palavra que foi dita."},{"termo":"inserções","significado":"erros em que o sistema escreve uma palavra que não foi dita."}],"exemplo":"A analista Heloísa comparou a transcrição do sistema com o texto corrigido por uma revisora. Encontrou 6 erros em 100 palavras do texto corrigido, e calculou 6% de WER. O colega Tadeu dividiu pelo texto do sistema e chegou a outro valor, errado."}},{"id":"aut.transcricao_ia.revisao_qualidade.0004","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Como as inserções não têm limite superior e o denominador do WER é o número de palavras da referência, o WER pode ultrapassar 100%.","gabarito":"C","explicacao":"Se o sistema inserir muitas palavras além das da referência, o numerador pode superar N. É uma das características que distinguem o WER de uma porcentagem de acertos.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Certo. O sistema pode inserir quantas palavras a mais quiser, então o número de erros pode passar do total de palavras da referência. Por isso o WER pode ser maior que 100%. Ele não é uma porcentagem de acertos.","teSitua":{"termos":[{"termo":"inserções","significado":"erros em que o sistema escreve palavras que não foram ditas, acrescentando texto a mais."},{"termo":"denominador","significado":"o número que fica embaixo na divisão; no WER, o total de palavras do texto de referência."},{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavras, medida que compara a transcrição do sistema com um texto de referência."},{"termo":"referência","significado":"texto correto, feito ou corrigido por pessoa, usado como comparação para medir a qualidade da transcrição."}],"exemplo":"O texto de referência tinha 10 palavras. O sistema do assessor Moacir, com defeito, escreveu 25 palavras, inserindo muitas. Contando 15 inserções e alguns outros erros, o WER passou de 100%. A professora Dulce explicou que isso é possível porque ele mede erros, e não acertos."}},{"id":"aut.transcricao_ia.revisao_qualidade.0005","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"O WER pondera cada erro pela gravidade para o sentido da frase, de modo que a troca de \\"aprovo\\" por \\"reprovo\\" pesa mais que a troca de um artigo.","gabarito":"E","explicacao":"O WER trata todos os erros com o mesmo peso: cada substituição, supressão ou inserção conta uma unidade, sem medir o impacto no sentido. Essa é uma de suas limitações como medida de qualidade.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Errado. O WER conta todos os erros do mesmo jeito: uma troca, uma falta ou um acréscimo vale um ponto. Trocar 'aprovo' por 'reprovo' pesa o mesmo que trocar um artigo, mesmo que mude o sentido. Essa é uma limitação dele.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavras, medida que compara a transcrição do sistema com um texto de referência."},{"termo":"pondera","significado":"dá pesos diferentes a cada item, conforme sua importância."},{"termo":"gravidade para o sentido","significado":"o tamanho do impacto de um erro na compreensão do que foi dito."},{"termo":"aprovo","significado":"forma do verbo aprovar, que indica concordância com algo, ao contrário de 'reprovo'."}],"exemplo":"Em dois testes, o sistema errou uma palavra em cada: trocou 'aprovo' por 'reprovo' no primeiro e 'o' por 'a' no segundo. O WER foi igual nos dois. A pesquisadora Lídia disse que isso é uma limitação: o WER não mede o impacto do erro no sentido."}},{"id":"aut.transcricao_ia.revisao_qualidade.0006","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"O CER, calculado no nível dos caracteres, é útil para evidenciar erros pequenos de grafia, como em nomes próprios e siglas, que no WER contam como erro de palavra inteira.","gabarito":"C","explicacao":"No WER, uma letra errada torna a palavra inteira errada; no CER, o erro tem peso proporcional ao número de caracteres afetados. Por isso o CER complementa o WER.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Certo. No WER, uma letra errada faz a palavra inteira contar como erro. No CER, o erro é medido por caracteres, então pesa menos quando só uma letra está errada. Por isso o CER ajuda a ver erros pequenos em nomes e siglas.","teSitua":{"termos":[{"termo":"CER","significado":"sigla em inglês de taxa de erro de caracteres, medida parecida com o WER, mas que conta letra por letra."},{"termo":"nível dos caracteres","significado":"forma de medir a qualidade letra por letra, em vez de palavra por palavra."},{"termo":"grafia","significado":"modo de escrever uma palavra, com as letras e acentos corretos."},{"termo":"siglas","significado":"abreviações formadas pelas letras iniciais de nomes, como CCJ ou PEC."}],"exemplo":"O sistema escreveu 'Bonifácio' como 'Bonifacio' e 'CCJ' como 'CCG'. No WER, cada palavra contou como errada inteira. No CER, o erro pesou só uma letra. O analista Rubens usou os dois indicadores para entender melhor o desempenho."}},{"id":"aut.transcricao_ia.revisao_qualidade.0007","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"O acordo de nível de serviço aplicado à produção de transcrições pode estabelecer metas mensuráveis, como prazo de entrega e nível mínimo de qualidade do texto entregue.","gabarito":"C","explicacao":"O SLA transforma expectativas em metas verificáveis. Na transcrição, combina-se a medição de prazo com indicadores de qualidade, como a taxa de erros apontados em auditoria ou o WER medido contra uma referência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Certo. O acordo de nível de serviço, ou SLA, coloca por escrito metas que podem ser medidas. Na transcrição, isso pode ser o prazo de entrega e um nível mínimo de qualidade do texto, medido, por exemplo, pela taxa de erros.","teSitua":{"termos":[{"termo":"acordo de nível de serviço","significado":"contrato ou cláusula que fixa metas mensuráveis para um serviço, como prazo e qualidade, também chamado SLA."},{"termo":"metas mensuráveis","significado":"objetivos que podem ser medidos com números, como entregar em 24 horas."},{"termo":"prazo de entrega","significado":"tempo máximo combinado para entregar o serviço contratado."},{"termo":"nível mínimo de qualidade","significado":"padrão abaixo do qual o serviço não pode ficar, como uma taxa máxima de erros."}],"exemplo":"A Câmara contratou a empresa Alfa para transcrever as sessões. No contrato, constava que o texto seria entregue em 24 horas e com no máximo 5% de erros. O fiscal do contrato, Joaquim, usou essas metas para cobrar a empresa quando houve atraso."}},{"id":"aut.transcricao_ia.revisao_qualidade.0008","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"A auditoria por amostragem exige a conferência integral de todos os textos produzidos, sob pena de não ser possível estimar a qualidade do conjunto.","gabarito":"E","explicacao":"Na amostragem, avalia-se apenas uma parte dos textos entregues, escolhida segundo critério definido, para estimar a qualidade do conjunto. A conferência de todos os textos seria revisão integral, não auditoria por amostragem.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Errado. Na auditoria por amostragem, confere-se só uma parte dos textos, escolhida por um critério, para estimar a qualidade do conjunto. Conferir todos os textos seria uma revisão total, e não amostragem.","teSitua":{"termos":[{"termo":"auditoria por amostragem","significado":"conferência de apenas uma parte dos itens, escolhida por um critério, para estimar a qualidade do conjunto todo."},{"termo":"conferência integral","significado":"verificação de todos os itens, um por um, sem deixar nenhum de fora."},{"termo":"estimar","significado":"calcular de forma aproximada, com base em uma parte das informações."}],"exemplo":"A coordenadora Vera recebeu 500 transcrições de uma empresa. Em vez de ler todas, sorteou 50 e conferiu cada uma, e concluiu que o lote tinha boa qualidade. Foi uma auditoria por amostragem. Se tivesse lido as 500, seria uma conferência integral."}},{"id":"aut.transcricao_ia.revisao_qualidade.0009","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Na revisão em dupla, o mesmo revisor confere duas vezes o próprio texto, o que assegura a independência da verificação.","gabarito":"E","explicacao":"A revisão em dupla (princípio dos quatro olhos) consiste na conferência por um segundo revisor. A independência decorre justamente de a verificação ser feita por pessoa diferente de quem produziu o texto.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Qualidade e Vocabulário)","mastigado":"Errado. Na revisão em dupla, quem confere é uma segunda pessoa, diferente de quem escreveu. É isso que garante a independência. Se a mesma pessoa conferisse duas vezes, ela repetiria os próprios vícios e erros.","teSitua":{"termos":[{"termo":"revisão em dupla","significado":"conferência em que duas pessoas diferentes participam: uma escreve e a outra confere o trabalho."},{"termo":"independência da verificação","significado":"garantia de que quem confere não é a mesma pessoa que produziu o texto."},{"termo":"revisor","significado":"pessoa que confere um texto e corrige erros antes de sua versão final."}],"exemplo":"O degravador Ítalo terminou o texto e o entregou à colega Sandra, que fez a revisão em dupla. Ela achou um número errado que ele não tinha visto. Se Ítalo revisasse o próprio texto duas vezes, provavelmente repetiria o mesmo descuido."}},{"id":"aut.transcricao_ia.seguranca_audio.0001","subtopico":"transcricao_ia.protecao_etica.seguranca_audio","tipo":"certo_errado","dificuldade":3,"enunciado":"A gravação da voz de um orador não configura dado pessoal, uma vez que se trata de manifestação pública em sessão.","gabarito":"E","explicacao":"O caráter público da sessão altera a base legal e o regime de publicidade, mas não retira da voz a condição de dado pessoal, já que permite identificar a pessoa natural.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Proteção de Dados)","mastigado":"Errado. A voz permite identificar uma pessoa, então é dado pessoal, mesmo que ela fale em uma sessão pública. O fato de ser público muda a base legal e a publicidade, mas não tira a proteção da voz como dado pessoal.","teSitua":{"termos":[{"termo":"dado pessoal","significado":"informação que identifica ou pode identificar uma pessoa, como nome, imagem ou voz."},{"termo":"orador","significado":"pessoa que discursa ou fala em público; aqui, o parlamentar que tem a palavra."},{"termo":"manifestação pública","significado":"fala feita de forma aberta, em evento ou sessão a que o público pode assistir."}],"exemplo":"A Câmara de Palmas gravava as sessões. A servidora Diana achou que a voz do vereador não precisava de cuidado por ser pública. O encarregado de dados, Vinícius, explicou que a voz permite identificar a pessoa e, por isso, continua sendo dado pessoal, mesmo em sessão aberta."}},{"id":"aut.transcricao_ia.seguranca_audio.0002","subtopico":"transcricao_ia.protecao_etica.seguranca_audio","tipo":"certo_errado","dificuldade":3,"enunciado":"A utilização de serviço de transcrição em nuvem dispensa a formalização de obrigações de segurança, desde que o fornecedor seja internacionalmente reconhecido.","gabarito":"E","explicacao":"A relação com o operador deve ser formalizada, com definição de finalidade, prazo, medidas de segurança e vedação de uso para fins não autorizados, independentemente da reputação do fornecedor.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Proteção de Dados)","mastigado":"Errado. Mesmo que o fornecedor seja muito conhecido, é preciso formalizar a relação, definindo para que os dados serão usados, por quanto tempo, quais medidas de segurança e a proibição de outros usos. A fama da empresa não substitui isso.","teSitua":{"termos":[{"termo":"serviço de transcrição em nuvem","significado":"serviço pela internet em que o áudio é enviado a servidores de uma empresa, que devolve o texto."},{"termo":"obrigações de segurança","significado":"deveres de proteger os dados contra acesso indevido, vazamento e uso não autorizado."},{"termo":"fornecedor","significado":"empresa que presta o serviço ou vende o produto contratado."},{"termo":"internacionalmente reconhecido","significado":"conhecido e respeitado em vários países, o que não substitui regras de segurança em contrato."}],"exemplo":"O tribunal pensou em usar uma empresa famosa de nuvem para transcrever audiências e achou que o contrato não precisava de cláusulas de segurança. A assessora jurídica Cármen discordou: a relação deve prever finalidade, prazo e medidas de proteção, não importa o nome da empresa."}},{"id":"aut.transcricao_ia.tempo_real.0001","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Por poder emitir saídas à medida que o áudio é recebido, o RNN-Transducer é adequado a cenários de transcrição em fluxo (streaming), como a transcrição ao vivo de sessões.","gabarito":"C","explicacao":"A estrutura do RNN-T permite decodificação incremental e de baixa latência, o que explica seu uso em reconhecimento em tempo real e em dispositivos. Já modelos com atenção sobre o áudio inteiro tendem a exigir adaptações para operar em fluxo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. O RNN-Transducer consegue escrever o texto aos poucos, conforme o áudio chega, sem esperar o fim da fala. Isso o torna bom para transcrever ao vivo uma sessão. Outros modelos, que precisam ver o áudio inteiro, exigem adaptações para isso.","teSitua":{"termos":[{"termo":"RNN-Transducer","significado":"tipo de modelo de reconhecimento de fala que gera o texto aos poucos, conforme o áudio chega."},{"termo":"à medida que","significado":"expressão que indica que duas coisas acontecem juntas, uma acompanhando a outra."},{"termo":"fluxo (streaming)","significado":"transmissão contínua de dados, na qual o conteúdo é processado enquanto chega, sem esperar o arquivo completo."},{"termo":"transcrição ao vivo","significado":"conversão da fala em texto enquanto a sessão acontece."}],"exemplo":"Na sessão plenária, o telão exibia a legenda do que o deputado dizia, quase na hora. O engenheiro Ênio explicou que o sistema usava um RNN-Transducer, que escreve conforme o áudio chega, sem esperar o discurso terminar. Isso é transcrição em fluxo."}},{"id":"aut.transcricao_ia.tempo_real.0002","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Um modelo de ASR causal usa apenas o áudio passado e o presente, o que o torna adequado à transcrição em tempo real, mas tende a lhe custar precisão em relação a um modelo que enxerga o áudio inteiro.","gabarito":"C","explicacao":"Modelo causal não usa contexto futuro, requisito para baixa latência. A menor quantidade de informação disponível costuma custar precisão, daí o compromisso entre latência e acurácia na transcrição em fluxo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. Um modelo causal só usa o que já foi dito, nunca o que virá depois. Isso permite transcrever em tempo real, mas ele tende a errar mais do que um modelo que analisa o áudio inteiro. É a troca entre rapidez e precisão.","teSitua":{"termos":[{"termo":"modelo de ASR causal","significado":"modelo de reconhecimento de fala que usa só o que já foi dito, sem olhar o que virá depois."},{"termo":"transcrição em tempo real","significado":"conversão da fala em texto enquanto ela acontece, com atraso mínimo."},{"termo":"precisão","significado":"grau de acerto do resultado em relação ao correto."},{"termo":"enxerga o áudio inteiro","significado":"usa também o que vem depois de cada trecho para decidir o que foi dito, o que melhora o acerto."}],"exemplo":"A TV Câmara queria legendas ao vivo. O modelo causal da engenheira Ana só usava o que já fora dito, e saía rápido, mas errava algumas palavras. Para a versão final, o modelo que analisa a gravação inteira acertou mais, só que demorou."}},{"id":"aut.transcricao_ia.tempo_real.0003","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Na transcrição em lote, o áudio é processado continuamente enquanto a fala ocorre, com emissão de resultados parciais; na transcrição em tempo real, o arquivo completo é processado depois, de forma assíncrona.","gabarito":"E","explicacao":"Inversão de conceitos. É a transcrição em tempo real (streaming) que processa o áudio enquanto a fala ocorre, com resultados parciais; a transcrição em lote processa o arquivo completo, de forma assíncrona.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. A frase trocou os conceitos. Quem processa o áudio enquanto a fala acontece, mostrando resultados parciais, é a transcrição em tempo real. A em lote recebe o arquivo completo e processa depois, sem pressa.","teSitua":{"termos":[{"termo":"transcrição em lote","significado":"processamento de arquivos de áudio já gravados, em grupo, sem a necessidade de resultado imediato."},{"termo":"resultados parciais","significado":"textos provisórios que o sistema vai mostrando e podendo corrigir enquanto a fala continua."},{"termo":"tempo real","significado":"forma de processar os dados no momento em que são gerados, quase sem atraso."},{"termo":"assíncrona","significado":"que não precisa de resposta na hora; o resultado fica pronto depois."}],"exemplo":"Na sessão de segunda, o telão do plenário mostrava a legenda quase na hora, com resultados parciais: era transcrição em tempo real. À noite, a secretaria enviou o arquivo inteiro da gravação e recebeu o texto pronto na manhã seguinte. Isso foi transcrição em lote, assíncrona."}},{"id":"aut.transcricao_ia.tempo_real.0004","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, o reconhecimento síncrono admite áudios de até 480 minutos, enquanto o reconhecimento assíncrono se limita a áudios de até 1 minuto.","gabarito":"E","explicacao":"Troca de números. Segundo a documentação do Google, o reconhecimento síncrono processa áudio de 1 minuto ou menos; o assíncrono admite áudio de qualquer duração até 480 minutos; o streaming é voltado ao tempo real.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. Os números estão trocados. No Google, o reconhecimento síncrono é para áudios de até 1 minuto, e o assíncrono aceita áudios longos, de até 480 minutos. A frase inverteu isso.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço de nuvem do Google que converte áudio em texto."},{"termo":"reconhecimento síncrono","significado":"modo em que o áudio é enviado e a resposta volta na hora, em geral para áudios curtos."},{"termo":"reconhecimento assíncrono","significado":"modo em que o áudio é enviado e o resultado fica pronto depois, usado para áudios longos."}],"exemplo":"O analista Plínio tinha um áudio de 2 horas de uma audiência. Tentou o modo síncrono e o sistema recusou, pois ele aceita só até 1 minuto. Usou o modo assíncrono, que aceita áudios longos, e recebeu a transcrição depois."}},{"id":"aut.transcricao_ia.tempo_real.0005","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Azure AI Speech, a transcrição em tempo real devolve resultados intermediários para áudio ao vivo, enquanto a transcrição em lote processa de forma assíncrona grandes volumes de áudio armazenados em arquivos.","gabarito":"C","explicacao":"A documentação distingue três modos: tempo real (resultados intermediários para áudio ao vivo), transcrição rápida (arquivos, resposta síncrona e mais rápida que o tempo real) e lote (processamento assíncrono de grandes volumes de arquivos).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Certo. No Azure, a transcrição em tempo real vai devolvendo resultados enquanto o áudio é falado ao vivo. A transcrição em lote cuida de muitos arquivos de áudio já guardados, de forma assíncrona, sem esperar ali na hora.","teSitua":{"termos":[{"termo":"Azure AI Speech","significado":"serviço de nuvem da Microsoft que converte voz em texto e faz outras tarefas com áudio."},{"termo":"resultados intermediários","significado":"textos provisórios que o sistema entrega enquanto a fala ainda acontece e que podem ser corrigidos depois."},{"termo":"transcrição em lote","significado":"processamento de muitos arquivos de áudio já gravados, de uma vez, sem a necessidade de resultado imediato."},{"termo":"assíncrona","significado":"que não precisa de resposta na hora; o resultado fica pronto depois."}],"exemplo":"O gestor Carlos usou o Azure para legendar uma reunião ao vivo, recebendo resultados intermediários. Depois, enviou 300 gravações guardadas à noite, sem pressa. O sistema processou tudo de forma assíncrona e entregou os textos na manhã seguinte. Foi a transcrição em lote."}},{"id":"aut.transcricao_ia.tempo_real.0006","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"A Amazon Transcribe permite apenas a transcrição de arquivos de mídia armazenados no Amazon S3, não oferecendo transcrição em tempo real.","gabarito":"E","explicacao":"Generalização indevida. A Amazon Transcribe é um serviço de ASR que opera em dois modos: lote (arquivos no Amazon S3) e streaming (mídia em tempo real).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Reconhecimento Automático de Fala)","mastigado":"Errado. A Amazon Transcribe faz os dois: transcreve arquivos guardados no armazenamento da Amazon, no modo em lote, e também transcreve áudio em tempo real, no modo de fluxo. A palavra 'apenas' torna a frase falsa.","teSitua":{"termos":[{"termo":"Amazon Transcribe","significado":"serviço de nuvem da Amazon que converte áudio em texto."},{"termo":"mídia","significado":"arquivos de áudio ou vídeo, como gravações de sessões."},{"termo":"Amazon S3","significado":"serviço de armazenamento de arquivos na nuvem da Amazon."},{"termo":"transcrição em tempo real","significado":"conversão da fala em texto enquanto ela acontece, com atraso mínimo."}],"exemplo":"O estagiário Davi disse que a Amazon Transcribe só lia arquivos guardados no S3. A analista Cecília mostrou na documentação que o serviço também aceita áudio em fluxo, ao vivo. Ela usou os dois modos: lote para gravações antigas e tempo real para a sessão do dia."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0001","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":3,"enunciado":"As manifestações do Plenário, como palmas e vaias, devem ser incorporadas ao texto da fala do orador, sem indicação distinta, para não interromper a fluidez da leitura.","gabarito":"E","explicacao":"O registro das manifestações do Plenário deve ser feito em indicação própria, conforme a convenção do órgão, separada da fala. Incorporá-las ao discurso confunde o que foi dito pelo orador com a reação do público.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Julgue C-E Degravação e Pós-processamento)","mastigado":"Errado. Palmas, vaias e outras reações do Plenário devem ser anotadas em separado, de acordo com a regra do órgão, e não misturadas à fala do orador. Misturar faria parecer que o orador disse o que, na verdade, foi reação do público.","teSitua":{"termos":[{"termo":"Plenário","significado":"reunião de todos os membros de uma casa legislativa, ou o local onde ela acontece."},{"termo":"orador","significado":"pessoa que discursa ou fala em público; aqui, o parlamentar que tem a palavra."},{"termo":"indicação distinta","significado":"marcação separada do texto da fala, como um colchete ou uma anotação própria."},{"termo":"fluidez da leitura","significado":"facilidade de ler o texto sem interrupções que atrapalhem o ritmo."}],"exemplo":"Durante o discurso do deputado Hugo, o Plenário aplaudiu. A degravadora Iara escreveu '(Palmas)' em linha separada, como manda o manual. Se tivesse colocado dentro da fala, o leitor poderia achar que o orador dissera algo sobre palmas."}},{"id":"aut.transcricao_ia.asr_modelos.0007","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":2,"enunciado":"O reconhecimento automático de fala (ASR) converte o sinal de áudio da fala em texto, e sua saída típica é a transcrição bruta, em geral com marcas de tempo e pontuações de confiança.","gabarito":"C","explicacao":"ASR (Automatic Speech Recognition, ou speech-to-text) é a tecnologia que converte o sinal de áudio da fala em texto. A saída típica é a transcrição bruta: sequência de palavras, em geral com marcas de tempo e pontuações de confiança. Essa saída ainda não é o texto final revisado de um registro oficial.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O sistema ouve a fala e devolve as palavras escritas, quase sempre dizendo em que segundo cada uma foi dita e o quanto ele tem certeza dela. É um texto cru, ainda sem revisão.","teSitua":{"termos":[{"termo":"reconhecimento automático de fala","significado":"tecnologia que transforma a voz em texto escrito sem ajuda humana."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala."},{"termo":"transcrição bruta","significado":"texto do jeito que a máquina entrega, sem correção nem ajuste."},{"termo":"marcas de tempo","significado":"indicação do momento exato da gravação em que cada palavra foi dita."},{"termo":"pontuações de confiança","significado":"notas que o sistema dá a cada palavra, indicando o quanto tem certeza de tê-la reconhecido bem."}],"exemplo":"Ao enviar o áudio da reunião, Gilberto recebe um arquivo com cada palavra, o segundo em que foi dita e uma nota de confiança. A palavra \\"Funai\\" veio com nota baixa, e ele sabe que precisa conferir esse ponto."}},{"id":"aut.transcricao_ia.asr_modelos.0008","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":2,"enunciado":"A saída típica de um sistema de reconhecimento automático de fala (ASR) já corresponde ao texto final revisado de um registro oficial, com as convenções editoriais do órgão aplicadas.","gabarito":"E","explicacao":"A saída típica do ASR é a transcrição bruta: sequência de palavras com marcas de tempo e pontuações de confiança. Ela ainda não é o texto final revisado de um registro oficial, que exige degravação, revisão e validação humanas.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O que sai da máquina é um texto cru. Para virar registro oficial, ainda precisa seguir as regras do órgão e passar por revisão de gente.","teSitua":{"termos":[{"termo":"reconhecimento automático de fala","significado":"tecnologia que transforma a voz em texto escrito sem ajuda humana."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala."},{"termo":"registro oficial","significado":"documento formal que vale como prova do que foi dito e decidido nas sessões."},{"termo":"convenções editoriais","significado":"regras do órgão sobre como o texto deve ser escrito e apresentado."}],"exemplo":"O estagiário Lauro achou que poderia publicar direto o texto do sistema. A supervisora Elza mostrou que faltavam os nomes dos oradores e havia siglas erradas: aquilo era só a transcrição bruta."}},{"id":"aut.transcricao_ia.asr_modelos.0009","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":2,"enunciado":"Na arquitetura clássica de ASR, um decodificador combina o modelo acústico, o léxico de pronúncia e o modelo de linguagem para encontrar a sequência de palavras mais provável.","gabarito":"C","explicacao":"A arquitetura clássica tem três módulos: modelo acústico (relaciona as características do sinal a unidades sonoras), léxico de pronúncia (associa cada palavra à sua sequência de fonemas) e modelo de linguagem (atribui probabilidade a sequências de palavras). Um decodificador combina os três para encontrar a sequência mais provável.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. No modelo antigo, três peças trabalham juntas: uma entende os sons, outra sabe como cada palavra se pronuncia e outra sabe quais frases fazem sentido. O decodificador junta as três e escolhe a frase mais provável.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"decodificador","significado":"parte do sistema que junta as informações dos modelos e escolhe o texto final mais provável."},{"termo":"modelo acústico","significado":"parte do sistema que liga os sons da gravação às unidades sonoras da língua."},{"termo":"léxico de pronúncia","significado":"dicionário que diz como cada palavra é pronunciada, em sequência de sons."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."}],"exemplo":"O sistema ouve algo como \\"sessão\\" ou \\"seção\\". O modelo acústico identifica os sons, o léxico mostra que as duas palavras se pronunciam igual, e o modelo de linguagem indica que \\"abrir a sessão\\" é mais provável. O decodificador escolhe \\"sessão\\"."}},{"id":"aut.transcricao_ia.asr_modelos.0010","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Na arquitetura clássica de ASR, o modelo de linguagem relaciona as características do sinal de áudio aos fonemas, ao passo que o modelo acústico atribui probabilidade às sequências de palavras.","gabarito":"E","explicacao":"A afirmativa inverteu as funções. O modelo acústico relaciona as características do sinal de áudio a unidades sonoras (fonemas ou estados de fonemas); o modelo de linguagem atribui probabilidade a sequências de palavras e favorece frases plausíveis.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. A frase trocou os papéis. Quem cuida do som é o modelo acústico. Quem calcula se a frase faz sentido é o modelo de linguagem.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."},{"termo":"fonemas","significado":"menores unidades de som de uma língua, que diferenciam palavras, como o p e o b em pato e bato."},{"termo":"modelo acústico","significado":"parte do sistema que liga os sons da gravação às unidades sonoras da língua."}],"exemplo":"Numa aula, Marcelo disse que o modelo de linguagem \\"escuta\\" o áudio. A professora Judite corrigiu: quem trata o som é o modelo acústico; o de linguagem só decide entre \\"votação nominal\\" e \\"votação no mau\\" pelo sentido."}},{"id":"aut.transcricao_ia.asr_modelos.0011","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":2,"enunciado":"Na arquitetura clássica de ASR, o modelo acústico relaciona o áudio aos fonemas, o léxico de pronúncia associa palavras a sequências de fonemas e o modelo de linguagem estima a probabilidade de sequências de palavras.","gabarito":"C","explicacao":"Essas são as funções dos três componentes clássicos. Na abordagem clássica, eles são construídos e ajustados separadamente e depois integrados pelo decodificador.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Cada peça tem seu trabalho: uma liga o som aos fonemas, outra liga os fonemas às palavras e a terceira diz quais sequências de palavras são prováveis.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"modelo acústico","significado":"parte do sistema que liga os sons da gravação às unidades sonoras da língua."},{"termo":"fonemas","significado":"menores unidades de som de uma língua, que diferenciam palavras, como o p e o b em pato e bato."},{"termo":"léxico de pronúncia","significado":"dicionário que diz como cada palavra é pronunciada, em sequência de sons."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."}],"exemplo":"Num sistema clássico, a equipe de Wilson treinou o modelo acústico com horas de áudio, montou o léxico com a pronúncia dos nomes dos deputados e treinou o modelo de linguagem com atas antigas. Só depois juntou as três partes."}},{"id":"aut.transcricao_ia.asr_modelos.0012","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Na arquitetura clássica de ASR, o decodificador relaciona diretamente o sinal de áudio aos fonemas, dispensando um modelo acústico construído separadamente.","gabarito":"E","explicacao":"Quem relaciona o áudio aos fonemas é o modelo acústico, componente construído e ajustado separadamente. O decodificador apenas integra modelo acústico, léxico de pronúncia e modelo de linguagem para encontrar a sequência de palavras mais provável. A afirmativa trocou o modelo acústico pelo decodificador.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. No sistema clássico, quem liga o som aos fonemas é o modelo acústico, uma peça própria. O decodificador só junta o trabalho das três peças no final.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"decodificador","significado":"parte do sistema que junta as informações dos modelos e escolhe o texto final mais provável."},{"termo":"fonemas","significado":"menores unidades de som de uma língua, que diferenciam palavras, como o p e o b em pato e bato."},{"termo":"modelo acústico","significado":"parte do sistema que liga os sons da gravação às unidades sonoras da língua."}],"exemplo":"Ao desenhar o sistema clássico, o engenheiro Caetano não deixou o decodificador lidar com o som: treinou antes um modelo acústico próprio. O decodificador entrou só no fim, para combinar as peças."}},{"id":"aut.transcricao_ia.asr_modelos.0013","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":2,"enunciado":"Na arquitetura clássica de ASR, o léxico de pronúncia é o componente que associa palavras a sequências de fonemas, construído separadamente dos demais e integrado pelo decodificador.","gabarito":"C","explicacao":"O léxico de pronúncia associa palavras a sequências de fonemas. Na abordagem clássica, ele, o modelo acústico e o modelo de linguagem são construídos e ajustados separadamente e depois integrados pelo decodificador.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O léxico é um dicionário de pronúncia: diz quais sons formam cada palavra. Ele é montado à parte e só no final se junta às outras peças.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"léxico de pronúncia","significado":"dicionário que diz como cada palavra é pronunciada, em sequência de sons."},{"termo":"fonemas","significado":"menores unidades de som de uma língua, que diferenciam palavras, como o p e o b em pato e bato."},{"termo":"decodificador","significado":"parte do sistema que junta as informações dos modelos e escolhe o texto final mais provável."}],"exemplo":"Quando um novo deputado, de sobrenome Wojcik, tomou posse, a equipe de Silvana acrescentou ao léxico de pronúncia a sequência de sons do nome dele. Só assim o sistema clássico passou a reconhecê-lo."}},{"id":"aut.transcricao_ia.asr_modelos.0014","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Na arquitetura clássica de ASR, o modelo de linguagem é o componente que associa cada palavra à sua sequência de fonemas.","gabarito":"E","explicacao":"Quem associa palavras a sequências de fonemas é o léxico de pronúncia. O modelo de linguagem estima a probabilidade de sequências de palavras. A afirmativa trocou o léxico pelo modelo de linguagem.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O dicionário de pronúncia, que diz quais sons formam cada palavra, é o léxico. O modelo de linguagem cuida de outra coisa: quais sequências de palavras fazem sentido.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."},{"termo":"fonemas","significado":"menores unidades de som de uma língua, que diferenciam palavras, como o p e o b em pato e bato."}],"exemplo":"Para o sistema reconhecer a palavra \\"quórum\\", Edgar a incluiu no léxico com seus sons. Para o sistema preferir \\"quórum para votação\\" a \\"quórum para vocação\\", quem ajuda é o modelo de linguagem."}},{"id":"aut.transcricao_ia.asr_modelos.0015","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":2,"enunciado":"Na arquitetura clássica de ASR, o modelo de linguagem estima a probabilidade de sequências de palavras, favorecendo as frases plausíveis na língua.","gabarito":"C","explicacao":"O modelo de linguagem atribui probabilidade a sequências de palavras e favorece frases plausíveis. Ele é construído separadamente do modelo acústico e do léxico de pronúncia, e os três são integrados pelo decodificador.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O modelo de linguagem sabe quais frases costumam aparecer na língua. Quando o som fica em dúvida entre duas opções, ele empurra para a que faz mais sentido.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."},{"termo":"plausíveis","significado":"que parecem razoáveis e têm boa chance de estarem certas."}],"exemplo":"O deputado diz algo que soa como \\"concerto\\" ou \\"conserto\\". Como a frase é \\"o conserto da estrada\\", o modelo de linguagem indica essa opção como mais provável, e o sistema de Neide acerta."}},{"id":"aut.transcricao_ia.asr_modelos.0016","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Na arquitetura clássica de ASR, o modelo de linguagem estima a probabilidade de cada fonema diretamente a partir das características acústicas do sinal.","gabarito":"E","explicacao":"Relacionar as características acústicas do sinal aos fonemas é função do modelo acústico. O modelo de linguagem estima a probabilidade de sequências de palavras. A afirmativa atribuiu ao modelo de linguagem a tarefa do modelo acústico.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O modelo de linguagem não mexe com o som. Quem olha o áudio e o liga aos fonemas é o modelo acústico. O de linguagem só avalia as sequências de palavras.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."},{"termo":"fonema","significado":"menor unidade de som de uma língua, que diferencia palavras, como o p e o b em pato e bato."},{"termo":"características acústicas","significado":"propriedades físicas do som gravado, como altura, intensidade e frequências."}],"exemplo":"A técnica Olga treinou o modelo de linguagem só com textos, sem nenhum áudio. Isso basta porque ele lida com palavras. Para os sons, ela usou outro componente, o modelo acústico, treinado com gravações."}},{"id":"aut.transcricao_ia.asr_modelos.0017","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos modelos end-to-end de ASR, uma única rede neural é treinada para mapear diretamente o áudio para o texto, em geral sem léxico de pronúncia explícito, embora um modelo de linguagem externo ainda possa ser acoplado.","gabarito":"C","explicacao":"Na arquitetura clássica, modelo acústico, léxico de pronúncia e modelo de linguagem são componentes separados, combinados na decodificação. Nos modelos end-to-end, uma única rede neural mapeia diretamente o áudio para o texto (caracteres, subpalavras ou palavras), em geral sem léxico explícito; um modelo de linguagem externo pode ser acoplado como reforço.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. No modelo moderno, uma rede só faz tudo, do som direto às letras, sem dicionário de pronúncia separado. Mesmo assim, se quiser, dá para ligar um modelo de linguagem extra como reforço.","teSitua":{"termos":[{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"rede neural","significado":"programa de computador inspirado no cérebro, que aprende padrões a partir de muitos exemplos."},{"termo":"léxico de pronúncia","significado":"dicionário que diz como cada palavra é pronunciada, em sequência de sons."},{"termo":"modelo de linguagem externo","significado":"componente separado, ligado ao sistema, que ajuda a escolher as sequências de palavras mais prováveis."}],"exemplo":"Ao migrar para um sistema end-to-end, a equipe de Cássio aposentou o dicionário de pronúncia. A nova rede aprendeu sozinha, com milhares de horas de áudio e texto, a escrever o que ouve."}},{"id":"aut.transcricao_ia.asr_modelos.0018","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos modelos end-to-end de ASR, o modelo acústico, o léxico de pronúncia e o modelo de linguagem continuam sendo treinados separadamente, sendo combinados apenas na decodificação.","gabarito":"E","explicacao":"Treinar componentes separados e combiná-los na decodificação é a marca da arquitetura clássica. Nos modelos end-to-end, uma única rede neural é treinada para mapear diretamente o áudio para o texto, em geral sem léxico de pronúncia explícito. A afirmativa descreveu a arquitetura clássica.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Peças treinadas em separado e juntadas no fim são o jeito antigo. O end-to-end é justamente uma rede só, treinada de uma vez, indo do som ao texto.","teSitua":{"termos":[{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."},{"termo":"modelo acústico","significado":"parte do sistema que liga os sons da gravação às unidades sonoras da língua."},{"termo":"léxico de pronúncia","significado":"dicionário que diz como cada palavra é pronunciada, em sequência de sons."},{"termo":"decodificação","significado":"etapa final em que o sistema escolhe o texto mais provável para o áudio."}],"exemplo":"Iara compara dois sistemas. No clássico, ela vê três arquivos de modelo treinados separadamente. No end-to-end, há um único modelo, que recebe o áudio e devolve o texto pronto."}},{"id":"aut.transcricao_ia.asr_modelos.0019","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":4,"enunciado":"O CTC (Connectionist Temporal Classification) permite treinar a rede sem alinhamento prévio entre cada quadro de áudio e cada rótulo, usando um símbolo especial de branco que é removido na obtenção da saída.","gabarito":"C","explicacao":"O CTC é uma função de perda, com esquema de decodificação, que permite treinar sem alinhamento prévio entre quadros de áudio e rótulos. Usa o símbolo branco (blank), e a saída é obtida colapsando repetições e removendo os brancos. Supõe independência condicional entre as saídas, o que explica o ganho frequente com modelo de linguagem externo. Proposto por Graves e colaboradores (2006).","fonte":"Graves et al., Connectionist Temporal Classification (ICML, 2006); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Com o CTC, não é preciso dizer à máquina em que pedacinho do áudio está cada letra. Ela usa um símbolo \\"vazio\\" para preencher os intervalos e depois o apaga, junto com as repetições.","teSitua":{"termos":[{"termo":"CTC","significado":"técnica de treino de reconhecimento de fala que dispensa marcar, antes, onde cada letra aparece no áudio."},{"termo":"alinhamento prévio","significado":"marcação feita antes do treino indicando em que momento do áudio está cada som ou letra."},{"termo":"quadro de áudio","significado":"pedacinho de poucos milissegundos em que o som é dividido para análise."},{"termo":"rótulo","significado":"símbolo de saída que o sistema deve produzir, como uma letra ou parte de palavra."},{"termo":"branco","significado":"símbolo especial que indica ausência de letra num quadro e é apagado no texto final."}],"exemplo":"O sistema produz algo como \\"cc-aa-mm-a-rr-a\\", em que o hífen é o branco. Ao juntar as repetições e apagar os brancos, sai \\"camara\\". Assim a equipe de Aurélio treinou a rede sem marcar onde cada letra estava no áudio."}},{"id":"aut.transcricao_ia.asr_modelos.0020","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":4,"enunciado":"O CTC (Connectionist Temporal Classification) não supõe independência condicional entre as saídas, razão pela qual dispensa por completo o auxílio de modelo de linguagem externo.","gabarito":"E","explicacao":"O CTC supõe independência condicional entre as saídas, e é justamente isso que explica o ganho frequente com modelo de linguagem externo. Quem não faz essa suposição é o RNN-Transducer, graças à rede de predição. A afirmativa inverteu a característica do CTC.","fonte":"Graves et al., Connectionist Temporal Classification (ICML, 2006); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O CTC escolhe cada letra sem olhar as que já escreveu, como se fossem independentes. Por isso costuma melhorar bastante quando se acopla um modelo de linguagem para dar coerência ao texto.","teSitua":{"termos":[{"termo":"CTC","significado":"técnica de treino de reconhecimento de fala que dispensa marcar, antes, onde cada letra aparece no áudio."},{"termo":"independência condicional","significado":"suposição de que cada saída é escolhida sem levar em conta as saídas anteriores."},{"termo":"modelo de linguagem externo","significado":"componente separado, ligado ao sistema, que ajuda a escolher as sequências de palavras mais prováveis."}],"exemplo":"O modelo CTC de Bárbara escrevia \\"prossesso legislativo\\". Ao acoplar um modelo de linguagem externo, que sabe que \\"processo legislativo\\" é muito mais comum, o erro desapareceu."}},{"id":"aut.transcricao_ia.asr_modelos.0021","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"Entre os modelos end-to-end de reconhecimento de fala estão o CTC, os modelos sequência a sequência com atenção e o RNN-Transducer.","gabarito":"C","explicacao":"CTC, modelos sequência a sequência com atenção e RNN-Transducer são os três esquemas end-to-end de ASR. Transformers e Conformers são arquiteturas de rede usadas como codificadores nesses esquemas; o Whisper, da OpenAI, é um modelo sequência a sequência baseado em Transformer.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Há três jeitos principais de fazer reconhecimento de fala com uma rede só: o CTC, os modelos com atenção e o RNN-Transducer.","teSitua":{"termos":[{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."},{"termo":"CTC","significado":"técnica de treino de reconhecimento de fala que dispensa marcar, antes, onde cada letra aparece no áudio."},{"termo":"sequência a sequência","significado":"tipo de modelo que transforma uma sequência de entrada, como o áudio, em outra sequência, como o texto."},{"termo":"atenção","significado":"mecanismo que deixa o modelo focar, a cada passo, nas partes mais importantes da entrada."},{"termo":"RNN-Transducer","significado":"modelo de reconhecimento de fala que gera o texto em fluxo, levando em conta o que já foi escrito."}],"exemplo":"No curso de reconhecimento de fala, a professora Lígia apresenta três famílias de modelos que vão direto do som ao texto: CTC, os de atenção, como o Whisper, e o RNN-Transducer, comum em celulares."}},{"id":"aut.transcricao_ia.asr_modelos.0022","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":4,"enunciado":"Os modelos ocultos de Markov combinados com léxico de pronúncia explícito figuram, ao lado do RNN-Transducer e dos modelos com atenção, entre os modelos end-to-end de reconhecimento de fala.","gabarito":"E","explicacao":"Os esquemas end-to-end são o CTC, os modelos sequência a sequência com atenção e o RNN-Transducer. Modelos com léxico de pronúncia explícito e componentes separados, como os sistemas baseados em modelos ocultos de Markov, pertencem à arquitetura clássica. A afirmativa colocou o CTC de lado e incluiu um modelo clássico.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Ter um dicionário de pronúncia separado é marca do sistema clássico, montado em peças. Os três modelos end-to-end são o CTC, os com atenção e o RNN-Transducer.","teSitua":{"termos":[{"termo":"modelos ocultos de Markov","significado":"técnica estatística antiga, muito usada no reconhecimento de fala clássico, para modelar sequências de sons."},{"termo":"léxico de pronúncia","significado":"dicionário que diz como cada palavra é pronunciada, em sequência de sons."},{"termo":"RNN-Transducer","significado":"modelo de reconhecimento de fala que gera o texto em fluxo, levando em conta o que já foi escrito."},{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."}],"exemplo":"O sistema antigo da Assembleia usava modelos de Markov e um dicionário de pronúncia, tudo em peças separadas. Quando o técnico Jair o trocou por um RNN-Transducer, passou a ter uma única rede, do áudio ao texto."}},{"id":"aut.transcricao_ia.asr_modelos.0023","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, é um modelo end-to-end de reconhecimento de fala do tipo sequência a sequência com atenção, baseado em Transformer.","gabarito":"C","explicacao":"Os modelos end-to-end incluem o CTC, os modelos sequência a sequência com atenção e o RNN-Transducer. O Whisper é um modelo sequência a sequência baseado em Transformer (codificador-decodificador).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Radford et al., Robust Speech Recognition via Large-Scale Weak Supervision (OpenAI, 2022)","mastigado":"Certo. O Whisper recebe o áudio inteiro de uma janela, entende tudo com um codificador e depois escreve o texto aos poucos, consultando o áudio pela atenção. É da família dos modelos com atenção.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"OpenAI","significado":"empresa americana de inteligência artificial que criou o Whisper e o ChatGPT."},{"termo":"sequência a sequência","significado":"tipo de modelo que transforma uma sequência de entrada, como o áudio, em outra sequência, como o texto."},{"termo":"atenção","significado":"mecanismo que deixa o modelo focar, a cada passo, nas partes mais importantes da entrada."},{"termo":"Transformer","significado":"tipo de rede neural baseada em atenção, usada hoje na maioria dos grandes modelos de IA."}],"exemplo":"Ao estudar o Whisper, Rogério vê que ele tem um codificador, que lê o áudio, e um decodificador, que escreve o texto palavra a palavra olhando para o áudio. É o desenho típico de sequência a sequência com atenção."}},{"id":"aut.transcricao_ia.asr_modelos.0024","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, é um modelo de reconhecimento de fala do tipo RNN-Transducer, e não um modelo sequência a sequência com atenção.","gabarito":"E","explicacao":"O Whisper é um modelo sequência a sequência baseado em Transformer (codificador-decodificador com atenção), e não um RNN-Transducer. A afirmativa trocou a família do modelo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Radford et al., Robust Speech Recognition via Large-Scale Weak Supervision (OpenAI, 2022)","mastigado":"Errado. O Whisper é da família dos modelos com atenção: um codificador lê o áudio e um decodificador escreve o texto. O RNN-Transducer é outro tipo de modelo, comum em transcrição ao vivo.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"RNN-Transducer","significado":"modelo de reconhecimento de fala que gera o texto em fluxo, levando em conta o que já foi escrito."},{"termo":"sequência a sequência","significado":"tipo de modelo que transforma uma sequência de entrada, como o áudio, em outra sequência, como o texto."},{"termo":"atenção","significado":"mecanismo que deixa o modelo focar, a cada passo, nas partes mais importantes da entrada."}],"exemplo":"Num seminário, Felícia disse que o Whisper era um RNN-Transducer. O palestrante Augusto corrigiu: o Whisper é um Transformer com codificador e decodificador, ou seja, um modelo de atenção."}},{"id":"aut.transcricao_ia.asr_modelos.0025","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":4,"enunciado":"Transformers e Conformers são arquiteturas de rede usadas como codificadores nos esquemas end-to-end de reconhecimento de fala, como o CTC e o RNN-Transducer.","gabarito":"C","explicacao":"Os esquemas end-to-end são o CTC, os modelos sequência a sequência com atenção e o RNN-Transducer. Transformers e Conformers são arquiteturas de rede usadas como codificadores nesses esquemas, e não esquemas concorrentes.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. CTC e RNN-Transducer são o jeito de treinar e gerar o texto; Transformer e Conformer são o motor que processa o áudio dentro deles. Um não exclui o outro.","teSitua":{"termos":[{"termo":"Transformers","significado":"tipo de rede neural baseada em atenção, usada hoje na maioria dos grandes modelos de IA."},{"termo":"Conformers","significado":"variação do Transformer que junta atenção e convolução, criada para lidar melhor com áudio."},{"termo":"codificadores","significado":"partes do modelo que transformam o áudio em representações numéricas para o resto do sistema usar."},{"termo":"CTC","significado":"técnica de treino de reconhecimento de fala que dispensa marcar, antes, onde cada letra aparece no áudio."},{"termo":"RNN-Transducer","significado":"modelo de reconhecimento de fala que gera o texto em fluxo, levando em conta o que já foi escrito."}],"exemplo":"O fornecedor explicou a Moisés que seu sistema é um RNN-Transducer com codificador Conformer. Ou seja, o Conformer processa o áudio, e o esquema RNN-Transducer gera o texto em fluxo."}},{"id":"aut.transcricao_ia.asr_modelos.0026","subtopico":"transcricao_ia.reconhecimento_fala.asr_modelos","tipo":"certo_errado","dificuldade":4,"enunciado":"Transformers e Conformers são esquemas end-to-end de reconhecimento de fala concorrentes do CTC e do RNN-Transducer, e não podem ser usados como codificadores nesses esquemas.","gabarito":"E","explicacao":"Transformers e Conformers são arquiteturas de rede usadas como codificadores nos esquemas end-to-end (CTC, sequência a sequência com atenção e RNN-Transducer). Não são esquemas concorrentes que excluam esses. A afirmativa confundiu arquitetura do codificador com esquema de treinamento e decodificação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Transformer e Conformer são peças que processam o áudio e podem ser usadas dentro do CTC e do RNN-Transducer. Não são rivais desses esquemas.","teSitua":{"termos":[{"termo":"Transformers","significado":"tipo de rede neural baseada em atenção, usada hoje na maioria dos grandes modelos de IA."},{"termo":"Conformers","significado":"variação do Transformer que junta atenção e convolução, criada para lidar melhor com áudio."},{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."},{"termo":"codificadores","significado":"partes do modelo que transformam o áudio em representações numéricas para o resto do sistema usar."}],"exemplo":"Na licitação, um concorrente disse que seu sistema \\"não é CTC, é Conformer\\". A analista Denise percebeu a confusão: o Conformer é o codificador, e o sistema pode muito bem ser treinado com CTC."}},{"id":"aut.transcricao_ia.asr_portugues.0002","subtopico":"transcricao_ia.reconhecimento_fala.asr_portugues","tipo":"certo_errado","dificuldade":2,"enunciado":"Entre os desafios do ASR para o português brasileiro em sessões legislativas estão a variação regional de sotaque, a fala espontânea e acelerada, a sobreposição de vozes e o vocabulário parlamentar, com siglas e expressões regimentais como \\"questão de ordem\\".","gabarito":"C","explicacao":"Os principais desafios são: variação regional de sotaque e de pronúncia; velocidade de fala elevada e fala espontânea (hesitações, truncamentos); ruído de ambiente e qualidade da captação; sobreposição de vozes (apartes e interrupções); vocabulário técnico e parlamentar, siglas e nomes próprios; expressões regimentais, como \\"questão de ordem\\" e \\"pela ordem\\".","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Na Câmara, a máquina enfrenta deputados de todo o país, com sotaques diferentes, falando rápido e de improviso, muitas vezes ao mesmo tempo, e usando siglas e expressões próprias do regimento.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"fala espontânea","significado":"fala improvisada, sem texto lido, cheia de pausas, repetições e frases interrompidas."},{"termo":"sobreposição de vozes","significado":"situação em que duas ou mais pessoas falam ao mesmo tempo."},{"termo":"expressões regimentais","significado":"termos fixos previstos no regimento da Casa, usados para pedir a palavra ou levantar dúvidas sobre o procedimento."},{"termo":"questão de ordem","significado":"pedido de um parlamentar para esclarecer dúvida sobre a aplicação do regimento na sessão."}],"exemplo":"Numa mesma sessão, o sistema ouve o deputado Josué, gaúcho, e a deputada Iolanda, paraense, falando depressa. No meio, alguém grita \\"pela ordem!\\" por cima da fala dela. O texto sai com erros, e o revisor Thiago corrige."}},{"id":"aut.transcricao_ia.asr_portugues.0003","subtopico":"transcricao_ia.reconhecimento_fala.asr_portugues","tipo":"certo_errado","dificuldade":2,"enunciado":"Por não haver variação regional relevante de pronúncia no português brasileiro, o sotaque não figura entre os desafios do ASR nas sessões legislativas, cujas dificuldades se limitam ao ruído de ambiente.","gabarito":"E","explicacao":"A variação regional de sotaque e de pronúncia é um dos principais desafios do ASR para o português brasileiro, ao lado da fala espontânea e acelerada, do ruído, da sobreposição de vozes, do vocabulário técnico e das expressões regimentais. A afirmativa negou o sotaque e reduziu os desafios ao ruído.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O Brasil tem muitos sotaques, e isso pesa bastante para a máquina. Além do barulho, há fala rápida, vozes ao mesmo tempo e muitas siglas e termos do regimento.","teSitua":{"termos":[{"termo":"variação regional","significado":"diferenças no jeito de falar de cada região do país, como sotaque e vocabulário."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"ruído de ambiente","significado":"barulho do local da gravação, como conversas paralelas, ar-condicionado e passos."}],"exemplo":"O sistema treinado só com vozes paulistas errava muito as falas do deputado Raimundo, cearense. Mesmo com o Plenário em silêncio, o problema era o sotaque, e a equipe de Ingrid incluiu áudios de várias regiões no ajuste."}},{"id":"aut.transcricao_ia.atas_resumos.0002","subtopico":"transcricao_ia.ia_parlamento.atas_resumos","tipo":"certo_errado","dificuldade":3,"enunciado":"A sumarização extrativa seleciona e recorta trechos do próprio original, preservando a literalidade, enquanto a abstrativa redige texto novo, mais fluente, porém com maior risco de imprecisão e de alucinação.","gabarito":"C","explicacao":"Extrativa: seleciona e recorta trechos do original; preserva a literalidade e tem menor risco de distorção, mas pode resultar em texto truncado. Abstrativa: redige texto novo, parafraseando; é mais fluente, porém com risco maior de imprecisão e de alucinação, o que exige revisão atenta quando o produto é uma ata.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. O resumo extrativo é feito de recortes do texto original: fiel, mas às vezes truncado. O abstrativo é reescrito com outras palavras: lê melhor, mas pode errar ou inventar.","teSitua":{"termos":[{"termo":"sumarização extrativa","significado":"resumo montado com frases recortadas do próprio texto original, sem reescrever."},{"termo":"literalidade","significado":"fidelidade exata às palavras originais."},{"termo":"abstrativa","significado":"tipo de resumo que reescreve o conteúdo com palavras novas, como uma paráfrase."},{"termo":"alucinação","significado":"erro em que a IA afirma algo inventado, que não estava na fonte, com aparência de verdade."}],"exemplo":"Para resumir a sessão, o sistema A só recortou frases dos discursos; o texto ficou fiel, mas picotado. O sistema B escreveu um resumo fluente, mas atribuiu ao deputado Celso uma proposta que ele não fez. A revisora Ivone corrigiu."}},{"id":"aut.transcricao_ia.atas_resumos.0003","subtopico":"transcricao_ia.ia_parlamento.atas_resumos","tipo":"certo_errado","dificuldade":3,"enunciado":"A sumarização abstrativa, por recortar trechos literais do original, apresenta menor risco de alucinação do que a extrativa, que redige texto novo parafraseando o conteúdo.","gabarito":"E","explicacao":"A afirmativa inverteu os conceitos. A extrativa é a que recorta trechos do original e tem menor risco de distorção; a abstrativa redige texto novo, parafraseando, com risco maior de imprecisão e de alucinação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. A frase trocou os dois tipos. Quem recorta pedaços do original é a extrativa, mais segura. A abstrativa reescreve com outras palavras e, por isso, corre mais risco de inventar.","teSitua":{"termos":[{"termo":"sumarização abstrativa","significado":"resumo que reescreve o conteúdo com palavras novas, como uma paráfrase."},{"termo":"alucinação","significado":"erro em que a IA afirma algo inventado, que não estava na fonte, com aparência de verdade."},{"termo":"extrativa","significado":"tipo de resumo montado com frases recortadas do próprio texto original."},{"termo":"parafraseando","significado":"dizendo a mesma ideia com outras palavras."}],"exemplo":"Quando precisou de um resumo bem fiel do depoimento na CPI, a analista Cristina escolheu o modo extrativo, que só recorta frases ditas. O modo abstrativo ficaria mais bonito, mas poderia inventar algo."}},{"id":"aut.transcricao_ia.atas_resumos.0004","subtopico":"transcricao_ia.ia_parlamento.atas_resumos","tipo":"certo_errado","dificuldade":2,"enunciado":"Por ser a ata documento oficial com efeitos jurídicos, a ata gerada automaticamente é tratada como minuta, exigindo conferência contra o áudio e sem supressão de manifestações, apartes e deliberações.","gabarito":"C","explicacao":"A ata é documento oficial, com efeitos jurídicos. Por isso: a saída automática é minuta, nunca versão final; exige-se conferência contra o áudio; o resumo não pode suprimir manifestações, apartes e deliberações; registra-se o que não foi compreendido em vez de completar; e a aprovação cabe ao servidor e ao órgão competente.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. A ata vale como documento oficial, então o que a máquina produz é só um rascunho. Alguém precisa conferir com a gravação e garantir que nenhuma fala, aparte ou decisão ficou de fora.","teSitua":{"termos":[{"termo":"ata","significado":"documento oficial que registra o que aconteceu e o que foi decidido numa reunião ou sessão."},{"termo":"efeitos jurídicos","significado":"consequências legais, como servir de prova ou dar validade a uma decisão."},{"termo":"minuta","significado":"rascunho de um documento, que ainda será revisado e aprovado."},{"termo":"apartes","significado":"interrupções breves de outro parlamentar no meio do discurso, com permissão do orador."},{"termo":"deliberações","significado":"decisões tomadas pelo colegiado, como aprovações e rejeições em votação."}],"exemplo":"O sistema gerou a ata da reunião da Comissão em minutos. O servidor Eduardo tratou o texto como minuta: ouviu o áudio, incluiu um aparte que tinha sumido e conferiu o resultado da votação antes de mandar para aprovação."}},{"id":"aut.transcricao_ia.atas_resumos.0005","subtopico":"transcricao_ia.ia_parlamento.atas_resumos","tipo":"certo_errado","dificuldade":2,"enunciado":"Na geração automática de atas parlamentares, os trechos não compreendidos pelo sistema devem ser completados pelo próprio modelo com base no contexto, para que a ata não apresente lacunas.","gabarito":"E","explicacao":"Na geração automática de atas, deve-se registrar o que não foi compreendido, em vez de completar. Completar pelo contexto é inventar conteúdo em documento oficial com efeitos jurídicos. A saída é minuta, exige conferência contra o áudio, e a aprovação cabe ao servidor e ao órgão competente.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. Em documento oficial, é melhor deixar claro que um trecho não foi entendido do que deixar a máquina adivinhar. Lacuna marcada é honesta; texto inventado pode virar prova falsa.","teSitua":{"termos":[{"termo":"atas","significado":"documentos oficiais que registram o que aconteceu e o que foi decidido numa reunião ou sessão."},{"termo":"modelo","significado":"sistema de inteligência artificial treinado para produzir texto."},{"termo":"lacunas","significado":"partes faltando num texto, espaços sem conteúdo."}],"exemplo":"Na reunião, o microfone do vereador Hugo falhou. O sistema sugeriu completar a frase com o que \\"ele provavelmente disse\\". A servidora Telma recusou e registrou o trecho como não compreendido."}},{"id":"aut.transcricao_ia.busca_semantica.0004","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":2,"enunciado":"A busca semântica em acervos parlamentares representa consulta e documentos como vetores (embeddings) e recupera por proximidade de significado, encontrando documentos relevantes mesmo quando o usuário usa outra formulação.","gabarito":"C","explicacao":"A busca léxica localiza documentos que contêm as palavras digitadas e falha com sinônimos ou outra formulação. A semântica representa consulta e documentos como vetores (embeddings) e recupera por proximidade de significado, com medidas como a similaridade de cosseno em banco vetorial.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. A busca semântica procura pelo sentido, não pela palavra exata. Se alguém digita \\"mudança nos impostos\\", ela encontra discursos sobre \\"reforma tributária\\", porque os dois querem dizer quase a mesma coisa.","teSitua":{"termos":[{"termo":"busca semântica","significado":"pesquisa que encontra documentos pelo significado, e não só pelas palavras exatas digitadas."},{"termo":"acervos","significado":"coleções de documentos guardados, como discursos e atas de muitos anos."},{"termo":"vetores","significado":"listas de números que o computador usa para representar o sentido de um texto."},{"termo":"embeddings","significado":"representações de textos em números, feitas de modo que textos de sentido parecido fiquem próximos."}],"exemplo":"A pesquisadora Daniela digita \\"mudança nos impostos sobre consumo\\" no acervo da Câmara. A busca semântica traz discursos sobre \\"reforma tributária\\" e \\"IVA dual\\", mesmo sem nenhuma das palavras que ela digitou."}},{"id":"aut.transcricao_ia.busca_semantica.0005","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":2,"enunciado":"A busca léxica em acervos parlamentares recupera documentos por proximidade de significado, razão pela qual não falha quando o usuário emprega sinônimos das palavras usadas nos documentos.","gabarito":"E","explicacao":"A busca léxica localiza documentos que contêm as palavras digitadas e falha justamente quando o usuário usa sinônimo ou outra formulação. Quem recupera por proximidade de significado, com vetores (embeddings), é a busca semântica. A afirmativa atribuiu à léxica a característica da semântica.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. A busca léxica procura as palavras exatas. Se o documento usa um sinônimo, ela não acha. Quem entende o sentido é a busca semântica.","teSitua":{"termos":[{"termo":"busca léxica","significado":"pesquisa que encontra apenas os documentos que contêm as palavras exatas digitadas."},{"termo":"acervos","significado":"coleções de documentos guardados, como discursos e atas de muitos anos."},{"termo":"sinônimos","significado":"palavras diferentes com o mesmo significado, como \\"imposto\\" e \\"tributo\\"."}],"exemplo":"Ramon pesquisa \\"tributo\\" no sistema antigo e não encontra o discurso em que a deputada falou só em \\"imposto\\". O sistema faz busca léxica, presa às palavras exatas."}},{"id":"aut.transcricao_ia.busca_semantica.0006","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":2,"enunciado":"A geração aumentada por recuperação (RAG) primeiro recupera trechos pertinentes de uma base confiável e depois pede ao modelo que responda fundamentado neles, o que reduz a alucinação e permite citar a origem.","gabarito":"C","explicacao":"RAG (retrieval-augmented generation) combina um mecanismo de busca com um modelo gerador: recupera trechos pertinentes de uma base confiável e pede ao modelo que responda com base neles. Reduz a alucinação porque ancora a resposta em fonte verificável e permite citar a origem, essencial em acervo legislativo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. Antes de responder, o sistema vai buscar os documentos certos e responde apoiado neles. Como a resposta tem de onde vir, ele inventa menos e pode mostrar a fonte.","teSitua":{"termos":[{"termo":"geração aumentada por recuperação","significado":"técnica em que a IA primeiro busca documentos confiáveis e depois responde com base neles."},{"termo":"RAG","significado":"sigla em inglês de geração aumentada por recuperação."},{"termo":"modelo","significado":"sistema de inteligência artificial treinado para produzir texto."},{"termo":"alucinação","significado":"erro em que a IA afirma algo inventado, que não estava na fonte, com aparência de verdade."}],"exemplo":"Ao perguntar ao assistente da Câmara quem relatou a lei do saneamento, o assessor Murilo recebe a resposta com o link do parecer original. O sistema usa RAG: buscou o documento antes de responder."}},{"id":"aut.transcricao_ia.busca_semantica.0007","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":3,"enunciado":"A geração aumentada por recuperação (RAG) reduz a alucinação porque retreina o modelo gerador a cada consulta com todo o acervo legislativo, dispensando a busca prévia de trechos.","gabarito":"E","explicacao":"A RAG não retreina o modelo: combina um mecanismo de busca com o gerador, recuperando primeiro trechos pertinentes de uma base confiável e pedindo ao modelo que responda fundamentado neles. A redução da alucinação vem de ancorar a resposta em fonte verificável. A afirmativa trocou a recuperação pelo retreinamento.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. A RAG não ensina o modelo de novo a cada pergunta. Ela busca primeiro os trechos certos e entrega ao modelo para ele responder com base neles. A busca é justamente o coração da técnica.","teSitua":{"termos":[{"termo":"geração aumentada por recuperação","significado":"técnica em que a IA primeiro busca documentos confiáveis e depois responde com base neles."},{"termo":"alucinação","significado":"erro em que a IA afirma algo inventado, que não estava na fonte, com aparência de verdade."},{"termo":"retreina","significado":"treina de novo o modelo com novos dados, processo demorado que muda o próprio sistema."},{"termo":"acervo legislativo","significado":"conjunto de documentos do Parlamento, como leis, projetos, pareceres e discursos."}],"exemplo":"Ao implantar o assistente, a equipe de Larissa não retreinou o modelo. Bastou ligá-lo a um buscador do acervo: a cada pergunta, o sistema puxa os trechos relevantes e responde citando-os."}},{"id":"aut.transcricao_ia.busca_semantica.0008","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":2,"enunciado":"A representação numérica que traduz o significado de um texto em um vetor, permitindo comparar documentos por proximidade de sentido, é chamada de embedding.","gabarito":"C","explicacao":"O embedding é a representação vetorial do significado de um texto. Esses vetores são armazenados em bancos vetoriais e comparados por medidas como a similaridade de cosseno, base da busca semântica.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. O embedding transforma o sentido de um texto numa lista de números. Textos parecidos viram números parecidos, e assim o computador consegue dizer quais documentos falam da mesma coisa.","teSitua":{"termos":[{"termo":"representação numérica","significado":"forma de descrever algo usando números, para o computador poder fazer contas com isso."},{"termo":"vetor","significado":"lista ordenada de números que representa uma informação, como o sentido de um texto."},{"termo":"embedding","significado":"representação do sentido de um texto em números, em que textos parecidos ficam próximos."}],"exemplo":"O sistema da Câmara transforma cada discurso em um embedding. Quando Viviane busca \\"violência contra a mulher\\", o sistema compara números e acha também discursos sobre \\"Lei Maria da Penha\\", cujo vetor é próximo."}},{"id":"aut.transcricao_ia.busca_semantica.0009","subtopico":"transcricao_ia.ia_parlamento.busca_semantica","tipo":"certo_errado","dificuldade":2,"enunciado":"A representação numérica que traduz o significado de um texto em um vetor, permitindo comparar documentos por proximidade de sentido, é chamada de diarização.","gabarito":"E","explicacao":"Essa representação é o embedding, armazenado em bancos vetoriais e comparado por medidas como a similaridade de cosseno. Diarização é a tarefa de dividir o áudio em segmentos e atribuí-los a cada falante. A afirmativa trocou o termo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. Transformar o sentido do texto em números é o embedding. Diarização é outra tarefa, do áudio: descobrir quem falou em cada momento da gravação.","teSitua":{"termos":[{"termo":"representação numérica","significado":"forma de descrever algo usando números, para o computador poder fazer contas com isso."},{"termo":"vetor","significado":"lista ordenada de números que representa uma informação, como o sentido de um texto."},{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."}],"exemplo":"No projeto de busca do acervo, o técnico Saulo gera um embedding para cada discurso. Na transcrição das sessões, outro sistema faz a diarização. São ferramentas diferentes, para problemas diferentes."}},{"id":"aut.transcricao_ia.cat_vocabulario.0003","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"Nas ferramentas de ASR, o vocabulário personalizado é uma lista de termos, nomes e frases do domínio fornecida ao serviço para aumentar a chance de serem reconhecidos, em geral sem retreinar o modelo.","gabarito":"C","explicacao":"Vocabulário personalizado é a lista de termos, nomes e frases do domínio entregue ao serviço (lista de frases no Azure AI Speech; vocabulário personalizado na Amazon Transcribe) para aumentar a chance de reconhecimento, em geral sem retreinar o modelo. O modelo adaptado, ao contrário, é personalizado com texto do domínio e, às vezes, com áudio e transcrições de referência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário); documentação Azure AI Speech (lista de frases) e Amazon Transcribe (vocabulário personalizado)","mastigado":"Certo. É como entregar ao sistema uma colinha com nomes e siglas que vão aparecer. Ele passa a reconhecê-los com mais facilidade, sem precisar ser treinado de novo.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"vocabulário personalizado","significado":"lista de palavras e nomes específicos que o usuário envia ao sistema para ele reconhecer melhor."},{"termo":"domínio","significado":"área de assunto em que o sistema é usado, como as sessões do Parlamento."},{"termo":"retreinar o modelo","significado":"treinar de novo o sistema com novos dados, processo demorado que muda o próprio modelo."}],"exemplo":"Antes da audiência sobre o marco do saneamento, Laura cadastra no serviço de transcrição os nomes dos convidados e siglas como ANA e FUNASA. O sistema continua o mesmo, mas passa a acertar esses termos com muito mais frequência."}},{"id":"aut.transcricao_ia.cat_vocabulario.0004","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":4,"enunciado":"Nas ferramentas de ASR, o vocabulário personalizado consiste em retreinar o modelo acústico com horas de áudio do domínio, ao passo que o modelo adaptado é apenas uma lista de termos fornecida ao serviço.","gabarito":"E","explicacao":"A afirmativa inverteu os conceitos. Vocabulário personalizado é uma lista de termos, nomes e frases do domínio fornecida ao serviço, em geral sem retreinar o modelo. Modelo adaptado é o modelo personalizado com texto do domínio e, às vezes, áudio com transcrições de referência (Custom Speech no Azure; modelos de linguagem personalizados na Amazon Transcribe).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário); documentação Azure Custom Speech e Amazon Transcribe","mastigado":"Errado. A frase trocou os dois. O vocabulário personalizado é a lista simples de palavras. Quem passa por ajuste com textos, e às vezes áudios, do assunto é o modelo adaptado.","teSitua":{"termos":[{"termo":"vocabulário personalizado","significado":"lista de palavras e nomes específicos que o usuário envia ao sistema para ele reconhecer melhor."},{"termo":"modelo acústico","significado":"parte do sistema que liga os sons da gravação às unidades sonoras da língua."},{"termo":"modelo adaptado","significado":"versão do sistema ajustada com textos e, às vezes, áudios de um assunto específico."}],"exemplo":"Felipe quer que o sistema acerte nomes de deputados. Para isso, basta uma lista de vocabulário. Já sua colega Sônia, que precisa de melhora geral no jargão regimental, prepara textos de sessões antigas para criar um modelo adaptado."}},{"id":"aut.transcricao_ia.cat_vocabulario.0005","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"A adaptação do modelo de linguagem ao vocabulário parlamentar usa textos do domínio, como transcrições de sessões, nomes de parlamentares, siglas e termos regimentais, para que o sistema atribua maior probabilidade a esses termos.","gabarito":"C","explicacao":"A adaptação usa textos do domínio (transcrições de sessões, nomes de parlamentares, siglas, termos regimentais) para que o sistema atribua maior probabilidade a esses termos, o que tende a reduzir o WER no domínio. Em sistemas end-to-end, o mesmo efeito pode ser buscado com modelo de linguagem externo acoplado ou com listas de termos.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Alimentando o sistema com textos do próprio Parlamento, ele aprende que palavras como \\"destaque\\" e \\"requerimento\\" aparecem muito ali. Assim, passa a apostar mais nelas quando ouve algo parecido.","teSitua":{"termos":[{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."},{"termo":"textos do domínio","significado":"textos da mesma área em que o sistema será usado, como atas e discursos parlamentares."},{"termo":"termos regimentais","significado":"expressões próprias do regimento da Casa, como questão de ordem e requerimento de urgência."},{"termo":"probabilidade","significado":"chance que o sistema calcula de uma palavra ou frase ser a correta."}],"exemplo":"A equipe de Rodrigo junta cinco anos de notas taquigráficas da Câmara e usa esse material para adaptar o modelo. Depois disso, o sistema deixa de escrever \\"questão de horda\\" e passa a acertar \\"questão de ordem\\"."}},{"id":"aut.transcricao_ia.cat_vocabulario.0006","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"A adaptação do modelo de linguagem ao vocabulário parlamentar, com transcrições de sessões, nomes de parlamentares e siglas, tende a elevar o WER no domínio, pois o modelo perde generalidade.","gabarito":"E","explicacao":"A adaptação com textos do domínio faz o sistema atribuir maior probabilidade aos termos parlamentares, o que tende a reduzir o WER (taxa de erro de palavra) no domínio, e não a elevá-lo. A afirmativa inverteu o efeito esperado.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Ensinar ao sistema o vocabulário do Parlamento faz ele errar menos ali, não mais. A taxa de erro de palavras cai, porque os termos da Casa passam a ser reconhecidos.","teSitua":{"termos":[{"termo":"modelo de linguagem","significado":"parte do sistema que calcula quais sequências de palavras são mais prováveis na língua."},{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra, medida de quantas palavras a máquina errou; quanto menor, melhor."},{"termo":"domínio","significado":"área de assunto em que o sistema é usado, como as sessões do Parlamento."},{"termo":"generalidade","significado":"capacidade de o sistema funcionar bem em assuntos variados, não só em um."}],"exemplo":"Antes da adaptação, o sistema da Câmara errava 18 de cada 100 palavras nas sessões. Depois que Bruno o ajustou com textos parlamentares, o erro caiu para 11 em cada 100, justamente porque os termos da Casa passaram a ser reconhecidos."}},{"id":"aut.transcricao_ia.cat_vocabulario.0007","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":2,"enunciado":"Na API de transcrição da OpenAI, o parâmetro prompt pode ser usado para ajudar o reconhecimento de nomes, siglas e vocabulário específico da gravação.","gabarito":"C","explicacao":"O parâmetro prompt da API de transcrição da OpenAI permite fornecer texto que orienta o modelo, ajudando no reconhecimento de nomes, siglas e vocabulário específico. Para o whisper-1, o limite do prompt é de 224 tokens; a API aceita arquivos de até 25 MB (mp3, mp4, mpeg, mpga, m4a, wav e webm).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário); OpenAI, documentação Speech to text (platform.openai.com/docs/guides/speech-to-text)","mastigado":"Certo. Dá para mandar junto com o áudio um pequeno texto com as palavras difíceis que vão aparecer. O modelo usa essa dica para escrever certo nomes e siglas.","teSitua":{"termos":[{"termo":"API","significado":"porta de acesso que um programa oferece para outros sistemas usarem seus serviços pela internet."},{"termo":"OpenAI","significado":"empresa americana de inteligência artificial que criou o Whisper e o ChatGPT."},{"termo":"parâmetro prompt","significado":"campo de texto enviado junto com o áudio para dar pistas ao modelo sobre o conteúdo."}],"exemplo":"Antes de enviar o áudio da audiência pública, Igor preenche o prompt com \\"Dep. Kátia Moura, CMO, PLDO, Funai\\". O modelo, que antes escrevia \\"PL do\\", passa a grafar corretamente \\"PLDO\\"."}},{"id":"aut.transcricao_ia.cat_vocabulario.0008","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"Na API de transcrição da OpenAI, o vocabulário específico da gravação deve ser informado pelo parâmetro language, já que a API não oferece campo de texto livre para orientar o reconhecimento.","gabarito":"E","explicacao":"O campo que ajuda o reconhecimento de nomes, siglas e vocabulário específico é o parâmetro prompt. O parâmetro language serve para indicar o idioma do áudio. A afirmativa trocou o parâmetro e negou a existência do prompt.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário); OpenAI, documentação Speech to text (platform.openai.com/docs/guides/speech-to-text)","mastigado":"Errado. Existe, sim, um campo livre para dar dicas ao modelo: é o prompt. O campo de idioma só diz em que língua o áudio está, e não serve para ensinar nomes e siglas.","teSitua":{"termos":[{"termo":"API","significado":"porta de acesso que um programa oferece para outros sistemas usarem seus serviços pela internet."},{"termo":"OpenAI","significado":"empresa americana de inteligência artificial que criou o Whisper e o ChatGPT."},{"termo":"parâmetro language","significado":"campo que informa ao serviço o idioma falado na gravação."}],"exemplo":"Natália preencheu só o idioma como português, e o modelo errou o nome do relator. Na segunda tentativa, ela colocou o nome do relator no prompt, e a transcrição saiu correta."}},{"id":"aut.transcricao_ia.cat_vocabulario.0009","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"Para o modelo whisper-1, na API de transcrição da OpenAI, o limite do parâmetro prompt é de 224 tokens.","gabarito":"C","explicacao":"A documentação da OpenAI informa que, para o whisper-1, o prompt é limitado a 224 tokens (o modelo considera apenas os últimos 224). O prompt ajuda no reconhecimento de nomes, siglas e vocabulário específico.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário); OpenAI, documentação Speech to text (platform.openai.com/docs/guides/speech-to-text)","mastigado":"Certo. A dica que se manda ao modelo tem tamanho máximo: 224 pedaços de texto, que é como o sistema conta as palavras. Lista de nomes muito longa acaba cortada.","teSitua":{"termos":[{"termo":"whisper-1","significado":"nome do modelo Whisper oferecido pela OpenAI em seu serviço pago pela internet."},{"termo":"API","significado":"porta de acesso que um programa oferece para outros sistemas usarem seus serviços pela internet."},{"termo":"parâmetro prompt","significado":"campo de texto enviado junto com o áudio para dar pistas ao modelo sobre o conteúdo."},{"termo":"tokens","significado":"pedaços de texto, como palavras ou partes de palavras, que o modelo usa como unidade de contagem."}],"exemplo":"Henrique colou no prompt a lista inteira dos 513 deputados. Como o whisper-1 só aproveita 224 tokens, a maior parte da lista foi ignorada. Ele passou a enviar só os nomes de quem participaria da reunião."}},{"id":"aut.transcricao_ia.cat_vocabulario.0010","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":4,"enunciado":"Para o modelo whisper-1, na API de transcrição da OpenAI, o parâmetro prompt admite até 25 mil tokens, o que permite enviar listas completas de nomes e siglas da sessão.","gabarito":"E","explicacao":"Para o whisper-1, o limite do prompt é de 224 tokens. O número 25 aparece na documentação, mas se refere ao tamanho máximo do arquivo de áudio aceito pela API (25 MB). A afirmativa trocou o limite.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário); OpenAI, documentação Speech to text (platform.openai.com/docs/guides/speech-to-text)","mastigado":"Errado. O espaço para dicas é bem pequeno: 224 tokens. O número 25 que a frase usa lembra o tamanho máximo do arquivo de áudio, 25 megas, que é outra regra.","teSitua":{"termos":[{"termo":"whisper-1","significado":"nome do modelo Whisper oferecido pela OpenAI em seu serviço pago pela internet."},{"termo":"parâmetro prompt","significado":"campo de texto enviado junto com o áudio para dar pistas ao modelo sobre o conteúdo."},{"termo":"tokens","significado":"pedaços de texto, como palavras ou partes de palavras, que o modelo usa como unidade de contagem."}],"exemplo":"Aline achou que poderia mandar no prompt o glossário inteiro da Câmara. Ao ler a documentação, viu que o limite é de 224 tokens e que o número 25 se refere aos megas do arquivo de áudio."}},{"id":"aut.transcricao_ia.cat_vocabulario.0011","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":2,"enunciado":"Os editores de transcrição com áudio sincronizado permitem ouvir o trecho correspondente a uma palavra selecionada, ajustar a velocidade de reprodução e, em alguns casos, destacar palavras de baixa confiança do ASR.","gabarito":"C","explicacao":"Esses editores exibem o texto sincronizado com o áudio: ao selecionar uma palavra, ouve-se o trecho correspondente; permitem ajustar a velocidade e, em alguns casos, destacar palavras de baixa confiança do ASR. Atalhos de teclado e pedal comandam a reprodução e aceleram a revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Nesses programas, texto e áudio andam juntos: clicou na palavra, ouve aquele pedaço. Dá para tocar mais devagar e ver em destaque as palavras de que a máquina não teve certeza.","teSitua":{"termos":[{"termo":"áudio sincronizado","significado":"gravação ligada ao texto, de modo que cada palavra corresponde a um momento exato do áudio."},{"termo":"velocidade de reprodução","significado":"rapidez com que o áudio toca, que pode ser reduzida para entender trechos difíceis."},{"termo":"baixa confiança","significado":"nota baixa que o sistema dá às palavras de que não tem certeza se reconheceu bem."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."}],"exemplo":"No editor, Vítor vê uma palavra sublinhada em amarelo, sinal de baixa confiança. Ele clica nela, ouve o trecho em velocidade reduzida e descobre que o deputado disse \\"emenda aglutinativa\\", não \\"emenda acumulativa\\"."}},{"id":"aut.transcricao_ia.cat_vocabulario.0012","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos editores de transcrição com áudio sincronizado, o pedal serve para inserir automaticamente a pontuação no texto, enquanto os atalhos de teclado trocam o orador identificado em cada trecho.","gabarito":"E","explicacao":"O pedal e os atalhos de teclado servem para comandar a reprodução do áudio (tocar, pausar, voltar alguns segundos). O pedal faz isso com os pés, mantendo as mãos livres para digitar, o que acelera a revisão. A afirmativa atribuiu-lhes funções que não têm.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. O pedal e os atalhos servem para controlar o áudio: tocar, pausar e voltar uns segundos. Com o pedal, isso é feito com o pé, e as mãos ficam livres para digitar.","teSitua":{"termos":[{"termo":"áudio sincronizado","significado":"gravação ligada ao texto, de modo que cada palavra corresponde a um momento exato do áudio."},{"termo":"pedal","significado":"aparelho no chão, acionado com o pé, que controla a reprodução do áudio durante a transcrição."},{"termo":"atalhos de teclado","significado":"combinações de teclas que fazem uma ação rápida no programa, sem usar o mouse."},{"termo":"orador","significado":"pessoa que está com a palavra e falando na sessão."}],"exemplo":"Enquanto digita a fala do deputado Sérgio, Paula aperta o pedal com o pé para voltar três segundos e ouvir de novo uma palavra. As mãos continuam no teclado, e o trabalho anda bem mais rápido."}},{"id":"aut.transcricao_ia.cat_vocabulario.0013","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"Em sistemas de ASR end-to-end, o efeito da adaptação ao vocabulário parlamentar pode ser buscado com um modelo de linguagem externo acoplado ou com listas de termos fornecidas ao reconhecedor.","gabarito":"C","explicacao":"A adaptação do modelo de linguagem com textos do domínio aumenta a probabilidade dos termos parlamentares e tende a reduzir o WER. Em sistemas end-to-end, o mesmo efeito pode ser buscado com modelo de linguagem externo acoplado ou com listas de termos fornecidas ao reconhecedor.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Mesmo nos sistemas feitos de uma peça só, dá para ensinar o jargão do Parlamento: ou se pluga um modelo de linguagem extra, ou se entrega uma lista com os termos.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."},{"termo":"modelo de linguagem externo","significado":"componente separado, ligado ao sistema, que ajuda a escolher as sequências de palavras mais prováveis."},{"termo":"reconhecedor","significado":"programa que ouve o áudio e o converte em palavras escritas."}],"exemplo":"O sistema end-to-end da Casa errava \\"destaque de bancada\\". A equipe de Leonardo acoplou um modelo de linguagem treinado com notas taquigráficas e enviou uma lista de termos regimentais. O erro sumiu."}},{"id":"aut.transcricao_ia.cat_vocabulario.0014","subtopico":"transcricao_ia.degravacao_revisao.cat_vocabulario","tipo":"certo_errado","dificuldade":3,"enunciado":"Em sistemas de ASR end-to-end, a adaptação ao vocabulário parlamentar é inviável, pois esses modelos não admitem o acoplamento de modelo de linguagem externo nem o uso de listas de termos.","gabarito":"E","explicacao":"Em sistemas end-to-end, o efeito da adaptação pode ser buscado justamente com modelo de linguagem externo acoplado ou com listas de termos fornecidas ao reconhecedor. A afirmativa negou essas duas possibilidades.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Os sistemas de uma peça só também podem aprender o vocabulário do Parlamento. Para isso, liga-se um modelo de linguagem extra ou envia-se uma lista de termos.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"end-to-end","significado":"sistema de uma só rede neural que vai direto do áudio ao texto, sem módulos separados."},{"termo":"acoplamento","significado":"ligação de um componente extra ao sistema principal, para os dois trabalharem juntos."},{"termo":"modelo de linguagem externo","significado":"componente separado, ligado ao sistema, que ajuda a escolher as sequências de palavras mais prováveis."}],"exemplo":"Um fornecedor disse a Juliana que seu sistema end-to-end não podia aprender nomes de deputados. Ela mostrou na documentação que bastava enviar uma lista de frases ao reconhecedor, recurso que o próprio serviço oferecia."}},{"id":"aut.transcricao_ia.diarizacao.0005","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A diarização de falantes divide o áudio em segmentos e os atribui a cada falante, respondendo à pergunta \\"quem falou quando\\", com rótulos anônimos como Falante 1 e Falante 2.","gabarito":"C","explicacao":"Diarização é a tarefa de dividir o áudio em segmentos e atribuí-los a cada falante, respondendo \\"quem falou quando\\" (who spoke when). O resultado são rótulos anônimos (Falante 1, Falante 2). Ela não revela a identidade real de cada voz; isso cabe à identificação de falante ou ao cruzamento com outras informações da sessão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. A diarização separa o áudio por voz e diz em que momentos cada voz falou. Mas ela só numera as vozes; não sabe o nome de ninguém.","teSitua":{"termos":[{"termo":"diarização de falantes","significado":"separação automática do áudio por voz, indicando quem falou em cada trecho."},{"termo":"segmentos","significado":"pedaços em que o áudio é dividido, cada um com início e fim."},{"termo":"rótulos anônimos","significado":"nomes genéricos, como Falante 1, dados a cada voz sem saber quem ela é."}],"exemplo":"Na transcrição da audiência, o sistema marca \\"Falante 1: 0 a 45 s; Falante 2: 45 a 70 s\\". É a revisora Marina quem, olhando a lista de presença, troca os rótulos pelos nomes dos deputados."}},{"id":"aut.transcricao_ia.diarizacao.0006","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A diarização de falantes revela a identidade real de cada voz da gravação, dispensando o cruzamento com outras informações da sessão para saber quem falou.","gabarito":"E","explicacao":"A diarização produz rótulos anônimos (Falante 1, Falante 2) e não revela a identidade real de cada voz; isso cabe à identificação de falante ou ao cruzamento com outras informações da sessão. A afirmativa confundiu diarização com identificação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. A diarização só separa e numera as vozes. Para saber que o Falante 2 é a deputada Fulana, é preciso outra ferramenta ou conferir com dados da sessão, como a ordem dos inscritos.","teSitua":{"termos":[{"termo":"diarização de falantes","significado":"separação automática do áudio por voz, indicando quem falou em cada trecho."},{"termo":"identidade real","significado":"quem a pessoa é de fato, com nome e cargo."}],"exemplo":"O sistema entregou o áudio separado em quatro vozes, sem nomes. Para identificar cada uma, o revisor Paulo cruzou os horários com a lista de oradores inscritos no painel da sessão."}},{"id":"aut.transcricao_ia.diarizacao.0007","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na diarização por agrupamento, a detecção de atividade de voz separa fala de silêncio e ruído antes da segmentação, da extração de embeddings de voz e do agrupamento dos trechos por falante.","gabarito":"C","explicacao":"Etapas típicas: (1) detecção de atividade de voz, que separa fala de silêncio e ruído; (2) segmentação em trechos curtos; (3) extração de embeddings de voz, vetores que resumem as características da voz de cada trecho; (4) agrupamento (clustering) dos embeddings, cada grupo correspondendo a um falante. O resultado são rótulos atribuídos a intervalos de tempo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Primeiro o sistema descobre onde há fala e onde há silêncio. Depois corta a fala em pedaços, tira uma \\"impressão digital\\" da voz de cada um e junta os pedaços parecidos.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"agrupamento","significado":"reunião automática de itens parecidos em grupos, sem saber antes quais são os grupos."},{"termo":"detecção de atividade de voz","significado":"etapa que identifica em que partes do áudio há fala e em quais há só silêncio ou barulho."},{"termo":"embeddings de voz","significado":"listas de números que resumem as características de uma voz, como uma impressão digital sonora."}],"exemplo":"Na gravação da reunião, o sistema primeiro descarta os silêncios e o barulho de cadeiras. Depois corta a fala em trechos de dois segundos, calcula a impressão de voz de cada um e junta os parecidos. Assim, Rodrigo recebe três grupos, um por falante."}},{"id":"aut.transcricao_ia.diarizacao.0008","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na diarização por agrupamento, a detecção de atividade de voz é a última etapa, responsável por atribuir o nome real do orador a cada grupo de embeddings.","gabarito":"E","explicacao":"A detecção de atividade de voz é a primeira etapa: separa fala de silêncio e ruído. Seguem-se a segmentação, a extração de embeddings e o agrupamento. O resultado são rótulos anônimos (Falante 1, Falante 2), sem a identidade real. A afirmativa errou a posição e a função da etapa.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Detectar onde há voz é o primeiro passo, não o último. E nenhuma etapa da diarização dá nome às vozes: o resultado é só Falante 1, Falante 2 e assim por diante.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"detecção de atividade de voz","significado":"etapa que identifica em que partes do áudio há fala e em quais há só silêncio ou barulho."},{"termo":"embeddings","significado":"listas de números que resumem as características de uma voz, como uma impressão digital sonora."}],"exemplo":"Ao ver o fluxograma do fornecedor, a analista Gisele estranhou a detecção de voz no fim da cadeia. No sistema certo, ela vem antes de tudo, para descartar os silêncios, e o resultado final são vozes numeradas, sem nomes."}},{"id":"aut.transcricao_ia.diarizacao.0009","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Em sistemas clássicos de diarização, cada trecho recebe um único rótulo de falante, de modo que, na sobreposição de falas, uma das vozes tende a ser perdida ou atribuída de forma errada.","gabarito":"C","explicacao":"Quando duas pessoas falam ao mesmo tempo, os sinais se misturam: em sistemas clássicos, cada trecho recebe um único rótulo, e uma das vozes é perdida ou a atribuição sai errada; o ASR também tende a errar as palavras. Abordagens neurais mais recentes conseguem atribuir mais de um falante ao mesmo instante. Apartes e interrupções são situações típicas.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Quando duas pessoas falam juntas, o sistema antigo só consegue marcar um nome por trecho. Aí uma voz some ou vai para a pessoa errada, e as palavras também saem trocadas.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"rótulo de falante","significado":"marcação que indica qual voz está falando num trecho, como Falante 1."},{"termo":"sobreposição de falas","significado":"situação em que duas ou mais pessoas falam ao mesmo tempo."}],"exemplo":"Durante o discurso do deputado Elias, a deputada Joice faz um aparte ao mesmo tempo. O sistema clássico marca o trecho todo como de Elias, e as palavras de Joice somem. A revisora Taís precisa ouvir e reconstituir as duas falas."}},{"id":"aut.transcricao_ia.diarizacao.0010","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Nenhuma abordagem de diarização consegue atribuir mais de um falante ao mesmo instante, razão pela qual a sobreposição de falas não afeta a precisão do reconhecimento das palavras.","gabarito":"E","explicacao":"Abordagens neurais mais recentes de diarização conseguem, sim, atribuir mais de um falante ao mesmo instante. E a sobreposição afeta o reconhecimento: com os sinais misturados, o ASR tende a errar as palavras do trecho. A afirmativa errou nas duas partes.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Os sistemas neurais mais novos já conseguem marcar duas vozes ao mesmo tempo. E fala sobreposta atrapalha, sim, o reconhecimento das palavras, porque os sons se misturam.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"sobreposição de falas","significado":"situação em que duas ou mais pessoas falam ao mesmo tempo."},{"termo":"precisão","significado":"grau de acerto do sistema em relação ao que realmente foi dito."}],"exemplo":"No bate-boca entre dois deputados, o texto da máquina saiu cheio de palavras sem sentido. O técnico Vinícius explicou que a fala sobreposta confunde o reconhecimento e que o sistema novo, neural, ao menos marca as duas vozes no mesmo trecho."}},{"id":"aut.transcricao_ia.diarizacao.0011","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na diarização por agrupamento, cada trecho de fala é convertido em um embedding de voz, vetor que resume as características da voz daquele trecho.","gabarito":"C","explicacao":"Na diarização por agrupamento, cada trecho de fala é convertido em um embedding de voz, e os embeddings semelhantes são reunidos por clustering, formando um grupo por falante. Antes, a detecção de atividade de voz separa fala de silêncio e a segmentação divide a fala em trechos curtos.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Cada pedacinho de fala vira uma lista de números que resume como aquela voz soa. É com esses números que o sistema compara os trechos e descobre quais são da mesma pessoa.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"agrupamento","significado":"reunião automática de itens parecidos em grupos, sem saber antes quais são os grupos."},{"termo":"embedding de voz","significado":"lista de números que resume as características de uma voz, como uma impressão digital sonora."},{"termo":"vetor","significado":"lista ordenada de números que representa uma informação."}],"exemplo":"O trecho em que a deputada Lorena fala de saúde e o trecho em que ela fala de educação geram embeddings de voz parecidos, porque a voz é a mesma. O sistema de Ulisses junta os dois no mesmo grupo."}},{"id":"aut.transcricao_ia.diarizacao.0012","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na diarização por agrupamento, cada trecho de fala é primeiro convertido em texto pelo ASR, e os textos de conteúdo semelhante são reunidos, formando um grupo por falante.","gabarito":"E","explicacao":"A diarização por agrupamento compara vozes, não textos: cada trecho é convertido em um embedding de voz, e os embeddings semelhantes são reunidos por clustering, um grupo por falante. A afirmativa trocou o embedding de voz pelo texto transcrito.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. A diarização agrupa pelo jeito da voz, e não pelo assunto falado. Duas pessoas falando do mesmo tema continuam sendo duas vozes diferentes.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"agrupamento","significado":"reunião automática de itens parecidos em grupos, sem saber antes quais são os grupos."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."}],"exemplo":"Dois deputados, Nestor e Abel, falam sobre o mesmo projeto. Se a diarização agrupasse por assunto, juntaria os dois. Como ela compara as vozes, o sistema de Clarice os separa em Falante 1 e Falante 2."}},{"id":"aut.transcricao_ia.diarizacao.0013","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Na diarização por agrupamento, os embeddings de voz semelhantes são reunidos por clustering, formando um grupo por falante, ao qual se atribui um rótulo anônimo.","gabarito":"C","explicacao":"Os embeddings de voz semelhantes são reunidos por clustering, formando um grupo por falante. O resultado são rótulos anônimos (Falante 1, Falante 2), sem a identidade real de cada falante.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Os trechos com voz parecida são juntados num mesmo grupo, e cada grupo é uma pessoa. O grupo ganha só um número, como Falante 1, e não um nome.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"embeddings de voz","significado":"listas de números que resumem as características de uma voz, como uma impressão digital sonora."},{"termo":"clustering","significado":"técnica que junta automaticamente itens parecidos em grupos."},{"termo":"rótulo anônimo","significado":"nome genérico, como Falante 1, dado a uma voz sem saber quem ela é."}],"exemplo":"Na reunião com cinco participantes, o clustering formou cinco grupos de trechos. Cada um saiu como Falante 1 a Falante 5, e a revisora Lia associou os números aos nomes."}},{"id":"aut.transcricao_ia.diarizacao.0014","subtopico":"transcricao_ia.reconhecimento_fala.diarizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Na diarização por agrupamento, os embeddings de voz são reunidos por clustering de modo que cada grupo corresponda a um tema discutido na sessão, e não a um falante.","gabarito":"E","explicacao":"Os embeddings de voz semelhantes são reunidos por clustering formando um grupo por falante, e não por tema. Os embeddings de voz resumem características da voz, não do conteúdo. A afirmativa trocou falante por tema.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Cada grupo é uma pessoa, porque o sistema compara vozes, e não assuntos. Separar por tema seria outra tarefa, feita sobre o texto.","teSitua":{"termos":[{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"embeddings de voz","significado":"listas de números que resumem as características de uma voz, como uma impressão digital sonora."},{"termo":"clustering","significado":"técnica que junta automaticamente itens parecidos em grupos."}],"exemplo":"Raul esperava que a diarização separasse a sessão em \\"saúde\\" e \\"orçamento\\". Recebeu, em vez disso, um grupo para cada deputado que falou. Para separar por assunto, ele precisaria classificar o texto."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0004","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"Como a proteção autoral brasileira pressupõe criação do espírito humano, o conteúdo produzido autonomamente por inteligência artificial não se enquadra com naturalidade na tutela autoral.","gabarito":"C","explicacao":"A Lei 9.610/1998 protege as criações do espírito (art. 7º) e considera autor a pessoa física criadora (art. 11). Por isso, o conteúdo produzido autonomamente por máquina não se enquadra com naturalidade na tutela autoral. O debate persiste e envolve a contribuição criativa humana na concepção e na edição; o uso de obras protegidas no treinamento é discussão distinta e também controvertida.","fonte":"Lei 9.610/1998, arts. 7º e 11; Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Direitos Autorais e Ética)","mastigado":"Certo. A lei de direitos autorais do Brasil protege o que nasce da criatividade de uma pessoa. O que a máquina faz sozinha não cabe direito nessa proteção, embora o assunto ainda esteja em debate.","teSitua":{"termos":[{"termo":"proteção autoral","significado":"conjunto de direitos que a lei dá ao criador de uma obra, como decidir quem pode copiá-la."},{"termo":"criação do espírito","significado":"obra que nasce da inteligência e da criatividade de uma pessoa, como um texto ou uma música."},{"termo":"inteligência artificial","significado":"sistemas de computador capazes de fazer tarefas que antes exigiam raciocínio humano."},{"termo":"tutela autoral","significado":"proteção que a lei de direitos autorais dá a uma obra e a seu autor."}],"exemplo":"Bernardo pediu a um sistema de IA um poema e, sem mexer em nada, tentou registrá-lo como obra sua. O advogado Ronaldo explicou que, sem contribuição criativa humana, dificilmente o texto teria a proteção da lei de direitos autorais."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0005","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"Pela lei brasileira de direitos autorais, o conteúdo gerado autonomamente por inteligência artificial pertence, como autora, à empresa desenvolvedora do sistema, questão já pacificada na doutrina.","gabarito":"E","explicacao":"A Lei 9.610/1998 considera autor a pessoa física criadora de obra (art. 11) e protege criações do espírito (art. 7º). O conteúdo produzido autonomamente por máquina não se enquadra com naturalidade na tutela autoral, e o debate persiste, envolvendo a contribuição criativa humana. Não há autoria atribuída à desenvolvedora nem tema pacificado.","fonte":"Lei 9.610/1998, arts. 7º e 11; Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Direitos Autorais e Ética)","mastigado":"Errado. A lei só reconhece como autor uma pessoa que cria. A empresa que fez o sistema não vira autora do que a máquina gera, e o assunto está longe de ser consenso.","teSitua":{"termos":[{"termo":"direitos autorais","significado":"direitos que a lei garante ao criador de uma obra sobre seu uso, cópia e divulgação."},{"termo":"inteligência artificial","significado":"sistemas de computador capazes de fazer tarefas que antes exigiam raciocínio humano."},{"termo":"doutrina","significado":"conjunto de estudos e opiniões de especialistas em Direito sobre um tema."},{"termo":"pacificada","significado":"sem controvérsia, aceita de forma ampla e estável."}],"exemplo":"A empresa Gama, criadora de um gerador de imagens, quis cobrar como autora de todas as ilustrações feitas pela ferramenta. A advogada Selma lembrou que a lei exige autor pessoa física e que o tema ainda está em debate."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0006","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"Na Câmara dos Deputados, as diretrizes da política de governança de inteligência artificial incluem supervisão humana, transparência, observância da LGPD e o dever de informar o usuário quando ele interagir com agentes de IA.","gabarito":"C","explicacao":"O Ato da Mesa nº 225/2025 fixa as diretrizes gerais da política de governança de IA da Câmara: boa-fé, transparência e supervisão humana; avaliação de riscos, análise de impactos e rastreabilidade; observância da LGPD; regras próprias para IA generativa; vedação a sistemas com resultados discriminatórios, danosos ou enviesados; supervisão contínua de falhas, vieses e alucinações; e dever de informar o usuário quando interagir com agentes de IA (art. 3º).","fonte":"Câmara dos Deputados, Ato da Mesa nº 225, de 15/12/2025, art. 3º; Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Direitos Autorais e Ética)","mastigado":"Certo. As regras da Câmara pedem que sempre haja uma pessoa supervisionando, que o uso seja transparente, que se respeite a lei de dados pessoais e que o cidadão saiba quando está falando com uma máquina.","teSitua":{"termos":[{"termo":"governança","significado":"conjunto de regras e responsáveis que orientam e controlam o uso de algo numa instituição."},{"termo":"supervisão humana","significado":"acompanhamento por uma pessoa, que confere e pode corrigir o que a máquina faz."},{"termo":"LGPD","significado":"Lei Geral de Proteção de Dados, que regula o uso de informações pessoais no Brasil."},{"termo":"agentes de IA","significado":"sistemas de inteligência artificial que conversam ou agem em nome da instituição, como um assistente virtual."}],"exemplo":"Ao abrir o assistente virtual do site da Câmara, a cidadã Irene vê o aviso de que está conversando com um sistema de IA. Por trás, uma equipe acompanha as respostas e corrige falhas, como mandam as diretrizes da Casa."}},{"id":"aut.transcricao_ia.direitos_autorais_etica.0007","subtopico":"transcricao_ia.protecao_etica.direitos_autorais_etica","tipo":"certo_errado","dificuldade":3,"enunciado":"Na Câmara dos Deputados, a política de governança de inteligência artificial transfere ao sistema a responsabilidade pela versão final do conteúdo quando há supervisão contínua de falhas e vieses.","gabarito":"E","explicacao":"O Ato da Mesa nº 225/2025 exige supervisão humana e distribui papéis e responsabilidades definidos entre gestores e áreas; o Manual de Comunicação da Câmara reforça que a IA é complementar ao trabalho humano e que o conteúdo passa por checagem antes da divulgação. A responsabilidade pela versão final permanece humana e não se transfere ao sistema.","fonte":"Câmara dos Deputados, Ato da Mesa nº 225, de 15/12/2025, art. 3º; Manual de Comunicação da Câmara; baralho Anki Câmara 2026, cargo 11 (Direitos Autorais e Ética)","mastigado":"Errado. A supervisão de falhas é feita justamente por pessoas, e a responsabilidade pelo texto final continua delas. A máquina é complemento do trabalho humano, nunca a responsável.","teSitua":{"termos":[{"termo":"governança","significado":"conjunto de regras e responsáveis que orientam e controlam o uso de algo numa instituição."},{"termo":"inteligência artificial","significado":"sistemas de computador capazes de fazer tarefas que antes exigiam raciocínio humano."},{"termo":"vieses","significado":"distorções sistemáticas nos resultados da IA, que favorecem ou prejudicam certos grupos ou ideias."}],"exemplo":"Uma notícia do portal da Câmara, rascunhada por IA, saiu com um dado errado. Na apuração, ficou claro que a responsabilidade era do jornalista Valdir, que deveria ter checado as fontes antes de publicar."}},{"id":"aut.transcricao_ia.ferramentas_apis.0003","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, é um modelo de ASR de código aberto que faz transcrição em vários idiomas, tradução para o inglês e identificação do idioma, mas não realiza diarização de falantes por si só.","gabarito":"C","explicacao":"O Whisper é um modelo de ASR de código aberto (código e pesos sob licença MIT), codificador-decodificador baseado em Transformer, treinado com cerca de 680 mil horas de áudio multilíngue e multitarefa. Faz transcrição em vários idiomas (inclusive o português), tradução para o inglês e identificação do idioma; processa o áudio em janelas de 30 segundos; roda localmente ou pela API (whisper-1). Não faz diarização por si só.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); OpenAI, repositório github.com/openai/whisper","mastigado":"Certo. O Whisper transcreve em muitas línguas, traduz para o inglês e descobre em que idioma a pessoa está falando. Só não separa as vozes: para saber quem falou, é preciso outra ferramenta.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"OpenAI","significado":"empresa americana de inteligência artificial que criou o Whisper e o ChatGPT."},{"termo":"código aberto","significado":"programa cujo código pode ser visto, usado e modificado livremente por qualquer pessoa."},{"termo":"diarização de falantes","significado":"separação automática do áudio por voz, indicando quem falou em cada trecho."}],"exemplo":"A equipe de Raquel usa o Whisper para transcrever audiências com convidados estrangeiros e traduzir as falas para o inglês. Para separar quem falou, ela combina o Whisper com outra ferramenta de diarização."}},{"id":"aut.transcricao_ia.ferramentas_apis.0004","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, processa o áudio em janelas de 30 segundos e realiza nativamente a diarização de falantes, identificando quem falou em cada trecho da gravação.","gabarito":"E","explicacao":"O Whisper processa o áudio em janelas de 30 segundos, mas não faz diarização de falantes por si só; para atribuir os trechos a cada falante, é preciso combiná-lo com outra ferramenta. A afirmativa atribuiu-lhe um recurso que ele não tem.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); OpenAI, repositório github.com/openai/whisper","mastigado":"Errado. A parte das janelas de 30 segundos está certa, mas o Whisper não separa as vozes sozinho. Ele entrega o texto sem dizer quem falou cada parte.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"janelas","significado":"pedaços de tamanho fixo em que o áudio é cortado para ser processado."},{"termo":"diarização de falantes","significado":"separação automática do áudio por voz, indicando quem falou em cada trecho."}],"exemplo":"Elton transcreveu uma reunião de quatro pessoas com o Whisper e recebeu um texto corrido, sem indicação de quem falou. Para separar as vozes, teve de usar uma ferramenta de diarização à parte."}},{"id":"aut.transcricao_ia.ferramentas_apis.0005","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, foi treinado com cerca de 680 mil horas de áudio multilíngue e multitarefa.","gabarito":"C","explicacao":"O Whisper foi treinado de forma supervisionada com cerca de 680 mil horas de áudio multilíngue e multitarefa; seu código e seus pesos são distribuídos sob a licença MIT. Processa o áudio em janelas de 30 segundos.","fonte":"Radford et al., Robust Speech Recognition via Large-Scale Weak Supervision (OpenAI, 2022); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O Whisper aprendeu ouvindo uma quantidade enorme de áudio, cerca de 680 mil horas, em muitas línguas e para várias tarefas, como transcrever e traduzir.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"multilíngue","significado":"em vários idiomas ao mesmo tempo."},{"termo":"multitarefa","significado":"usado para treinar o modelo em várias tarefas, como transcrever, traduzir e identificar o idioma."}],"exemplo":"Para ter ideia do tamanho do treino do Whisper, o professor Anselmo fez a conta: 680 mil horas de áudio equivalem a mais de 77 anos ouvindo sem parar."}},{"id":"aut.transcricao_ia.ferramentas_apis.0006","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, foi treinado com cerca de 68 mil horas de áudio exclusivamente em inglês, razão pela qual não transcreve outros idiomas.","gabarito":"E","explicacao":"O Whisper foi treinado com cerca de 680 mil horas de áudio multilíngue e multitarefa, e transcreve vários idiomas, inclusive o português. A afirmativa trocou o volume de dados (68 mil em vez de 680 mil horas) e negou o caráter multilíngue.","fonte":"Radford et al., Robust Speech Recognition via Large-Scale Weak Supervision (OpenAI, 2022); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Foram cerca de 680 mil horas, dez vezes mais que o dito, e em muitas línguas. Tanto que o Whisper transcreve português e vários outros idiomas.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"OpenAI","significado":"empresa americana de inteligência artificial que criou o Whisper e o ChatGPT."}],"exemplo":"O analista Germano usa o Whisper para transcrever sessões em português e entrevistas em espanhol. Isso só é possível porque o modelo foi treinado com 680 mil horas de áudio em várias línguas."}},{"id":"aut.transcricao_ia.ferramentas_apis.0007","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O código e os pesos do Whisper, da OpenAI, são distribuídos sob a licença MIT, o que permite executar o modelo localmente, sem enviar o áudio a um serviço de terceiros.","gabarito":"C","explicacao":"O código e os pesos do Whisper estão sob a licença MIT. O caráter aberto permite executar o modelo localmente, sem enviar o áudio a um serviço de terceiros, o que também importa para a proteção de dados.","fonte":"OpenAI, repositório github.com/openai/whisper (licença MIT); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Como o Whisper é aberto, qualquer órgão pode instalá-lo nos próprios computadores. Assim, o áudio das reuniões não precisa sair de casa para ser transcrito.","teSitua":{"termos":[{"termo":"pesos","significado":"números aprendidos no treino que fazem o modelo funcionar; ter os pesos é ter o modelo pronto."},{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"licença MIT","significado":"licença de software livre bem permissiva, que deixa usar, modificar e distribuir o programa."},{"termo":"localmente","significado":"nos computadores do próprio usuário, sem depender de serviço pela internet."}],"exemplo":"Para transcrever reuniões reservadas, a equipe de Lucinda instalou o Whisper nos servidores da própria Casa. Como a licença MIT permite, o áudio nunca foi enviado a uma empresa externa."}},{"id":"aut.transcricao_ia.ferramentas_apis.0008","subtopico":"transcricao_ia.reconhecimento_fala.ferramentas_apis","tipo":"certo_errado","dificuldade":3,"enunciado":"O Whisper, da OpenAI, é um modelo proprietário, com pesos fechados e acessível apenas pela API da empresa, o que impede sua execução local.","gabarito":"E","explicacao":"O código e os pesos do Whisper são distribuídos sob a licença MIT, e o modelo pode ser executado localmente, em tamanhos variados, além de ser acessível pela API da OpenAI (whisper-1). A afirmativa descreveu um modelo fechado.","fonte":"OpenAI, repositório github.com/openai/whisper (licença MIT); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O Whisper é aberto: o código e o próprio modelo estão disponíveis de graça. Dá para usar pela internet, na API da empresa, ou instalar no próprio computador.","teSitua":{"termos":[{"termo":"Whisper","significado":"modelo de reconhecimento de fala da OpenAI, de código aberto, que funciona em muitos idiomas."},{"termo":"proprietário","significado":"programa fechado, de uso controlado pela empresa dona, sem acesso livre ao código."},{"termo":"pesos","significado":"números aprendidos no treino que fazem o modelo funcionar; ter os pesos é ter o modelo pronto."},{"termo":"API","significado":"porta de acesso que um programa oferece para outros sistemas usarem seus serviços pela internet."}],"exemplo":"O gestor Teodoro achou que precisaria contratar a API para usar o Whisper. O técnico Vagner baixou o modelo do repositório oficial e o rodou no notebook da equipe, sem custo e sem internet."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0007","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":2,"enunciado":"Na formatação de transcrições parlamentares, as manifestações do Plenário, como palmas, vaias e risos, são registradas em indicação distinta da fala do orador, e os apartes trazem o aparteante identificado.","gabarito":"C","explicacao":"As convenções variam por órgão, mas em geral incluem: identificação do orador a cada troca de fala; marcação de apartes, com o aparteante identificado e a retomada da palavra pelo orador; indicação de ruído, pausa e trecho inaudível por marcação convencionada; e registro das manifestações do Plenário (palmas, vaias, risos) em indicação distinta da fala.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Palmas e vaias não são palavras do orador, então aparecem separadas, numa marcação própria. E quando outro parlamentar interrompe com um aparte, o texto diz quem foi.","teSitua":{"termos":[{"termo":"manifestações do Plenário","significado":"reações dos presentes na sessão, como aplausos, vaias e risos, que não fazem parte do discurso."},{"termo":"orador","significado":"pessoa que está com a palavra e falando na sessão."},{"termo":"apartes","significado":"interrupções breves de outro parlamentar no meio do discurso, com permissão do orador."},{"termo":"aparteante","significado":"parlamentar que faz o aparte, interrompendo o orador para comentar."}],"exemplo":"No discurso do deputado Hélio, a deputada Vera pede um aparte. A transcrição registra o nome dela antes da fala e, quando o Plenário aplaude, anota \\"(Palmas.)\\" entre parênteses, separado das palavras de Hélio."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0008","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":2,"enunciado":"Na formatação de transcrições parlamentares, os apartes são incorporados à fala do orador sem identificação do aparteante, para preservar a continuidade do discurso.","gabarito":"E","explicacao":"As convenções em geral exigem a marcação dos apartes, com o aparteante identificado e a retomada da palavra pelo orador. Fundir o aparte à fala do orador, sem dizer quem o fez, atribuiria a um parlamentar palavras de outro. A afirmativa contraria a regra.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Se o aparte fosse misturado ao discurso, pareceria que o orador disse algo que foi dito por outra pessoa. Por isso o texto marca o aparte e diz quem falou.","teSitua":{"termos":[{"termo":"apartes","significado":"interrupções breves de outro parlamentar no meio do discurso, com permissão do orador."},{"termo":"orador","significado":"pessoa que está com a palavra e falando na sessão."},{"termo":"aparteante","significado":"parlamentar que faz o aparte, interrompendo o orador para comentar."}],"exemplo":"O deputado Mauro discursa contra o projeto e o deputado Álvaro, a favor, faz um aparte. Se o texto juntasse as duas falas, Mauro pareceria defender o projeto. Por isso a revisora Cíntia marca o aparte com o nome de Álvaro."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0009","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":2,"enunciado":"Quando um trecho da gravação não pode ser compreendido, a transcrição registra o trecho inaudível por marcação convencionada, em vez de inventar o conteúdo.","gabarito":"C","explicacao":"O trecho que não pode ser compreendido é indicado como inaudível por marcação convencionada, sem inventar o conteúdo. A mesma lógica vale para ruído e pausa: a marcação segue a convenção do órgão e não altera o que foi dito.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Se não deu para ouvir, o texto avisa que não deu para ouvir, com a marca combinada pelo órgão. Ninguém pode chutar o que o orador teria dito.","teSitua":{"termos":[{"termo":"trecho inaudível","significado":"parte da gravação em que não se consegue entender o que foi falado."},{"termo":"marcação convencionada","significado":"sinal padronizado pelo órgão, como uma palavra entre parênteses, para indicar algo no texto."}],"exemplo":"No meio da fala do deputado Wagner, um microfone chia e três palavras se perdem. A transcritora Elisa não tenta adivinhar: escreve \\"(Inaudível.)\\" no ponto, como manda o manual."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0010","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":2,"enunciado":"Quando um trecho da gravação não pode ser compreendido, o revisor deve reconstituir o conteúdo provável a partir do contexto do discurso, dispensando qualquer marcação no texto.","gabarito":"E","explicacao":"O trecho inaudível é registrado por marcação convencionada, em vez de inventar o conteúdo. Reconstituir o \\"provável\\" pelo contexto é justamente inventar, o que fere a fidelidade ao que foi dito. A afirmativa trocou a marcação pela reconstrução.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Deduzir pelo contexto o que a pessoa teria dito é inventar. O certo é marcar que aquele pedaço ficou sem entendimento, seguindo o padrão do órgão.","teSitua":{"termos":[{"termo":"revisor","significado":"profissional que confere o texto com o áudio e corrige erros."},{"termo":"reconstituir","significado":"montar de novo algo que se perdeu, a partir de pistas."},{"termo":"contexto do discurso","significado":"o que vem antes e depois na fala, que ajuda a entender o assunto."}],"exemplo":"Pela lógica da fala, o revisor Otávio achou que o deputado tinha dito \\"sou contra\\". Mas o áudio estava encoberto por vaias. Em vez de completar, ele marcou o trecho como inaudível, preservando a fidelidade."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0011","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":2,"enunciado":"Assim como o trecho inaudível, o ruído e a pausa são indicados na transcrição por marcação que segue a convenção do órgão, sem alterar o que foi dito.","gabarito":"C","explicacao":"A lógica aplicada ao trecho inaudível vale para ruído e pausa: a marcação segue a convenção do órgão e não altera o que foi dito. O texto não inventa conteúdo nem disfarça a interrupção.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Barulho e silêncio também ganham uma marca combinada no texto. Assim o leitor sabe o que aconteceu, e as palavras do orador ficam como foram ditas.","teSitua":{"termos":[{"termo":"trecho inaudível","significado":"parte da gravação em que não se consegue entender o que foi falado."},{"termo":"ruído","significado":"barulho que atrapalha a gravação, como microfonia, conversas paralelas ou batidas."},{"termo":"convenção do órgão","significado":"regra padronizada pela instituição sobre como escrever ou marcar algo no texto."}],"exemplo":"Durante a fala da deputada Sandra, o som cai por alguns segundos e depois há uma pausa longa. A revisora Teresa registra cada coisa com a marcação do manual, sem mexer nas frases de Sandra."}},{"id":"aut.transcricao_ia.formatacao_parlamentar.0012","subtopico":"transcricao_ia.degravacao_revisao.formatacao_parlamentar","tipo":"certo_errado","dificuldade":3,"enunciado":"Por não fazerem parte da fala, o ruído e a pausa nunca são indicados na transcrição parlamentar, reservando-se a marcação convencionada exclusivamente aos trechos inaudíveis.","gabarito":"E","explicacao":"A marcação convencionada não é exclusiva dos trechos inaudíveis: ruído e pausa também são indicados, segundo a convenção do órgão, sem alterar o que foi dito. A afirmativa restringiu indevidamente a regra.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Não é só o trecho que ninguém entendeu que ganha marca. Barulho e pausa também são indicados no texto, do jeito que o órgão padronizou.","teSitua":{"termos":[{"termo":"ruído","significado":"barulho que atrapalha a gravação, como microfonia, conversas paralelas ou batidas."},{"termo":"marcação convencionada","significado":"sinal padronizado pelo órgão, como uma palavra entre parênteses, para indicar algo no texto."},{"termo":"trechos inaudíveis","significado":"partes da gravação em que não se consegue entender o que foi falado."}],"exemplo":"Na reunião da Comissão, um alarme toca por um minuto. O revisor Diogo não ignora o fato: registra a interrupção com a marcação de ruído do manual, para o leitor entender por que a fala foi cortada."}},{"id":"aut.transcricao_ia.human_in_the_loop.0003","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo de transcrição assistido por IA com humano no circuito, a qualidade da captura do áudio define o piso de qualidade do resultado, e a validação final cabe a pessoa responsável.","gabarito":"C","explicacao":"As etapas do fluxo são: (1) captura do áudio, cuja qualidade define o piso de qualidade do resultado; (2) transcrição automática (ASR, em geral com diarização e pontuação); (3) revisão, com conferência do texto com o áudio; (4) edição, com convenções, normalização e formatação; (5) validação, aprovação final por pessoa responsável. O humano decide e responde pelo texto final; a IA acelera o trabalho.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Se o som foi mal gravado, nenhuma etapa seguinte faz milagre: a captação define o mínimo de qualidade possível. E no fim do caminho é sempre uma pessoa quem aprova o texto.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"captura do áudio","significado":"gravação do som da sessão, com microfones e equipamentos de captação."},{"termo":"piso de qualidade","significado":"nível mínimo que o resultado pode alcançar, limitado pela etapa mais fraca."},{"termo":"validação final","significado":"aprovação do texto por uma pessoa responsável, antes de ele ser publicado como oficial."}],"exemplo":"Numa audiência fora da Câmara, o microfone ficou longe dos convidados. O sistema errou muito, e a revisora Débora precisou de horas para corrigir. No fim, a chefe Cecília validou o texto e assinou como responsável."}},{"id":"aut.transcricao_ia.human_in_the_loop.0004","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo de transcrição assistido por IA com humano no circuito, a responsabilidade pelo texto final é transferida ao sistema de ASR, cabendo ao humano apenas a captura do áudio.","gabarito":"E","explicacao":"No fluxo com humano no circuito, o humano decide e responde pelo texto final: revisa, edita e valida. A IA acelera o trabalho, mas a responsabilidade não se transfere ao sistema. A afirmativa inverteu os papéis.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. A máquina ajuda a ir mais rápido, mas quem responde pelo texto é a pessoa que revisa e aprova. Não dá para culpar o sistema por um erro publicado.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"captura do áudio","significado":"gravação do som da sessão, com microfones e equipamentos de captação."}],"exemplo":"Um texto publicado trouxe um voto trocado. Na apuração, o servidor Anderson disse que o erro foi do sistema. A diretora Raquel lembrou que quem validou o texto responde por ele: a IA só produziu a primeira versão."}},{"id":"aut.transcricao_ia.human_in_the_loop.0005","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo assistido por IA com humano no circuito, as etapas são: captura do áudio, transcrição automática, revisão, edição e validação.","gabarito":"C","explicacao":"A sequência do fluxo é captura do áudio, transcrição automática (ASR), revisão (conferência com o áudio), edição (convenções, normalização, formatação) e validação (aprovação final). O sistema acelera o trabalho, mas a decisão e a responsabilidade pelo texto final permanecem com quem revisa e valida.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Primeiro grava-se o som; a máquina transcreve; uma pessoa confere com o áudio; depois arruma o texto no padrão do órgão; e, por fim, alguém responsável aprova.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"transcrição automática","significado":"texto produzido sozinho pelo computador a partir do áudio, sem tratamento humano."},{"termo":"validação","significado":"aprovação final do texto por uma pessoa responsável, antes de ele virar oficial."}],"exemplo":"A sessão é gravada; em minutos, o sistema entrega o texto. Henrique revisa ouvindo o áudio, Priscila edita conforme o manual e a coordenadora Simone valida. Só então o discurso entra no Diário da Câmara."}},{"id":"aut.transcricao_ia.human_in_the_loop.0006","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo assistido por IA com humano no circuito, a etapa de transcrição manual precede a captura do áudio, e só depois o sistema de ASR revisa o texto produzido pela pessoa.","gabarito":"E","explicacao":"A ordem é captura do áudio, transcrição automática, revisão, edição e validação. A máquina transcreve primeiro, e o humano revisa depois; não é o sistema que revisa o texto humano, nem há transcrição antes de haver áudio. A afirmativa trocou a transcrição automática por manual e inverteu os papéis.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. A ordem é o contrário: grava-se o áudio, a máquina transcreve e a pessoa revisa. Não faz sentido transcrever antes de gravar, e não é o sistema que corrige o humano.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"captura do áudio","significado":"gravação do som da sessão, com microfones e equipamentos de captação."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."}],"exemplo":"Na Comissão de Educação, o áudio da reunião é gravado e enviado ao sistema, que devolve o texto. Só então a revisora Kelly começa a ouvir e corrigir. Ela não digita nada antes de a máquina entregar a primeira versão."}},{"id":"aut.transcricao_ia.human_in_the_loop.0007","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo assistido por IA com humano no circuito, a revisão, etapa posterior à transcrição automática, consiste na conferência do texto com o áudio.","gabarito":"C","explicacao":"Depois da transcrição automática vem a revisão, que confere o texto com o áudio; seguem-se a edição e a validação. O sistema acelera o trabalho, mas a decisão e a responsabilidade pelo texto final permanecem com quem revisa e valida.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Assim que a máquina entrega o texto, uma pessoa escuta a gravação e compara palavra por palavra. Essa é a revisão, e ela vem antes da edição e da aprovação final.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"transcrição automática","significado":"texto produzido sozinho pelo computador a partir do áudio, sem tratamento humano."}],"exemplo":"O sistema entrega a transcrição da sessão às 15h. A partir daí, Leandro põe o fone e ouve cada trecho, conferindo se o texto bate com o áudio. Só depois Patrícia cuida da edição."}},{"id":"aut.transcricao_ia.human_in_the_loop.0008","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo assistido por IA com humano no circuito, a etapa seguinte à transcrição automática é a publicação, ficando a conferência com o áudio reservada a reclamações posteriores.","gabarito":"E","explicacao":"Depois da transcrição automática vem a revisão, com conferência do texto com o áudio; seguem-se a edição e a validação, e só então o texto é publicado. A afirmativa pulou a revisão e a validação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. O texto da máquina não vai direto para publicação. Antes, uma pessoa confere com o áudio, arruma o texto e outra aprova. Esperar reclamação para conferir seria abrir mão do controle humano.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"transcrição automática","significado":"texto produzido sozinho pelo computador a partir do áudio, sem tratamento humano."}],"exemplo":"Uma câmara municipal publicou direto o texto da máquina. Dias depois, o vereador Nilton reclamou de uma frase que nunca disse. Se houvesse revisão com o áudio antes da publicação, o erro teria sido corrigido a tempo."}},{"id":"aut.transcricao_ia.human_in_the_loop.0009","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"No fluxo assistido por IA com humano no circuito, a última etapa é a validação, momento em que a pessoa responsável aprova o texto e responde por ele.","gabarito":"C","explicacao":"A sequência termina na validação, a aprovação final por pessoa responsável, depois da captura, da transcrição automática, da revisão e da edição. O sistema acelera o trabalho, mas a decisão e a responsabilidade pelo texto final permanecem com quem revisa e valida.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. O último passo é uma pessoa dar o aval final. Quem aprova assume a responsabilidade pelo que foi publicado, não a máquina.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"validação","significado":"aprovação final do texto por uma pessoa responsável, antes de ele virar oficial."}],"exemplo":"Depois da revisão e da edição, o texto da sessão chega à supervisora Regina. Ela confere os pontos marcados, aprova e registra seu nome como responsável. Só então o discurso é publicado."}},{"id":"aut.transcricao_ia.human_in_the_loop.0010","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":3,"enunciado":"No fluxo assistido por IA com humano no circuito, a última etapa é a diarização, em que o sistema aprova automaticamente o texto já revisado e editado.","gabarito":"E","explicacao":"A última etapa é a validação: aprovação final por pessoa responsável. Diarização é a separação do áudio por falante, feita em geral junto com a transcrição automática, e não aprova nada. A afirmativa trocou a validação pela diarização e entregou a aprovação ao sistema.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. O passo final é a validação, e quem valida é uma pessoa. Diarização é só separar o áudio por quem falou, e acontece lá no começo, junto com a transcrição da máquina.","teSitua":{"termos":[{"termo":"IA","significado":"sigla de inteligência artificial, sistemas de computador que fazem tarefas que antes exigiam raciocínio humano."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."}],"exemplo":"O sistema da Casa separa as vozes da reunião logo que transcreve. Semanas depois, quando o texto já foi revisado e editado, quem dá a palavra final é o servidor Jonas, que valida e assina."}},{"id":"aut.transcricao_ia.human_in_the_loop.0011","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"O fluxo em que o sistema produz a saída e um profissional revisa, corrige e valida antes da publicação é chamado de humano no circuito, expressão traduzida do inglês human in the loop.","gabarito":"C","explicacao":"Human in the loop (humano no circuito) é o desenho em que a máquina gera a saída e um profissional revisa, corrige e valida antes da publicação. É o desenho recomendado para registro parlamentar, em que a fidelidade é requisito e não conveniência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Direitos Autorais e Ética)","mastigado":"Certo. A máquina faz a primeira versão e uma pessoa fica no meio do caminho, conferindo e aprovando antes de publicar. Esse arranjo tem o nome de humano no circuito.","teSitua":{"termos":[{"termo":"saída","significado":"resultado que o sistema entrega depois de processar o áudio, como o texto transcrito."},{"termo":"humano no circuito","significado":"modelo de trabalho em que a máquina produz e uma pessoa revisa, decide e responde pelo resultado."},{"termo":"human in the loop","significado":"expressão em inglês para humano no circuito, a pessoa que confere e aprova o trabalho da máquina."}],"exemplo":"Na Câmara, o sistema transcreve a sessão, mas nenhum texto vai ao ar sem passar por Rosana, que revisa, corrige e valida. Esse é o modelo humano no circuito, exigido porque o registro precisa ser fiel."}},{"id":"aut.transcricao_ia.human_in_the_loop.0012","subtopico":"transcricao_ia.degravacao_revisao.human_in_the_loop","tipo":"certo_errado","dificuldade":2,"enunciado":"O fluxo em que o sistema produz a saída e um profissional revisa, corrige e valida antes da publicação é chamado de humano fora do circuito, desenho desaconselhado para o registro parlamentar.","gabarito":"E","explicacao":"Esse fluxo é o humano no circuito (human in the loop), e é justamente o desenho recomendado para registro parlamentar, em que a fidelidade é requisito e não conveniência. A afirmativa trocou o nome e inverteu a recomendação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Direitos Autorais e Ética)","mastigado":"Errado. Quando uma pessoa revisa e aprova o que a máquina fez, ela está dentro do circuito, não fora. E esse é exatamente o modelo indicado para o Parlamento, onde o texto precisa ser fiel.","teSitua":{"termos":[{"termo":"saída","significado":"resultado que o sistema entrega depois de processar o áudio, como o texto transcrito."},{"termo":"registro parlamentar","significado":"texto oficial que documenta o que foi dito e decidido nas sessões do Parlamento."}],"exemplo":"Ao montar o novo fluxo, o gestor Ricardo pensou em publicar o texto da máquina direto. A consultora Lilian explicou que, no registro parlamentar, o modelo recomendado é o humano no circuito, com revisão e validação antes de publicar."}},{"id":"aut.transcricao_ia.ia_parlamentos.0002","subtopico":"transcricao_ia.ia_parlamento.ia_parlamentos","tipo":"certo_errado","dificuldade":2,"enunciado":"Entre as aplicações de inteligência artificial em parlamentos estão a transcrição automática de sessões, a sumarização de discursos, a indexação e busca em acervos e a classificação temática de proposições, atuando a IA como apoio.","gabarito":"C","explicacao":"As principais aplicações de IA em parlamentos são: transcrição automática de sessões; sumarização de discursos e sessões; indexação e busca em acervos; classificação temática de proposições; tradução e legendagem; apoio à acessibilidade; organização de dados legislativos. Em todas, a IA atua como apoio, e a responsabilidade pelo registro oficial permanece humana.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. A IA ajuda o Parlamento a transcrever sessões, resumir discursos, achar documentos antigos e separar projetos por assunto. Mas é sempre ajudante: quem responde pelo registro oficial são as pessoas.","teSitua":{"termos":[{"termo":"inteligência artificial","significado":"sistemas de computador capazes de fazer tarefas que antes exigiam raciocínio humano, como entender fala e textos."},{"termo":"sumarização","significado":"produção automática de um resumo a partir de um texto ou discurso longo."},{"termo":"indexação","significado":"organização dos documentos com etiquetas e índices, para que possam ser encontrados depois."},{"termo":"classificação temática","significado":"separação dos documentos por assunto, como saúde, educação ou tributos."},{"termo":"proposições","significado":"propostas apresentadas para votação no Parlamento, como projetos de lei e emendas."}],"exemplo":"Na Câmara, o sistema transcreve a sessão, sugere um resumo e etiqueta cada projeto apresentado por tema. A analista Rosângela confere tudo, porque o registro oficial continua sob responsabilidade da equipe."}},{"id":"aut.transcricao_ia.ia_parlamentos.0003","subtopico":"transcricao_ia.ia_parlamento.ia_parlamentos","tipo":"certo_errado","dificuldade":2,"enunciado":"Nas aplicações de inteligência artificial em parlamentos, como a transcrição e a sumarização de sessões, a responsabilidade pelo registro oficial passa ao sistema sempre que sua taxa de acerto supera a de revisores humanos.","gabarito":"E","explicacao":"Em todas as aplicações de IA em parlamentos (transcrição, sumarização, indexação, busca, classificação, tradução, acessibilidade), a IA atua como apoio, e a responsabilidade pelo registro oficial permanece humana. Não há transferência de responsabilidade em função do desempenho do sistema.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. Por melhor que seja a máquina, ela é só apoio. A responsabilidade pelo que fica registrado oficialmente continua com as pessoas, não importa a taxa de acerto do sistema.","teSitua":{"termos":[{"termo":"inteligência artificial","significado":"sistemas de computador capazes de fazer tarefas que antes exigiam raciocínio humano, como entender fala e textos."},{"termo":"sumarização","significado":"produção automática de um resumo a partir de um texto ou discurso longo."},{"termo":"registro oficial","significado":"documento formal que vale como prova do que foi dito e decidido nas sessões."},{"termo":"taxa de acerto","significado":"percentual de vezes em que o sistema acerta o resultado esperado."}],"exemplo":"Um fornecedor garantiu que seu sistema erra menos que os revisores. Mesmo assim, a diretora Márcia manteve a revisão e a validação humanas: se algo sair errado no registro, a responsabilidade é da Casa e de sua equipe."}},{"id":"aut.transcricao_ia.llms_audio.0002","subtopico":"transcricao_ia.reconhecimento_fala.llms_audio","tipo":"certo_errado","dificuldade":3,"enunciado":"Um LLM multimodal de áudio nativo recebe o áudio diretamente e o processa sem etapa prévia de transcrição, preservando informação paralinguística que o encadeamento de ASR seguido de LLM em grande parte descarta.","gabarito":"C","explicacao":"O LLM multimodal de áudio nativo recebe o áudio diretamente (como representações ou tokens de áudio), sem transcrever antes. No encadeamento em cascata, o ASR transcreve e só depois um LLM processa o texto, o que descarta em grande parte informação paralinguística (entonação, ênfase, emoção). Esses modelos podem parafrasear ou resumir em vez de transcrever literalmente, o que exige cautela em registro oficial.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Esse tipo de modelo \\"ouve\\" o áudio direto, sem passar antes para texto. Por isso percebe tom de voz, ênfase e emoção, coisas que se perdem quando o áudio vira texto antes de chegar ao modelo.","teSitua":{"termos":[{"termo":"LLM multimodal","significado":"grande modelo de linguagem capaz de lidar com mais de um tipo de entrada, como texto, imagem e áudio."},{"termo":"áudio nativo","significado":"áudio entregue diretamente ao modelo, sem ser convertido antes em texto."},{"termo":"informação paralinguística","significado":"o que a voz comunica além das palavras, como entonação, ênfase, ironia e emoção."},{"termo":"encadeamento","significado":"uso de sistemas em sequência, em que a saída de um vira a entrada do outro."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."}],"exemplo":"A deputada Sílvia diz \\"que belo projeto\\" em tom irônico. Num encadeamento ASR e LLM, o texto perde o tom e parece elogio. Um modelo de áudio nativo, que ouve a voz, percebe a ironia ao resumir a fala para o analista Hugo."}},{"id":"aut.transcricao_ia.llms_audio.0003","subtopico":"transcricao_ia.reconhecimento_fala.llms_audio","tipo":"certo_errado","dificuldade":3,"enunciado":"Por processarem o áudio diretamente, os LLMs multimodais de áudio nativo sempre transcrevem a fala de forma literal, o que dispensa cautela no seu uso para registro oficial.","gabarito":"E","explicacao":"Os LLMs multimodais de áudio nativo podem parafrasear ou resumir em vez de transcrever literalmente, o que exige cautela em registro oficial. Processar o áudio diretamente não garante literalidade. A afirmativa inverteu o risco.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Esses modelos às vezes reescrevem ou resumem o que ouviram, em vez de copiar palavra por palavra. Num registro oficial, isso é perigoso, então é preciso cuidado redobrado.","teSitua":{"termos":[{"termo":"LLMs multimodais","significado":"grandes modelos de linguagem capazes de lidar com mais de um tipo de entrada, como texto, imagem e áudio."},{"termo":"áudio nativo","significado":"áudio entregue diretamente ao modelo, sem ser convertido antes em texto."},{"termo":"literal","significado":"palavra por palavra, exatamente como foi dito."},{"termo":"registro oficial","significado":"documento formal que vale como prova do que foi dito e decidido nas sessões."}],"exemplo":"Ao testar um modelo de áudio nativo, a revisora Celeste notou que ele trocou \\"eu não concordo, em hipótese alguma\\" por \\"o deputado discorda\\". O sentido geral ficou, mas a fala literal se perdeu. Para o registro, ela manteve a revisão completa."}},{"id":"aut.transcricao_ia.modelos_portugues.0001","subtopico":"transcricao_ia.ia_parlamento.modelos_portugues","tipo":"certo_errado","dificuldade":2,"enunciado":"Modelos de linguagem treinados em muitos idiomas são ditos multilíngues, e a escolha entre eles e modelos especializados em português pondera abrangência e especialização.","gabarito":"C","explicacao":"Modelos treinados em muitos idiomas são multilíngues; os treinados ou ajustados predominantemente em português tendem a ter melhor desempenho em vocabulário e construções próprias do português brasileiro. A escolha pondera abrangência e especialização.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. O modelo multilíngue sabe um pouco de muitas línguas; o especializado sabe muito de uma só. Escolher entre eles é decidir se importa mais a variedade ou a profundidade no português.","teSitua":{"termos":[{"termo":"modelos de linguagem","significado":"sistemas de inteligência artificial treinados com muitos textos para entender e produzir linguagem."},{"termo":"multilíngues","significado":"que funcionam em vários idiomas ao mesmo tempo."},{"termo":"abrangência","significado":"capacidade de cobrir muitas situações ou muitos idiomas."}],"exemplo":"Para traduzir resoluções do Mercosul, a equipe de Tomás prefere um modelo multilíngue. Para revisar discursos cheios de regionalismos, usa um modelo ajustado em português brasileiro, que conhece melhor as expressões locais."}},{"id":"aut.transcricao_ia.modelos_portugues.0002","subtopico":"transcricao_ia.ia_parlamento.modelos_portugues","tipo":"certo_errado","dificuldade":3,"enunciado":"Modelos treinados em muitos idiomas, ditos monolíngues, superam necessariamente os modelos ajustados em português no tratamento de vocabulário e construções próprias do português brasileiro.","gabarito":"E","explicacao":"Modelos treinados em muitos idiomas são ditos multilíngues, não monolíngues. E são os treinados ou ajustados predominantemente em português que tendem a ter melhor desempenho em vocabulário e construções do português brasileiro. A afirmativa errou o nome e inverteu a vantagem.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. Modelo de muitas línguas é multilíngue, não monolíngue. E, para as expressões típicas do português do Brasil, quem costuma se sair melhor é o modelo ajustado em português.","teSitua":{"termos":[{"termo":"monolíngues","significado":"que funcionam em um único idioma."},{"termo":"ajustados","significado":"treinados de novo, com material específico, para melhorar numa tarefa ou língua."},{"termo":"construções","significado":"formas de montar frases típicas de uma língua ou região."}],"exemplo":"Num teste com discursos do Nordeste, o modelo de Helena, ajustado em português, entendeu \\"arretado\\" e \\"oxente\\". O modelo multilíngue do colega errou as duas palavras."}},{"id":"aut.transcricao_ia.modelos_portugues.0003","subtopico":"transcricao_ia.ia_parlamento.modelos_portugues","tipo":"certo_errado","dificuldade":2,"enunciado":"Modelos treinados ou ajustados predominantemente em português tendem a ter melhor desempenho em vocabulário e construções próprias do português brasileiro do que modelos multilíngues.","gabarito":"C","explicacao":"Os modelos treinados ou ajustados predominantemente em português tendem a ter melhor desempenho em vocabulário e construções próprias do português brasileiro; os multilíngues ganham em abrangência. A escolha pondera abrangência e especialização.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Certo. Quem estudou muito português conhece melhor as palavras e o jeito de falar do Brasil. O modelo de muitas línguas é mais versátil, mas costuma ser menos afiado aqui.","teSitua":{"termos":[{"termo":"ajustados","significado":"treinados de novo, com material específico, para melhorar numa tarefa ou língua."},{"termo":"construções","significado":"formas de montar frases típicas de uma língua ou região."},{"termo":"multilíngues","significado":"que funcionam em vários idiomas ao mesmo tempo."}],"exemplo":"A Câmara testou dois modelos com notas taquigráficas. O ajustado em português acertou expressões como \\"pela ordem\\" e \\"verificação de votação\\" com mais frequência que o multilíngue, e a equipe de Saulo o escolheu."}},{"id":"aut.transcricao_ia.modelos_portugues.0004","subtopico":"transcricao_ia.ia_parlamento.modelos_portugues","tipo":"certo_errado","dificuldade":2,"enunciado":"Modelos treinados ou ajustados predominantemente em português tendem a ter melhor desempenho em vocabulário e construções próprias do inglês técnico, por terem sido expostos a menos idiomas.","gabarito":"E","explicacao":"A vantagem dos modelos treinados ou ajustados predominantemente em português aparece no vocabulário e nas construções próprias do português brasileiro, e não do inglês técnico. A afirmativa trocou a língua em que ocorre a especialização.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (IA no Contexto Parlamentar)","mastigado":"Errado. Quem foi treinado em português fica bom em português do Brasil, não em inglês técnico. A especialização vale para a língua que o modelo mais estudou.","teSitua":{"termos":[{"termo":"ajustados","significado":"treinados de novo, com material específico, para melhorar numa tarefa ou língua."},{"termo":"construções","significado":"formas de montar frases típicas de uma língua ou região."},{"termo":"inglês técnico","significado":"vocabulário em inglês próprio de áreas especializadas, como informática ou medicina."}],"exemplo":"Kátia achou que o modelo em português seria o melhor para os documentos técnicos em inglês de um acordo internacional. O teste mostrou o contrário: a vantagem dele estava nos discursos em português brasileiro."}},{"id":"aut.transcricao_ia.normalizacao.0002","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A normalização de texto na revisão de transcrições é a padronização, conforme o manual do órgão, da grafia de números, siglas, abreviações, datas, valores e termos técnicos que a fala deixa em aberto.","gabarito":"C","explicacao":"Normalização é a padronização da grafia de elementos que a fala deixa em aberto, conforme o manual do órgão: números (por extenso ou em algarismos), siglas e abreviações, datas, valores e termos técnicos. Os sistemas fazem uma normalização inversa automática (ITN), mas a conferência final segue o padrão do órgão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Quem fala \\"dois mil e vinte e seis\\" não diz se é para escrever por extenso ou em número. A normalização decide isso, seguindo o manual do órgão, para números, siglas, datas e valores.","teSitua":{"termos":[{"termo":"normalização de texto","significado":"padronização da forma de escrever números, siglas e datas, para o texto ficar uniforme."},{"termo":"abreviações","significado":"formas encurtadas de palavras, como \\"art.\\" para artigo ou \\"Dep.\\" para deputado."},{"termo":"termos técnicos","significado":"palavras próprias de uma área específica, como o vocabulário do processo legislativo."}],"exemplo":"O deputado Márcio diz \\"trinta por cento do orçamento de dois mil e vinte e seis\\". A revisora Carla consulta o manual da Casa e escreve \\"30% do orçamento de 2026\\", padronizando como todos os textos oficiais."}},{"id":"aut.transcricao_ia.normalizacao.0003","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Como os sistemas de ASR já realizam a normalização inversa de texto de forma automática, a padronização de números, siglas e datas dispensa a conferência final segundo o manual do órgão.","gabarito":"E","explicacao":"Os sistemas fazem uma normalização inversa de texto (ITN) automática, mas a conferência final segue o padrão do órgão: o manual define se números vão por extenso ou em algarismos, como se grafam siglas, datas e valores. A afirmativa errou ao dispensar essa conferência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. A máquina já converte números e datas sozinha, mas pode não seguir as regras do órgão. Por isso alguém ainda confere tudo com o manual antes de o texto sair.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"normalização inversa de texto","significado":"conversão automática do que foi falado, como \\"vinte por cento\\", para a forma escrita, como \\"20%\\"."},{"termo":"manual do órgão","significado":"guia interno com as regras de escrita que todos os textos da instituição devem seguir."}],"exemplo":"O sistema escreveu \\"1º de março de 2026\\" como \\"1/3/26\\". O revisor Fábio sabe que o manual da Casa manda escrever a data por extenso e corrige, mesmo com a conversão automática já feita."}},{"id":"aut.transcricao_ia.normalizacao.0004","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Em ASR, a conversão da forma falada para a forma escrita padronizada, como de \\"vinte por cento\\" para \\"20%\\", é feita pela normalização inversa de texto.","gabarito":"C","explicacao":"A normalização inversa de texto (ITN, de inverse text normalization) converte a forma falada (\\"vinte por cento\\", \\"dois mil e vinte e seis\\") na forma escrita padronizada (\\"20%\\", \\"2026\\"). A normalização feita pelo revisor depois padroniza números, siglas, datas e valores conforme o manual do órgão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. O sistema ouve palavras e precisa decidir como escrever números e símbolos. Esse passo que transforma \\"vinte por cento\\" em \\"20%\\" tem esse nome: normalização inversa de texto.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"forma falada","significado":"jeito como algo é dito em voz alta, com números e símbolos por extenso."},{"termo":"normalização inversa de texto","significado":"conversão automática do que foi falado para a forma escrita padrão, com algarismos e símbolos."}],"exemplo":"O ministro diz na audiência: \\"a inflação ficou em quatro vírgula cinco por cento\\". Graças à normalização inversa, o sistema já entrega \\"4,5%\\", e a revisora Joana só confere se o formato segue o manual."}},{"id":"aut.transcricao_ia.normalizacao.0005","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Em ASR, a conversão da forma falada para a forma escrita padronizada, como de \\"vinte por cento\\" para \\"20%\\", é chamada de diarização.","gabarito":"E","explicacao":"Essa conversão é a normalização inversa de texto (ITN). Diarização é outra tarefa: dividir o áudio em segmentos e atribuí-los a cada falante, respondendo \\"quem falou quando\\". A afirmativa trocou o nome do processo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Transformar \\"vinte por cento\\" em \\"20%\\" é a normalização inversa de texto. Diarização é outra coisa: separar o áudio por pessoa, dizendo quem falou em cada momento.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"forma falada","significado":"jeito como algo é dito em voz alta, com números e símbolos por extenso."},{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."}],"exemplo":"Na mesma transcrição, o sistema faz duas coisas: marca que o trecho de 10 a 40 segundos é do Falante 2, que é a diarização, e escreve \\"20%\\" no lugar de \\"vinte por cento\\", que é a normalização inversa. Lucas, o revisor, confere as duas."}},{"id":"aut.transcricao_ia.normalizacao.0006","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A sigla ITN, usada em reconhecimento de fala, designa a normalização inversa de texto, que converte a forma falada de números e valores na forma escrita padronizada.","gabarito":"C","explicacao":"ITN é a sigla de inverse text normalization, a normalização inversa de texto, que converte a forma falada (\\"vinte por cento\\") na forma escrita padronizada (\\"20%\\"). A normalização do revisor, depois, segue o manual do órgão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. ITN vem do inglês e quer dizer normalização inversa de texto. É o passo em que a máquina transforma números ditos em voz alta em algarismos e símbolos.","teSitua":{"termos":[{"termo":"ITN","significado":"sigla em inglês de normalização inversa de texto, a conversão do que foi falado para a forma escrita padrão."},{"termo":"reconhecimento de fala","significado":"tecnologia que transforma a voz gravada ou ao vivo em texto escrito."},{"termo":"normalização inversa de texto","significado":"conversão automática do que foi falado para a forma escrita padrão, com algarismos e símbolos."}],"exemplo":"No painel do serviço de transcrição, Mariana encontra a opção \\"ITN ativada\\". Com ela ligada, \\"cinco milhões de reais\\" aparece como \\"R$ 5 milhões\\"; desligada, o texto vem todo por extenso."}},{"id":"aut.transcricao_ia.normalizacao.0007","subtopico":"transcricao_ia.degravacao_revisao.normalizacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A sigla ITN, usada em reconhecimento de fala, designa a identificação de termos novos, etapa em que o sistema aprende palavras ausentes de seu vocabulário durante a transcrição.","gabarito":"E","explicacao":"ITN é a sigla de inverse text normalization, a normalização inversa de texto, que converte a forma falada (\\"vinte por cento\\") na forma escrita padronizada (\\"20%\\"). A afirmativa inventou outro significado para a sigla.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. ITN não tem a ver com aprender palavras novas. É a normalização inversa de texto, o passo que transforma números e valores falados em algarismos e símbolos.","teSitua":{"termos":[{"termo":"ITN","significado":"sigla em inglês de normalização inversa de texto, a conversão do que foi falado para a forma escrita padrão."},{"termo":"reconhecimento de fala","significado":"tecnologia que transforma a voz gravada ou ao vivo em texto escrito."},{"termo":"vocabulário","significado":"conjunto de palavras que o sistema conhece e consegue reconhecer."}],"exemplo":"Num treinamento, Rafael pergunta se ITN serve para o sistema aprender siglas novas. A instrutora Beatriz explica que não: ITN é a conversão de \\"mil e quinhentos\\" em \\"1.500\\". Para siglas novas, usa-se o vocabulário personalizado."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0003","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A pontuação e a capitalização automáticas costumam ser tratadas como pós-processamento porque a fala não contém pontuação, e pausas e entonação não correspondem de forma exata a vírgulas e pontos.","gabarito":"C","explicacao":"A pontuação é convenção da escrita, e pausas e entonação não correspondem exatamente a vírgulas e pontos. Muitos modelos de ASR produzem texto sem pontuação e em minúsculas; uma etapa posterior ou um modelo de restauração insere sinais e maiúsculas. Alguns modelos modernos já emitem texto pontuado, e as APIs oferecem a pontuação como recurso opcional. O resultado ainda exige revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Ninguém fala vírgula nem ponto. Uma pausa nem sempre é uma vírgula. Por isso, vírgulas e letras maiúsculas costumam ser colocadas depois, numa etapa própria.","teSitua":{"termos":[{"termo":"capitalização","significado":"uso de letras maiúsculas onde a escrita exige, como no início de frases e em nomes próprios."},{"termo":"pós-processamento","significado":"etapa que trata o resultado depois que o sistema principal terminou seu trabalho."},{"termo":"entonação","significado":"subida e descida do tom da voz ao falar, que indica pergunta, ênfase ou fim de frase."}],"exemplo":"O sistema entrega \\"o deputado paulo disse que votará contra\\" tudo em minúsculas e sem pontos. Uma segunda etapa coloca a maiúscula em \\"Paulo\\" e o ponto final. A revisora Neusa confere, porque essa etapa ainda erra."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0004","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Como as pausas e a entonação da fala correspondem de forma exata a vírgulas e pontos, a pontuação automática inserida pelo ASR dispensa revisão humana.","gabarito":"E","explicacao":"Pausas e entonação não correspondem de forma exata a vírgulas e pontos: a pontuação é convenção da escrita. Por isso ela costuma ser tratada como pós-processamento, e o resultado ainda pode ter erros e exige revisão. A afirmativa errou na premissa e na conclusão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. A gente para para respirar no meio da frase e às vezes emenda duas frases sem pausa. Por isso a pontuação da máquina erra e precisa de revisão.","teSitua":{"termos":[{"termo":"entonação","significado":"subida e descida do tom da voz ao falar, que indica pergunta, ênfase ou fim de frase."},{"termo":"pontuação automática","significado":"recurso do sistema que coloca vírgulas, pontos e outros sinais no texto sem ajuda humana."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."}],"exemplo":"O deputado Osmar fez uma pausa longa para tomar água no meio de uma frase. O sistema colocou um ponto final ali, partindo a ideia em duas. O revisor Yuri juntou de novo as partes."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0005","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Como a fala não contém sinais gráficos, a pontuação automática resulta de pós-processamento ou de modelos específicos de restauração, e algumas APIs de ASR a oferecem como recurso opcional.","gabarito":"C","explicacao":"A pontuação e a capitalização automáticas resultam de pós-processamento ou de modelos de restauração. Algumas APIs oferecem a pontuação automática como recurso opcional; o Google Cloud Speech-to-Text a lista entre os recursos adicionais de reconhecimento. O resultado continua exigindo revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Google Cloud Speech-to-Text, documentação (pontuação automática)","mastigado":"Certo. Os sinais de pontuação são colocados por uma etapa à parte ou por um modelo especial. Em alguns serviços, basta ligar a opção de pontuação automática.","teSitua":{"termos":[{"termo":"sinais gráficos","significado":"símbolos da escrita, como vírgula, ponto e interrogação, que não existem na fala."},{"termo":"pós-processamento","significado":"etapa que trata o resultado depois que o sistema principal terminou seu trabalho."},{"termo":"modelos específicos de restauração","significado":"sistemas treinados só para recolocar pontuação e maiúsculas em textos que vieram sem elas."},{"termo":"APIs","significado":"portas de acesso que um programa oferece para outros sistemas usarem seus serviços pela internet."}],"exemplo":"Ao configurar o serviço do Google, o técnico Lourenço marca a opção de pontuação automática. O texto da sessão passa a vir com vírgulas e pontos, mas a equipe de revisão continua conferindo."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0006","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"Como a fala não contém sinais gráficos, nenhuma API de ASR oferece pontuação automática, que precisa ser inteiramente inserida pelo revisor humano.","gabarito":"E","explicacao":"Algumas APIs de ASR oferecem a pontuação automática como recurso opcional; o Google Cloud Speech-to-Text a lista entre os recursos adicionais de reconhecimento. A pontuação resulta de pós-processamento ou de modelos de restauração, e o revisor confere o resultado. A afirmativa negou a existência do recurso.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Google Cloud Speech-to-Text, documentação (pontuação automática)","mastigado":"Errado. Vários serviços já colocam vírgulas e pontos sozinhos, como opção. O revisor não precisa pontuar tudo do zero: ele confere e corrige o que a máquina fez.","teSitua":{"termos":[{"termo":"sinais gráficos","significado":"símbolos da escrita, como vírgula, ponto e interrogação, que não existem na fala."},{"termo":"API","significado":"porta de acesso que um programa oferece para outros sistemas usarem seus serviços pela internet."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"pontuação automática","significado":"recurso do sistema que coloca vírgulas, pontos e outros sinais no texto sem ajuda humana."}],"exemplo":"Antes, a revisora Lurdes pontuava cada página à mão. Com a opção de pontuação automática ligada no serviço contratado, ela só ajusta as vírgulas fora do lugar."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0007","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A capitalização automática, que insere as letras maiúsculas no texto produzido pelo ASR, resulta de pós-processamento ou de modelo específico de restauração, e o resultado continua exigindo revisão.","gabarito":"C","explicacao":"Como a fala não contém sinais gráficos, a pontuação e a capitalização automáticas resultam de pós-processamento ou de modelos específicos de restauração. O resultado continua exigindo revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. As maiúsculas também são postas depois, por uma etapa à parte ou por um modelo especial. E, como essa etapa erra, alguém ainda precisa conferir.","teSitua":{"termos":[{"termo":"capitalização automática","significado":"recurso que coloca letras maiúsculas no texto sozinho, como em nomes próprios e início de frases."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"pós-processamento","significado":"etapa que trata o resultado depois que o sistema principal terminou seu trabalho."},{"termo":"modelo específico de restauração","significado":"sistema treinado só para recolocar pontuação e maiúsculas em textos que vieram sem elas."}],"exemplo":"O modelo de restauração escreveu \\"comissão de constituição e justiça\\" todo em minúsculas e \\"Votação\\" com maiúscula no meio da frase. A revisora Débora corrigiu as duas coisas."}},{"id":"aut.transcricao_ia.pontuacao_capitalizacao.0008","subtopico":"transcricao_ia.reconhecimento_fala.pontuacao_capitalizacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A capitalização automática é obtida diretamente do sinal acústico, pois a fala marca as letras maiúsculas pela entonação, o que dispensa pós-processamento.","gabarito":"E","explicacao":"A fala não contém sinais gráficos, e maiúscula é convenção da escrita, sem marca acústica. A capitalização automática resulta de pós-processamento ou de modelos de restauração, e o resultado exige revisão. A afirmativa inventou uma correspondência entre entonação e maiúsculas.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Ninguém fala uma letra maiúscula: isso só existe na escrita. Por isso as maiúsculas são colocadas depois, por uma etapa própria, que também precisa de revisão.","teSitua":{"termos":[{"termo":"capitalização automática","significado":"recurso que coloca letras maiúsculas no texto sozinho, como em nomes próprios e início de frases."},{"termo":"sinal acústico","significado":"o som em si, como onda gravada pelo microfone."},{"termo":"entonação","significado":"subida e descida do tom da voz ao falar, que indica pergunta, ênfase ou fim de frase."},{"termo":"pós-processamento","significado":"etapa que trata o resultado depois que o sistema principal terminou seu trabalho."}],"exemplo":"O deputado diz \\"o senado\\" com o mesmo tom de \\"o cenário\\". Nada no som indica a maiúscula. É a etapa de restauração que escreve \\"Senado\\", e a revisora Ester confere."}},{"id":"aut.transcricao_ia.revisao_qualidade.0010","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Na revisão de uma transcrição, o respeito ao registro do orador impõe preservar seu estilo e seu tom, sem uniformizar a linguagem, ainda que se corrijam deslizes gramaticais.","gabarito":"C","explicacao":"Os critérios de revisão incluem: fidelidade ao conteúdo (não alterar o sentido, não acrescentar nem suprimir ideias); correção gramatical que ajuste deslizes sem descaracterizar a fala; respeito ao registro do orador, preservando estilo e tom, sem uniformizar a linguagem; e tratamento de vícios, repetições e truncamentos, eliminando ruído da oralidade e mantendo o que tem efeito retórico.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. O revisor conserta pequenos erros de gramática, mas não reescreve o deputado com a própria voz. Quem fala de modo simples continua soando simples; quem é formal continua formal.","teSitua":{"termos":[{"termo":"registro do orador","significado":"jeito próprio de falar de quem discursa, mais formal ou mais coloquial."},{"termo":"uniformizar","significado":"deixar tudo igual, apagando as diferenças de estilo entre as pessoas."},{"termo":"deslizes gramaticais","significado":"pequenos erros de concordância ou construção, comuns na fala espontânea."}],"exemplo":"O deputado Zeca fala de modo simples, com expressões do interior. A revisora Mônica corrige um \\"nós vai\\" para \\"nós vamos\\", mas mantém o \\"pois é, minha gente\\", porque é o jeito dele falar."}},{"id":"aut.transcricao_ia.revisao_qualidade.0011","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Na revisão de uma transcrição, todas as repetições da fala devem ser eliminadas como ruído da oralidade, inclusive aquelas usadas pelo orador com efeito retórico ou de sentido.","gabarito":"E","explicacao":"O tratamento de vícios de linguagem, repetições e truncamentos elimina o que é ruído da oralidade (hesitações, repetições sem função), mas mantém o que tem efeito retórico ou de sentido. Eliminar todas as repetições contraria esse critério.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Só sai a repetição que é tropeço da fala. Quando o orador repete de propósito, para dar força à ideia, a repetição fica, porque faz parte do que ele quis dizer.","teSitua":{"termos":[{"termo":"ruído da oralidade","significado":"marcas da fala sem função, como hesitações, \\"é...\\" e repetições por engano."},{"termo":"efeito retórico","significado":"impacto buscado de propósito pelo orador para convencer ou emocionar a plateia."}],"exemplo":"A deputada Neusa diz: \\"Nunca, nunca, nunca votarei contra a saúde!\\". O revisor Caio mantém as três palavras, porque a repetição é proposital. Já o \\"o... o... o projeto\\" de outro orador vira só \\"o projeto\\"."}},{"id":"aut.transcricao_ia.revisao_qualidade.0012","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"A taxa de erro de palavra (WER) mede a diferença entre a transcrição de referência e a hipótese do sistema, e quanto menor o seu valor, melhor o desempenho do reconhecedor.","gabarito":"C","explicacao":"O WER (Word Error Rate) compara a transcrição de referência, feita ou corrigida por pessoa, com a hipótese do sistema: WER = (S + D + I) / N, com S substituições, D supressões, I inserções e N palavras da referência. O alinhamento usa a distância de edição (Levenshtein). Quanto menor o WER, melhor.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Compara-se o texto da máquina com um texto feito por gente, tido como correto, e contam-se os erros. Quanto menos erros, menor a taxa e melhor o sistema.","teSitua":{"termos":[{"termo":"taxa de erro de palavra","significado":"medida de quantas palavras o sistema errou em comparação com um texto correto."},{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"transcrição de referência","significado":"texto feito ou corrigido por uma pessoa, usado como gabarito para medir o erro da máquina."},{"termo":"hipótese","significado":"texto que o sistema produziu, aquilo que ele acha que foi dito."}],"exemplo":"Para comparar dois fornecedores, a equipe de Gabriel transcreve à mão uma hora de sessão. O sistema A tem WER de 9% e o B, de 14%. Como o menor é melhor, a Casa escolhe o sistema A."}},{"id":"aut.transcricao_ia.revisao_qualidade.0013","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"A taxa de erro de palavra (WER) é calculada dividindo-se o número de palavras corretamente reconhecidas pelo número de palavras da hipótese do sistema, de modo que quanto maior o valor, melhor o reconhecedor.","gabarito":"E","explicacao":"O WER conta erros, não acertos: WER = (S + D + I) / N, em que S são substituições, D supressões, I inserções e N o número de palavras da referência (não da hipótese). Quanto menor o WER, melhor. A afirmativa descreveu uma taxa de acerto e trocou o denominador.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. A conta soma os erros (palavras trocadas, faltando e sobrando) e divide pelo tamanho do texto correto, não do texto da máquina. Por ser taxa de erro, quanto menor, melhor.","teSitua":{"termos":[{"termo":"taxa de erro de palavra","significado":"medida de quantas palavras o sistema errou em comparação com um texto correto."},{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"hipótese","significado":"texto que o sistema produziu, aquilo que ele acha que foi dito."}],"exemplo":"Num texto de referência de 100 palavras, o sistema trocou 5, omitiu 2 e acrescentou 1. Fernanda soma os 8 erros e divide por 100: o WER é 8%. Se fossem 3 erros, seria 3%, um resultado melhor."}},{"id":"aut.transcricao_ia.revisao_qualidade.0014","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Uma das limitações do WER é tratar todos os erros com o mesmo peso, sem medir a gravidade para o sentido: trocar \\"aprovo\\" por \\"reprovo\\" pesa o mesmo que trocar um artigo.","gabarito":"C","explicacao":"Entre as limitações do WER estão: pode ultrapassar 100%, porque as inserções não têm limite e N é fixo; trata todos os erros com o mesmo peso, sem medir a gravidade para o sentido; depende da normalização aplicada à referência e à hipótese; e, em geral, não captura a qualidade da pontuação, da diarização e da formatação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Para a conta, erro é erro. Trocar \\"o\\" por \\"a\\" vale o mesmo que trocar \\"aprovo\\" por \\"reprovo\\", embora o segundo inverta o voto do deputado. Por isso a taxa sozinha não diz tudo.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"gravidade para o sentido","significado":"quanto um erro muda o significado do que foi dito."}],"exemplo":"Dois textos têm o mesmo WER de 2%. No de Marcelo, os erros são artigos trocados. No de Renata, o sistema escreveu \\"reprovo\\" onde o deputado disse \\"aprovo\\". A taxa é igual, mas o estrago do segundo é muito maior."}},{"id":"aut.transcricao_ia.revisao_qualidade.0015","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":4,"enunciado":"Por ser uma proporção calculada sobre o número de palavras da referência, o WER está necessariamente limitado a 100%.","gabarito":"E","explicacao":"O WER pode ultrapassar 100%, porque as inserções (palavras a mais na hipótese) não têm limite, enquanto N, o número de palavras da referência, é fixo. A afirmativa ignorou o efeito das inserções.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Se a máquina inventa muitas palavras a mais, os erros podem passar do tamanho do texto correto. Aí a taxa fica acima de 100%, mesmo sendo uma divisão.","teSitua":{"termos":[{"termo":"proporção","significado":"relação entre duas quantidades, obtida dividindo uma pela outra."},{"termo":"referência","significado":"texto correto, feito por uma pessoa, usado como gabarito para medir o erro da máquina."},{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."}],"exemplo":"O orador disse só \\"sim\\", uma palavra. Por causa de um ruído, o sistema escreveu \\"não sei se sim ou não\\". Há uma substituição e cinco inserções: seis erros sobre uma palavra de referência. O WER calculado por Tânia deu 600%."}},{"id":"aut.transcricao_ia.revisao_qualidade.0016","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"A taxa de erro de caractere (CER) é especialmente útil para medir erros pequenos, como a grafia de nomes próprios, siglas e números, e para línguas sem separação clara entre palavras.","gabarito":"C","explicacao":"O CER segue a lógica do WER no nível dos caracteres: CER = (S + D + I) / N, com N igual ao número de caracteres da referência. É útil para línguas sem separação clara entre palavras e para erros pequenos de grafia: uma só letra errada conta como palavra inteira errada no WER, mas pesa pouco no CER.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Contar letra por letra mostra melhor os erros miúdos, como um nome com uma letra trocada. Também ajuda em línguas que não separam as palavras com espaço.","teSitua":{"termos":[{"termo":"taxa de erro de caractere","significado":"medida de quantas letras e sinais o sistema errou em comparação com um texto correto."},{"termo":"CER","significado":"sigla em inglês de taxa de erro de caractere, que conta erros letra por letra."},{"termo":"nomes próprios","significado":"nomes de pessoas, lugares e instituições, que se escrevem com letra maiúscula."}],"exemplo":"O sistema escreveu \\"Deputado Tadeo\\" em vez de \\"Deputado Tadeu\\". No WER, isso conta como uma palavra inteira errada. No CER, é só uma letra entre muitas. A analista Sueli usa o CER para acompanhar a grafia dos nomes."}},{"id":"aut.transcricao_ia.revisao_qualidade.0017","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"No WER, uma única letra errada em uma palavra pesa menos que no CER, razão pela qual o WER é preferível para avaliar a grafia de nomes próprios e siglas.","gabarito":"E","explicacao":"É o contrário: no WER, uma só letra errada faz a palavra inteira contar como erro; no CER, o peso é proporcional ao tamanho do erro. Por isso o CER é o mais útil para medir erros pequenos de grafia em nomes próprios, siglas e números.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. A frase inverteu tudo. No WER, uma letra trocada já faz a palavra inteira valer como erro. Quem mede o erro miúdo com precisão é o CER, que conta letra por letra.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"CER","significado":"sigla em inglês de taxa de erro de caractere, que conta erros letra por letra."},{"termo":"siglas","significado":"palavras formadas pelas iniciais de um nome, como CCJC ou TCU."}],"exemplo":"O sistema grafou \\"CCJ\\" em vez de \\"CCJC\\". Para o WER, a sigla inteira está errada. Para o CER, falta só uma letra. O analista Davi usa o CER quando quer ver o quanto a máquina chega perto da grafia certa."}},{"id":"aut.transcricao_ia.revisao_qualidade.0018","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"A auditoria por amostragem avalia uma amostra dos textos entregues, com critérios definidos, para estimar a qualidade do conjunto sem conferir todos os textos.","gabarito":"C","explicacao":"Mecanismos de controle de qualidade: revisão em dupla (segundo revisor confere o texto já revisado, princípio dos quatro olhos); auditoria por amostragem (avalia-se uma amostra com critérios definidos para estimar a qualidade do conjunto sem conferir tudo); acordo de nível de serviço, SLA (metas mensuráveis de prazo e qualidade).","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Em vez de reler tudo, sorteia-se uma parte dos textos e confere-se com regras claras. O resultado dessa parte dá uma boa ideia da qualidade do todo.","teSitua":{"termos":[{"termo":"auditoria por amostragem","significado":"verificação de qualidade feita em uma parte escolhida dos textos, para estimar como está o conjunto."},{"termo":"amostra","significado":"pequena parte de um conjunto maior, escolhida para representá-lo."}],"exemplo":"No mês, a equipe entregou 400 transcrições. A auditora Lúcia sorteia 40 e confere cada uma com uma ficha de critérios. Achando poucos erros na amostra, ela conclui que a qualidade geral está dentro do esperado."}},{"id":"aut.transcricao_ia.revisao_qualidade.0019","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"O princípio dos quatro olhos, no controle de qualidade de transcrições, corresponde à auditoria por amostragem, em que quatro revisores avaliam uma amostra dos textos entregues.","gabarito":"E","explicacao":"O princípio dos quatro olhos corresponde à revisão em dupla: um segundo revisor confere o texto já revisado (dois pares de olhos). A auditoria por amostragem é outro mecanismo, que avalia parte dos textos para estimar a qualidade do conjunto. A afirmativa confundiu os mecanismos.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Quatro olhos são duas pessoas: o revisor e um segundo revisor que confere o trabalho dele. Isso é a revisão em dupla, não a auditoria por amostra.","teSitua":{"termos":[{"termo":"princípio dos quatro olhos","significado":"regra de que um trabalho importante deve ser conferido por uma segunda pessoa."},{"termo":"auditoria por amostragem","significado":"verificação de qualidade feita em uma parte escolhida dos textos, para estimar como está o conjunto."},{"termo":"revisores","significado":"profissionais que conferem o texto com o áudio e corrigem erros."}],"exemplo":"Toda transcrição revisada por Valter segue para Inês, que a confere de novo antes da entrega. Esse é o princípio dos quatro olhos. Já a auditoria mensal, feita por outra equipe, sorteia alguns textos."}},{"id":"aut.transcricao_ia.revisao_qualidade.0020","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"No cálculo do WER, somam-se substituições, supressões e inserções, e o total é dividido pelo número de palavras da referência.","gabarito":"C","explicacao":"WER = (S + D + I) / N: S substituições, D supressões (palavras omitidas), I inserções (palavras a mais) e N número de palavras da referência. Como as inserções não têm limite e N é fixo, o WER pode ultrapassar 100%.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Contam-se três tipos de erro: palavra trocada, palavra que faltou e palavra que sobrou. Soma-se tudo e divide-se pelo número de palavras do texto correto.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"substituições","significado":"palavras que o sistema trocou por outras."},{"termo":"supressões","significado":"palavras ditas que o sistema deixou de escrever."},{"termo":"inserções","significado":"palavras que o sistema escreveu sem que tivessem sido ditas."},{"termo":"referência","significado":"texto correto, feito por uma pessoa, usado como gabarito para medir o erro da máquina."}],"exemplo":"A frase correta tinha 20 palavras. O sistema trocou 2, pulou 1 e inventou 1. Sérgio soma 2 + 1 + 1 = 4 e divide por 20: o WER é 20%."}},{"id":"aut.transcricao_ia.revisao_qualidade.0021","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"No cálculo do WER, somam-se apenas substituições e inserções, pois as palavras omitidas pelo sistema não são computadas como erro.","gabarito":"E","explicacao":"As supressões (palavras omitidas) também entram na conta: WER = (S + D + I) / N, com S substituições, D supressões e I inserções, divididas pelo número de palavras da referência. A afirmativa excluiu as supressões.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Palavra que o orador disse e a máquina pulou é erro, sim. A conta soma três coisas: palavras trocadas, palavras que faltaram e palavras que sobraram.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"substituições","significado":"palavras que o sistema trocou por outras."},{"termo":"inserções","significado":"palavras que o sistema escreveu sem que tivessem sido ditas."}],"exemplo":"O deputado disse \\"não aprovo o texto\\", e o sistema escreveu \\"aprovo o texto\\". Só faltou uma palavra, mas o sentido virou ao contrário. Karina conta essa supressão como erro no WER."}},{"id":"aut.transcricao_ia.revisao_qualidade.0022","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"No cálculo do WER, as inserções correspondem às palavras que o sistema escreveu sem que tivessem sido ditas e, por não terem limite, podem levar a taxa a ultrapassar 100%.","gabarito":"C","explicacao":"Inserções (I) são palavras a mais na hipótese. Como WER = (S + D + I) / N e N, o número de palavras da referência, é fixo, as inserções sem limite podem levar o WER acima de 100%.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Inserção é palavra que a máquina inventou. Como ela pode inventar quantas quiser e o texto correto tem tamanho fixo, os erros podem passar de 100%.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"inserções","significado":"palavras que o sistema escreveu sem que tivessem sido ditas."}],"exemplo":"Num trecho de silêncio com chiado, o sistema escreveu doze palavras soltas, embora ninguém tenha falado nada além de \\"obrigado\\". O analista Rui viu o WER do trecho passar de 1.000% por causa das inserções."}},{"id":"aut.transcricao_ia.revisao_qualidade.0023","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":4,"enunciado":"No cálculo do WER, a soma de substituições, supressões e inserções é dividida pelo número de palavras da hipótese produzida pelo sistema.","gabarito":"E","explicacao":"O denominador do WER é N, o número de palavras da referência (a transcrição feita ou corrigida por pessoa), e não da hipótese do sistema. Por isso, como N é fixo e as inserções não têm limite, o WER pode passar de 100%. A afirmativa trocou referência por hipótese.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Divide-se pelo tamanho do texto correto, feito por gente, e não pelo texto da máquina. É por isso que, quando a máquina inventa muita coisa, a taxa pode passar de 100%.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"hipótese","significado":"texto que o sistema produziu, aquilo que ele acha que foi dito."}],"exemplo":"O texto correto tinha 50 palavras e o do sistema, 58. Ao calcular o WER, Amanda divide os erros por 50, o tamanho da referência, e não por 58."}},{"id":"aut.transcricao_ia.revisao_qualidade.0024","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"O CER é a taxa de erro no nível dos caracteres, útil para evidenciar erros pequenos de grafia em nomes próprios, siglas e números.","gabarito":"C","explicacao":"O CER (Character Error Rate) mede o erro no nível dos caracteres. No WER, uma única letra errada em uma palavra conta como erro de palavra inteira; no CER, o peso é proporcional ao tamanho do erro, o que evidencia erros pequenos em nomes próprios, siglas e números.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. O CER conta os erros letra por letra. Assim, um nome com uma letra trocada aparece como um erro pequeno, do tamanho que ele realmente tem.","teSitua":{"termos":[{"termo":"CER","significado":"sigla em inglês de taxa de erro de caractere, que conta erros letra por letra."},{"termo":"caracteres","significado":"cada letra, número, espaço ou sinal de um texto."},{"termo":"nomes próprios","significado":"nomes de pessoas, lugares e instituições, que se escrevem com letra maiúscula."}],"exemplo":"O sistema escreveu \\"Ministra Gleice\\" em vez de \\"Ministra Gleise\\". O analista Paulo usa o CER e vê que só um caractere estava errado, o que confirma que a máquina chegou perto."}},{"id":"aut.transcricao_ia.revisao_qualidade.0025","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"O CER é a taxa de erro calculada no nível das frases, útil para avaliar a pontuação e a segmentação das falas na transcrição.","gabarito":"E","explicacao":"O CER é a taxa de erro no nível dos caracteres (Character Error Rate), útil para evidenciar erros pequenos de grafia em nomes próprios, siglas e números. Não é medida por frase nem de pontuação. A afirmativa trocou caracteres por frases.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. O \\"C\\" de CER é de caractere, ou seja, letra. A taxa conta erros letra por letra, e não frase por frase, e serve para pegar erros pequenos de grafia.","teSitua":{"termos":[{"termo":"CER","significado":"sigla em inglês de taxa de erro de caractere, que conta erros letra por letra."},{"termo":"segmentação","significado":"divisão do texto ou do áudio em trechos menores, como frases ou falas."}],"exemplo":"Ao montar o relatório, Heloísa explicou à chefia que o CER mede letra por letra e por isso mostra os erros nos nomes dos deputados. Para avaliar a pontuação, ela precisaria de outra métrica."}},{"id":"aut.transcricao_ia.revisao_qualidade.0026","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"O acordo de nível de serviço (SLA) define metas mensuráveis na produção de transcrições, como prazo de entrega e nível mínimo de qualidade.","gabarito":"C","explicacao":"O SLA (acordo de nível de serviço) fixa metas mensuráveis, como prazo de entrega e nível mínimo de qualidade (por exemplo, taxa máxima de erros apontados na auditoria). É complementar à auditoria por amostragem e à revisão em dupla.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. O SLA é o combinado por escrito do que se espera do serviço, com números: em quanto tempo entregar e qual a qualidade mínima aceitável.","teSitua":{"termos":[{"termo":"acordo de nível de serviço","significado":"contrato ou combinado que fixa metas medíveis de prazo e qualidade para um serviço."},{"termo":"SLA","significado":"sigla em inglês de acordo de nível de serviço."},{"termo":"metas mensuráveis","significado":"objetivos que podem ser medidos com números, como horas de prazo ou percentual de erros."}],"exemplo":"O contrato com a empresa de transcrição tem SLA de entrega em quatro horas após a sessão e, no máximo, dois erros por página auditada. O fiscal Moacir confere esses números todo mês."}},{"id":"aut.transcricao_ia.revisao_qualidade.0027","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"O acordo de nível de serviço (SLA) é o mecanismo de controle de qualidade em que um segundo revisor confere o texto já revisado antes da entrega.","gabarito":"E","explicacao":"A conferência por um segundo revisor é a revisão em dupla. O SLA define metas mensuráveis, como prazo de entrega e nível mínimo de qualidade. A afirmativa atribuiu ao SLA a função da revisão em dupla.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Um segundo revisor conferir o texto é a revisão em dupla. O SLA é outra coisa: o combinado com metas de prazo e de qualidade mínima.","teSitua":{"termos":[{"termo":"acordo de nível de serviço","significado":"contrato ou combinado que fixa metas medíveis de prazo e qualidade para um serviço."},{"termo":"SLA","significado":"sigla em inglês de acordo de nível de serviço."},{"termo":"revisor","significado":"profissional que confere o texto com o áudio e corrige erros."}],"exemplo":"Na empresa contratada, o texto de Alice passa pela segunda leitura de Édson: isso é revisão em dupla. O SLA, assinado com a Câmara, só diz que tudo deve chegar em quatro horas, com poucos erros."}},{"id":"aut.transcricao_ia.revisao_qualidade.0028","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"Na produção de transcrições, a auditoria por amostragem avalia parte dos textos entregues e é complementar ao acordo de nível de serviço e à revisão em dupla.","gabarito":"C","explicacao":"O SLA define metas mensuráveis; a auditoria por amostragem avalia parte dos textos entregues; e, na revisão em dupla, um segundo revisor confere o texto. São mecanismos complementares de controle de qualidade.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. A auditoria olha uma parte do que foi entregue para medir a qualidade. Ela não substitui o combinado de metas nem a segunda leitura: as três ferramentas trabalham juntas.","teSitua":{"termos":[{"termo":"auditoria por amostragem","significado":"verificação de qualidade feita em uma parte escolhida dos textos, para estimar como está o conjunto."},{"termo":"acordo de nível de serviço","significado":"contrato ou combinado que fixa metas medíveis de prazo e qualidade para um serviço."},{"termo":"revisão em dupla","significado":"conferência de um texto já revisado por um segundo revisor, antes da entrega."}],"exemplo":"A Câmara exige revisão em dupla dos textos, fixa no SLA o limite de erros e, todo mês, a auditora Vânia sorteia uma amostra para conferir se o limite foi cumprido."}},{"id":"aut.transcricao_ia.revisao_qualidade.0029","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"Na produção de transcrições, a auditoria por amostragem exige a conferência integral de todos os textos entregues, o que a distingue da revisão em dupla.","gabarito":"E","explicacao":"A auditoria por amostragem avalia apenas parte dos textos entregues, com critérios definidos, para estimar a qualidade do conjunto sem conferir tudo. Conferência integral é o oposto de amostragem. A afirmativa contrariou o próprio conceito.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Amostragem quer dizer olhar só uma parte. A graça da auditoria é justamente estimar a qualidade de tudo sem precisar reler todos os textos.","teSitua":{"termos":[{"termo":"auditoria por amostragem","significado":"verificação de qualidade feita em uma parte escolhida dos textos, para estimar como está o conjunto."},{"termo":"conferência integral","significado":"revisão de todos os itens, um por um, sem deixar nenhum de fora."},{"termo":"revisão em dupla","significado":"conferência de um texto já revisado por um segundo revisor, antes da entrega."}],"exemplo":"Com mil transcrições por mês, a equipe de Nelson não teria como reler tudo. A auditoria sorteia cem textos e, a partir deles, estima a qualidade de todo o lote."}},{"id":"aut.transcricao_ia.revisao_qualidade.0030","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"Na revisão em dupla, mecanismo de controle de qualidade de transcrições, um segundo revisor confere o texto já revisado.","gabarito":"C","explicacao":"Na revisão em dupla, um segundo revisor confere o texto já revisado (princípio dos quatro olhos). Junto com o SLA, que fixa metas mensuráveis, e a auditoria por amostragem, que avalia parte dos textos, forma o conjunto de mecanismos complementares de controle de qualidade.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Depois que uma pessoa revisou, outra lê de novo para pegar o que escapou. Duas cabeças conferindo diminuem a chance de erro passar.","teSitua":{"termos":[{"termo":"revisão em dupla","significado":"conferência de um texto já revisado por um segundo revisor, antes da entrega."},{"termo":"controle de qualidade","significado":"conjunto de cuidados para garantir que o produto final saia sem erros."}],"exemplo":"Glória revisa a transcrição da reunião da CPI. Antes da entrega, Wesley lê o texto de novo e encontra uma data errada que tinha passado. A revisão em dupla evitou a publicação do erro."}},{"id":"aut.transcricao_ia.revisao_qualidade.0031","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"Na revisão em dupla, mecanismo de controle de qualidade de transcrições, o mesmo revisor confere duas vezes o próprio texto, em dias diferentes.","gabarito":"E","explicacao":"Na revisão em dupla, quem confere o texto já revisado é um segundo revisor, e não o mesmo profissional (princípio dos quatro olhos). A afirmativa trocou o segundo revisor pelo próprio autor da revisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Na revisão em dupla entram duas pessoas diferentes. Quem fez o trabalho tende a não ver os próprios erros, e por isso um segundo revisor confere o texto.","teSitua":{"termos":[{"termo":"revisão em dupla","significado":"conferência de um texto já revisado por um segundo revisor, antes da entrega."},{"termo":"controle de qualidade","significado":"conjunto de cuidados para garantir que o produto final saia sem erros."}],"exemplo":"Mateus releu o próprio texto no dia seguinte e achou que estava perfeito. Quando a colega Eliane o conferiu, encontrou dois nomes trocados. Por isso a revisão em dupla pede outra pessoa."}},{"id":"aut.transcricao_ia.revisao_qualidade.0032","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":2,"enunciado":"No cálculo do WER, as supressões correspondem às palavras da referência que o sistema deixou de transcrever na hipótese.","gabarito":"C","explicacao":"WER = (S + D + I) / N. As supressões (D, de deletions) são as palavras presentes na referência e omitidas na hipótese; as inserções (I) são as palavras a mais; as substituições (S), as trocadas. N é o número de palavras da referência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Supressão é a palavra que foi dita, está no texto correto, mas a máquina pulou. É um dos três tipos de erro somados na taxa.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"supressões","significado":"palavras ditas que o sistema deixou de escrever."},{"termo":"referência","significado":"texto correto, feito por uma pessoa, usado como gabarito para medir o erro da máquina."},{"termo":"hipótese","significado":"texto que o sistema produziu, aquilo que ele acha que foi dito."}],"exemplo":"A referência diz \\"o projeto foi aprovado ontem\\", e o sistema escreveu \\"o projeto foi aprovado\\". A palavra \\"ontem\\" sumiu. Ao calcular o WER, Isabela conta uma supressão."}},{"id":"aut.transcricao_ia.revisao_qualidade.0033","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"No cálculo do WER, as supressões correspondem às palavras que o sistema escreveu a mais na hipótese, sem que tivessem sido ditas pelo orador.","gabarito":"E","explicacao":"Palavras a mais na hipótese são inserções (I). Supressões (D) são as palavras da referência omitidas pelo sistema. WER = (S + D + I) / N. A afirmativa trocou supressão por inserção.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. Palavra que a máquina inventou é inserção. Supressão é o contrário: a palavra que foi dita e ficou faltando no texto da máquina.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"supressões","significado":"palavras ditas que o sistema deixou de escrever."},{"termo":"hipótese","significado":"texto que o sistema produziu, aquilo que ele acha que foi dito."}],"exemplo":"O deputado disse \\"voto sim\\", e o sistema escreveu \\"eu voto sim\\". O \\"eu\\" a mais é inserção. Se tivesse escrito só \\"sim\\", aí faltaria \\"voto\\", e Jorge contaria uma supressão."}},{"id":"aut.transcricao_ia.revisao_qualidade.0034","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"No CER, o peso de um erro é proporcional ao seu tamanho, ao passo que no WER uma única letra errada faz a palavra inteira contar como erro.","gabarito":"C","explicacao":"No WER, uma única letra errada em uma palavra conta como erro de palavra inteira; no CER, que mede no nível dos caracteres, o peso é proporcional ao tamanho do erro. Por isso o CER evidencia erros pequenos de grafia.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Certo. Na conta por palavra, errar uma letra já derruba a palavra toda. Na conta por letra, o erro pesa só o tamanho que tem: uma letra errada vale uma letra.","teSitua":{"termos":[{"termo":"CER","significado":"sigla em inglês de taxa de erro de caractere, que conta erros letra por letra."},{"termo":"proporcional","significado":"que cresce ou diminui na mesma medida de outra coisa."},{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."}],"exemplo":"O sistema escreveu \\"orçamentaria\\" sem acento. Para o WER de Flávia, é uma palavra inteira errada. Para o CER, é um só caractere em doze, um erro pequeno."}},{"id":"aut.transcricao_ia.revisao_qualidade.0035","subtopico":"transcricao_ia.degravacao_revisao.revisao_qualidade","tipo":"certo_errado","dificuldade":3,"enunciado":"Assim como no WER, no CER uma única letra errada faz a palavra inteira contar como erro, pois as duas taxas usam a palavra como unidade de contagem.","gabarito":"E","explicacao":"O CER usa o caractere como unidade: o peso do erro é proporcional ao seu tamanho. Só no WER uma única letra errada faz a palavra inteira contar como erro. A afirmativa atribuiu ao CER a unidade do WER.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Qualidade e Vocabulário)","mastigado":"Errado. As duas taxas medem coisas diferentes. O WER conta palavras; o CER conta letras. No CER, uma letra errada pesa só como uma letra.","teSitua":{"termos":[{"termo":"WER","significado":"sigla em inglês de taxa de erro de palavra; quanto menor, melhor o sistema."},{"termo":"CER","significado":"sigla em inglês de taxa de erro de caractere, que conta erros letra por letra."},{"termo":"unidade de contagem","significado":"aquilo que se conta para fazer a medida, como palavras ou letras."}],"exemplo":"Numa reunião, Otávio disse que CER e WER davam no mesmo. A analista Rebeca mostrou que \\"Tadeo\\" no lugar de \\"Tadeu\\" é uma palavra errada no WER, mas só um caractere errado no CER."}},{"id":"aut.transcricao_ia.tempo_real.0007","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":2,"enunciado":"Na transcrição em lote (batch), o arquivo de áudio completo é processado depois, de forma assíncrona, o que permite ao modelo usar o contexto inteiro e tende a dar maior precisão que a transcrição em tempo real.","gabarito":"C","explicacao":"Em tempo real (streaming), o áudio chega continuamente e o texto é emitido enquanto a fala ocorre, com resultados parciais revisáveis; exige baixa latência e pouco ou nenhum contexto futuro. Em lote (batch), o arquivo completo é processado depois, de forma assíncrona: o modelo usa o contexto inteiro e várias passagens, o que tende a dar maior precisão e permite diarização mais cuidadosa.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Quando a gravação já terminou, o sistema pode ouvir tudo, inclusive o que vem depois de cada frase, e sem pressa. Por isso costuma acertar mais do que quando precisa escrever ao vivo.","teSitua":{"termos":[{"termo":"transcrição em lote","significado":"transcrição feita depois que a gravação acabou, processando o arquivo inteiro de uma vez."},{"termo":"batch","significado":"palavra em inglês para lote, processamento feito de uma vez sobre um conjunto já completo."},{"termo":"assíncrona","significado":"que não acontece ao mesmo tempo que a fala; o resultado chega depois."},{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."}],"exemplo":"Durante a sessão, a legenda ao vivo da TV Câmara sai com alguns erros. À noite, o arquivo completo é processado em lote, com o contexto inteiro, e o texto que a revisora Glória recebe vem bem mais limpo."}},{"id":"aut.transcricao_ia.tempo_real.0008","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Na transcrição em tempo real (streaming), o modelo dispõe de todo o contexto futuro da fala, sem pressão de latência, o que a torna, em regra, mais precisa que a transcrição em lote.","gabarito":"E","explicacao":"A transcrição em tempo real exige baixa latência e modelo que use pouco ou nenhum contexto futuro; seus resultados parciais podem ser revistos. Quem dispõe do contexto inteiro, sem pressão de latência, é a transcrição em lote, que tende a ser mais precisa. A afirmativa inverteu as características.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Ao vivo, o sistema não sabe o que a pessoa vai dizer em seguida e precisa responder rápido. Quem tem a gravação inteira e tempo de sobra é a transcrição em lote, que por isso costuma errar menos.","teSitua":{"termos":[{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"streaming","significado":"fluxo contínuo de áudio enviado e processado aos poucos, enquanto acontece."},{"termo":"contexto futuro","significado":"parte da fala que ainda vem depois do trecho que está sendo transcrito."},{"termo":"latência","significado":"tempo de atraso entre a fala e o aparecimento do texto."}],"exemplo":"Na legenda ao vivo, o sistema escreveu \\"cessão\\" e, três segundos depois, ainda não sabia que a frase seguia com \\"de crédito\\". No processamento em lote da noite, com a frase completa, acertou de primeira."}},{"id":"aut.transcricao_ia.tempo_real.0009","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":4,"enunciado":"O RNN-Transducer (RNN-T) combina codificador acústico, rede de predição e rede conjunta, não supõe independência entre as saídas, como faz o CTC, e permite decodificação em fluxo, sendo muito usado em transcrição em tempo real.","gabarito":"C","explicacao":"O RNN-T tem três partes: codificador acústico, rede de predição (que consome os rótulos já emitidos e funciona como modelo de linguagem interno) e rede conjunta, que combina as duas. Por isso não supõe independência entre as saídas, como o CTC, e permite decodificação em fluxo (streaming), sendo muito usado em tempo real e em dispositivos. Foi proposto por Graves (2012).","fonte":"Graves, Sequence Transduction with Recurrent Neural Networks (2012); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O RNN-T leva em conta o que já escreveu antes de escolher a próxima letra, ao contrário do CTC. E consegue ir escrevendo enquanto o áudio chega, por isso é tão usado em transcrição ao vivo.","teSitua":{"termos":[{"termo":"RNN-Transducer","significado":"modelo de reconhecimento de fala que gera o texto em fluxo, levando em conta o que já foi escrito."},{"termo":"rede de predição","significado":"parte do RNN-T que olha as letras já escritas e funciona como um modelo de linguagem interno."},{"termo":"rede conjunta","significado":"parte do RNN-T que junta a informação do som e a do texto já escrito para escolher a próxima saída."},{"termo":"CTC","significado":"técnica de treino de reconhecimento de fala que dispensa marcar, antes, onde cada letra aparece no áudio."},{"termo":"decodificação em fluxo","significado":"geração do texto aos poucos, enquanto o áudio ainda está chegando."}],"exemplo":"O ditado por voz do celular de Ronaldo escreve as palavras enquanto ele fala, sem internet. Por trás, há um RNN-Transducer, escolhido justamente por funcionar em fluxo e caber no aparelho."}},{"id":"aut.transcricao_ia.tempo_real.0010","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":4,"enunciado":"Assim como o CTC, o RNN-Transducer (RNN-T) supõe independência condicional entre as saídas, pois não possui componente que consuma os rótulos já emitidos.","gabarito":"E","explicacao":"O RNN-T tem uma rede de predição que consome os rótulos já emitidos e funciona como modelo de linguagem interno; combinada ao codificador pela rede conjunta, ela faz com que o RNN-T não suponha independência entre as saídas, diferentemente do CTC. A afirmativa negou justamente o elemento que distingue os dois.","fonte":"Graves, Sequence Transduction with Recurrent Neural Networks (2012); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. A grande diferença do RNN-T para o CTC é exatamente uma peça que olha o que já foi escrito. Por isso ele não trata cada letra como independente das anteriores.","teSitua":{"termos":[{"termo":"CTC","significado":"técnica de treino de reconhecimento de fala que dispensa marcar, antes, onde cada letra aparece no áudio."},{"termo":"RNN-Transducer","significado":"modelo de reconhecimento de fala que gera o texto em fluxo, levando em conta o que já foi escrito."},{"termo":"independência condicional","significado":"suposição de que cada saída é escolhida sem levar em conta as saídas anteriores."},{"termo":"rótulos","significado":"símbolos de saída que o sistema produz, como letras ou partes de palavras."}],"exemplo":"Na prova da especialização, Matilde escreveu que RNN-T e CTC tratam as saídas da mesma forma. O professor Vicente lembrou que o RNN-T tem a rede de predição, que olha as letras anteriores, e o CTC não."}},{"id":"aut.transcricao_ia.tempo_real.0011","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Em sua forma padrão, a atenção dos modelos sequência a sequência de ASR olha a enunciação inteira, o que dificulta o uso desses modelos em fluxo contínuo, por aumentar a latência.","gabarito":"C","explicacao":"Nos modelos sequência a sequência com atenção, um codificador converte o áudio em representações e um decodificador autorregressivo gera o texto símbolo a símbolo, consultando por atenção as partes relevantes do áudio. Na forma padrão, a atenção olha a enunciação inteira, o que dificulta o uso em fluxo contínuo (aumenta a latência). Exemplos: Listen, Attend and Spell e o Whisper.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Chan et al., Listen, Attend and Spell (2016)","mastigado":"Certo. Esses modelos gostam de ouvir a frase toda antes de escrever, para decidir onde prestar atenção. Ao vivo, esperar a frase inteira gera atraso, e isso atrapalha.","teSitua":{"termos":[{"termo":"atenção","significado":"mecanismo que deixa o modelo focar, a cada passo, nas partes mais importantes da entrada."},{"termo":"sequência a sequência","significado":"tipo de modelo que transforma uma sequência de entrada, como o áudio, em outra sequência, como o texto."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"enunciação","significado":"trecho de fala completo, como uma frase dita de uma vez."},{"termo":"latência","significado":"tempo de atraso entre a fala e o aparecimento do texto."}],"exemplo":"A equipe de Wanderley testou o Whisper para legendar a sessão ao vivo. Como o modelo espera trechos longos para processar, as legendas chegavam com vários segundos de atraso. Para o ao vivo, escolheram um modelo em fluxo."}},{"id":"aut.transcricao_ia.tempo_real.0012","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Nos modelos sequência a sequência com atenção, o decodificador emite todo o texto de uma só vez, sem gerar símbolo a símbolo, razão pela qual são os mais indicados para transcrição em tempo real.","gabarito":"E","explicacao":"O decodificador desses modelos é autorregressivo: gera o texto símbolo a símbolo, consultando por atenção as partes relevantes do áudio. Na forma padrão, a atenção olha a enunciação inteira, o que dificulta o uso em fluxo contínuo e aumenta a latência. A afirmativa errou o funcionamento e a aptidão para tempo real.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Chan et al., Listen, Attend and Spell (2016)","mastigado":"Errado. Esses modelos escrevem o texto aos poucos, uma peça de cada vez. E, por quererem ouvir a frase inteira antes, não são os melhores para o ao vivo: geram atraso.","teSitua":{"termos":[{"termo":"sequência a sequência","significado":"tipo de modelo que transforma uma sequência de entrada, como o áudio, em outra sequência, como o texto."},{"termo":"atenção","significado":"mecanismo que deixa o modelo focar, a cada passo, nas partes mais importantes da entrada."},{"termo":"decodificador","significado":"parte do modelo que gera o texto de saída, uma peça de cada vez."},{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."}],"exemplo":"Ao estudar o Whisper, Alessandra viu que o decodificador escreve token por token, consultando o áudio a cada passo. Entendeu também por que ele não é a primeira escolha para legendas instantâneas."}},{"id":"aut.transcricao_ia.tempo_real.0013","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Um modelo de ASR causal usa apenas o áudio já recebido, sem olhar o futuro, o que o torna adequado à transcrição em tempo real; a quantidade de áudio que o modelo enxerga de uma vez é a janela de contexto.","gabarito":"C","explicacao":"O modelo causal só usa o áudio já recebido e, por isso, serve à transcrição em tempo real. A janela de contexto é a quantidade de áudio que o modelo enxerga de uma vez. Quanto mais contexto futuro o modelo espera, maior a latência: há um compromisso entre latência e precisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O modelo causal só olha para trás: usa o que já ouviu, sem esperar o resto. Por isso serve para o ao vivo. E o pedaço de áudio que ele consegue ver de uma vez tem nome: janela de contexto.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"causal","significado":"que usa só o que já aconteceu, sem depender do que ainda vai chegar."},{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"janela de contexto","significado":"quantidade de áudio que o modelo consegue analisar de uma só vez."}],"exemplo":"Para a legenda ao vivo do Plenário, a equipe de Arlindo escolheu um modelo causal com janela de contexto curta. As palavras aparecem quase na hora em que o deputado fala."}},{"id":"aut.transcricao_ia.tempo_real.0014","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Um modelo de ASR causal é aquele que aguarda o fim da enunciação para usar todo o contexto futuro, o que o torna o mais adequado à transcrição em lote.","gabarito":"E","explicacao":"O modelo causal usa apenas o áudio já recebido, sem olhar o futuro, e por isso é adequado à transcrição em tempo real. Esperar o contexto futuro é o oposto da causalidade e aumenta a latência. A afirmativa inverteu o conceito.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Causal é justamente o modelo que não espera o futuro: decide só com o que já ouviu. É ele que serve para o ao vivo, não para processar gravações inteiras depois.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"causal","significado":"que usa só o que já aconteceu, sem depender do que ainda vai chegar."},{"termo":"enunciação","significado":"trecho de fala completo, como uma frase dita de uma vez."},{"termo":"transcrição em lote","significado":"transcrição feita depois que a gravação acabou, processando o arquivo inteiro de uma vez."}],"exemplo":"No projeto de legendas, Cristiano confundiu os termos e pediu um modelo \\"causal que espera a frase acabar\\". A colega Viviane explicou: se espera a frase acabar, não é causal, e as legendas ficariam atrasadas."}},{"id":"aut.transcricao_ia.tempo_real.0015","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Na transcrição em tempo real, quanto mais contexto futuro o modelo de ASR espera antes de emitir o texto, maior a latência, havendo um compromisso entre latência e precisão.","gabarito":"C","explicacao":"Um modelo causal usa só o áudio já recebido e serve ao tempo real. Quanto mais contexto futuro o modelo espera, maior a latência, embora o contexto adicional possa melhorar a precisão; por isso há um compromisso entre latência e precisão.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. Esperar um pouco mais do áudio ajuda a acertar, mas atrasa o texto. Ao vivo, é preciso escolher o meio-termo entre rapidez e acerto.","teSitua":{"termos":[{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"contexto futuro","significado":"parte da fala que ainda vem depois do trecho que está sendo transcrito."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"latência","significado":"tempo de atraso entre a fala e o aparecimento do texto."}],"exemplo":"A técnica Rosa testou duas configurações: esperando meio segundo de áudio futuro, a legenda erra mais, mas chega na hora; esperando dois segundos, erra menos, mas atrasa. Ela escolheu um segundo, o meio-termo."}},{"id":"aut.transcricao_ia.tempo_real.0016","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Na transcrição em tempo real, ampliar o contexto futuro que o modelo de ASR aguarda reduz a latência, pois o texto passa a ser emitido em blocos maiores.","gabarito":"E","explicacao":"Quanto mais contexto futuro o modelo espera, maior a latência, e não menor: o texto demora mais para sair porque o sistema aguarda mais áudio. Há um compromisso entre latência e precisão. A afirmativa inverteu a relação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Se o sistema espera mais áudio antes de escrever, o texto demora mais a aparecer. Esperar mais aumenta o atraso, não diminui.","teSitua":{"termos":[{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"contexto futuro","significado":"parte da fala que ainda vem depois do trecho que está sendo transcrito."},{"termo":"latência","significado":"tempo de atraso entre a fala e o aparecimento do texto."}],"exemplo":"Querendo legendas mais rápidas, Fausto aumentou a espera do modelo para três segundos de áudio futuro. O resultado foi o oposto: as legendas passaram a aparecer bem depois da fala do deputado."}},{"id":"aut.transcricao_ia.tempo_real.0017","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":2,"enunciado":"Em reconhecimento de fala, a janela de contexto corresponde à quantidade de áudio que o modelo enxerga de uma vez.","gabarito":"C","explicacao":"A janela de contexto é a quantidade de áudio que o modelo enxerga de uma vez. Em modelos causais, usados em tempo real, essa janela só inclui o áudio já recebido; quanto mais contexto futuro o modelo espera, maior a latência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. A janela de contexto é o tamanho do pedaço de áudio que o modelo consegue olhar de cada vez. É como o campo de visão dele.","teSitua":{"termos":[{"termo":"reconhecimento de fala","significado":"tecnologia que transforma a voz gravada ou ao vivo em texto escrito."},{"termo":"janela de contexto","significado":"quantidade de áudio que o modelo consegue analisar de uma só vez."}],"exemplo":"O Whisper trabalha com janelas de 30 segundos. Por isso, quando a equipe de Luana transcreve uma sessão de duas horas, o áudio é cortado em pedaços desse tamanho, que o modelo analisa um a um."}},{"id":"aut.transcricao_ia.tempo_real.0018","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Em reconhecimento de fala, a janela de contexto corresponde ao intervalo entre o fim da fala do orador e a exibição do texto transcrito na tela.","gabarito":"E","explicacao":"A janela de contexto é a quantidade de áudio que o modelo enxerga de uma vez. O intervalo entre a fala e a exibição do texto é a latência. A afirmativa trocou janela de contexto por latência.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O atraso entre a fala e o texto na tela se chama latência. A janela de contexto é outra coisa: o tamanho do pedaço de áudio que o modelo enxerga de uma vez.","teSitua":{"termos":[{"termo":"reconhecimento de fala","significado":"tecnologia que transforma a voz gravada ou ao vivo em texto escrito."},{"termo":"janela de contexto","significado":"quantidade de áudio que o modelo consegue analisar de uma só vez."},{"termo":"orador","significado":"pessoa que está com a palavra e falando na sessão."}],"exemplo":"No relatório, Benedito anotou \\"janela de contexto: 2 segundos de atraso\\". A supervisora Odete corrigiu: os 2 segundos de atraso são a latência; a janela é o trecho de áudio que o modelo processa de cada vez."}},{"id":"aut.transcricao_ia.tempo_real.0019","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":2,"enunciado":"Na transcrição em tempo real, os resultados parciais (intermediários) podem ser revistos pelo sistema à medida que chega mais áudio, enquanto o resultado final corresponde ao trecho já consolidado.","gabarito":"C","explicacao":"Os resultados parciais (intermediários) podem mudar conforme chega mais áudio; o resultado final é o trecho já consolidado. A documentação do Azure AI Speech descreve a transcrição em tempo real como a que devolve resultados intermediários para áudio ao vivo.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Microsoft, documentação Azure AI Speech (transcrição em tempo real)","mastigado":"Certo. Ao vivo, o sistema mostra um palpite que ainda pode mudar quando ouvir o resto da frase. Quando ele fecha aquele pedaço, o texto vira definitivo.","teSitua":{"termos":[{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"resultados parciais","significado":"versões provisórias do texto, mostradas ao vivo e que ainda podem ser corrigidas pelo sistema."},{"termo":"consolidado","significado":"fechado, definitivo, que não vai mais mudar."}],"exemplo":"Na legenda ao vivo, aparece \\"o projeto de lei da\\" e, um instante depois, a frase muda para \\"o projeto de lei do saneamento\\". O primeiro texto era resultado parcial; quando o deputado Ítalo terminou a frase, veio o final."}},{"id":"aut.transcricao_ia.tempo_real.0020","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"Na transcrição em tempo real, os resultados parciais são definitivos e não podem ser alterados pelo sistema, ao passo que o resultado final é o que ainda pode ser revisto à medida que chega mais áudio.","gabarito":"E","explicacao":"É o contrário: os resultados parciais (intermediários) podem ser revistos à medida que chega mais áudio, e o resultado final corresponde ao trecho já consolidado. A afirmativa inverteu os conceitos.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala); Microsoft, documentação Azure AI Speech (transcrição em tempo real)","mastigado":"Errado. A frase trocou os dois. O parcial é o provisório, que ainda pode mudar. O final é o que já foi fechado pelo sistema.","teSitua":{"termos":[{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"resultados parciais","significado":"versões provisórias do texto, mostradas ao vivo e que ainda podem ser corrigidas pelo sistema."},{"termo":"resultado final","significado":"versão fechada de um trecho, que o sistema não altera mais."}],"exemplo":"Ao integrar a legenda ao site, o programador Heitor gravava só os resultados parciais no banco e ficava com frases pela metade. A colega Silvana explicou que deveria gravar os finais, que são os consolidados."}},{"id":"aut.transcricao_ia.tempo_real.0021","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":2,"enunciado":"A documentação do Azure AI Speech descreve a transcrição em tempo real como a que devolve resultados intermediários para áudio ao vivo.","gabarito":"C","explicacao":"Segundo a documentação do Azure AI Speech, a transcrição em tempo real devolve resultados intermediários para áudio ao vivo. Esses resultados parciais podem ser revistos conforme chega mais áudio, e o resultado final corresponde ao trecho já consolidado.","fonte":"Microsoft, documentação Azure AI Speech (transcrição em tempo real); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. No serviço de fala da Microsoft, o modo ao vivo vai mostrando versões provisórias do texto enquanto a pessoa fala, antes de fechar cada trecho.","teSitua":{"termos":[{"termo":"Azure AI Speech","significado":"serviço de reconhecimento e síntese de fala da Microsoft, oferecido pela internet."},{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"resultados intermediários","significado":"versões provisórias do texto, mostradas ao vivo e que ainda podem mudar."}],"exemplo":"Usando o Azure AI Speech na transmissão da audiência, a técnica Joana vê o texto aparecer e se ajustar a cada segundo. Quando o convidado termina a frase, o serviço envia a versão final daquele trecho."}},{"id":"aut.transcricao_ia.tempo_real.0022","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":2,"enunciado":"A documentação do Azure AI Speech descreve a transcrição em tempo real como a que processa apenas arquivos de áudio gravados, devolvendo exclusivamente o resultado final após o término da gravação.","gabarito":"E","explicacao":"Segundo a documentação do Azure AI Speech, a transcrição em tempo real devolve resultados intermediários para áudio ao vivo. Processar arquivos já gravados e devolver só o resultado ao fim é característica da transcrição em lote. A afirmativa descreveu o modo errado.","fonte":"Microsoft, documentação Azure AI Speech (transcrição em tempo real e em lote); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O modo em tempo real trabalha com áudio ao vivo e vai mostrando resultados provisórios. Esperar a gravação acabar para entregar tudo é o modo em lote.","teSitua":{"termos":[{"termo":"Azure AI Speech","significado":"serviço de reconhecimento e síntese de fala da Microsoft, oferecido pela internet."},{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"resultado final","significado":"versão fechada de um trecho, que o sistema não altera mais."}],"exemplo":"Para transcrever as gravações antigas do arquivo, Davi usa o modo em lote do Azure. Para a legenda ao vivo das sessões, usa o modo em tempo real, que vai mostrando o texto enquanto o deputado fala."}},{"id":"aut.transcricao_ia.tempo_real.0023","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, o reconhecimento síncrono processa áudio de até 1 minuto; o assíncrono, de até 480 minutos; e o streaming destina-se ao tempo real.","gabarito":"C","explicacao":"O Google Cloud Speech-to-Text oferece três métodos: síncrono, para áudio de até 1 minuto; assíncrono, para áudio de até 480 minutos (8 horas); e em fluxo (streaming, via gRPC), voltado a casos como a captura de áudio ao vivo de um microfone.","fonte":"Google Cloud Speech-to-Text, documentação (métodos de reconhecimento: síncrono, assíncrono e streaming); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. No serviço do Google, áudio curto, de até um minuto, vai pelo modo síncrono. Gravação longa, de até oito horas, vai pelo assíncrono. E o ao vivo usa o streaming.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço do Google, pela internet, que transforma áudio em texto."},{"termo":"reconhecimento síncrono","significado":"modo em que o sistema recebe o áudio e devolve o texto na mesma chamada, só para áudios curtos."},{"termo":"assíncrono","significado":"modo em que o pedido é processado em segundo plano e o resultado é buscado depois, para áudios longos."},{"termo":"streaming","significado":"fluxo contínuo de áudio enviado e processado aos poucos, enquanto acontece."}],"exemplo":"Ivo transcreve com o Google um recado de 40 segundos pelo modo síncrono. A sessão de seis horas vai pelo assíncrono. E a legenda do Plenário, que precisa sair ao vivo, usa o streaming."}},{"id":"aut.transcricao_ia.tempo_real.0024","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, o reconhecimento síncrono processa áudio de até 60 minutos, sendo o método adequado para transcrever sessões parlamentares inteiras.","gabarito":"E","explicacao":"O reconhecimento síncrono do Google Cloud Speech-to-Text processa áudio de até 1 minuto. Para gravações longas, usa-se o assíncrono, que aceita até 480 minutos. A afirmativa trocou o limite (1 minuto por 60 minutos).","fonte":"Google Cloud Speech-to-Text, documentação (métodos de reconhecimento); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. O modo síncrono do Google só aceita áudio de até um minuto. Para uma sessão inteira, o certo é o modo assíncrono, que vai até 480 minutos.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço do Google, pela internet, que transforma áudio em texto."},{"termo":"reconhecimento síncrono","significado":"modo em que o sistema recebe o áudio e devolve o texto na mesma chamada, só para áudios curtos."}],"exemplo":"Ao enviar a gravação de uma hora pelo modo síncrono, Sandro recebeu erro do serviço. A colega Paula explicou que o limite desse modo é de um minuto e trocou para o assíncrono."}},{"id":"aut.transcricao_ia.tempo_real.0025","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, o reconhecimento assíncrono processa áudio de até 480 minutos, o que o torna adequado à transcrição de gravações longas.","gabarito":"C","explicacao":"O reconhecimento assíncrono do Google Cloud Speech-to-Text aceita áudio de até 480 minutos (8 horas), sendo o método para gravações longas; o síncrono vai até 1 minuto; o streaming destina-se ao tempo real.","fonte":"Google Cloud Speech-to-Text, documentação (métodos de reconhecimento); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O modo assíncrono aguenta gravações de até 480 minutos, ou seja, oito horas. É o caminho para sessões longas que já terminaram.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço do Google, pela internet, que transforma áudio em texto."},{"termo":"reconhecimento assíncrono","significado":"modo em que o pedido é processado em segundo plano e o resultado é buscado depois, para áudios longos."}],"exemplo":"A sessão de votação do orçamento durou sete horas. À noite, Josiane enviou o arquivo pelo modo assíncrono do Google e, pela manhã, buscou a transcrição pronta."}},{"id":"aut.transcricao_ia.tempo_real.0026","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, o reconhecimento assíncrono é limitado a áudios de até 1 minuto, devendo gravações mais longas ser enviadas pelo método síncrono.","gabarito":"E","explicacao":"A afirmativa inverteu os limites. O síncrono é que vai até 1 minuto; o assíncrono aceita até 480 minutos e é o método para gravações longas.","fonte":"Google Cloud Speech-to-Text, documentação (métodos de reconhecimento); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. A frase trocou os modos. O de um minuto é o síncrono. O assíncrono é justamente o feito para gravações compridas, de até 480 minutos.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço do Google, pela internet, que transforma áudio em texto."},{"termo":"reconhecimento assíncrono","significado":"modo em que o pedido é processado em segundo plano e o resultado é buscado depois, para áudios longos."},{"termo":"método síncrono","significado":"modo em que o sistema recebe o áudio e devolve o texto na mesma chamada, só para áudios curtos."}],"exemplo":"Num treinamento, Valéria disse que o modo assíncrono servia para recados curtos. O instrutor Haroldo corrigiu: curto é o síncrono, de até um minuto; o assíncrono vai até oito horas."}},{"id":"aut.transcricao_ia.tempo_real.0027","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, o reconhecimento em fluxo (streaming), via gRPC, é voltado a casos como a captura de áudio ao vivo de um microfone.","gabarito":"C","explicacao":"O reconhecimento em fluxo (streaming, via gRPC) do Google Cloud Speech-to-Text destina-se ao tempo real, em casos como a captura de áudio ao vivo de um microfone; para arquivos, há os métodos síncrono (até 1 minuto) e assíncrono (até 480 minutos).","fonte":"Google Cloud Speech-to-Text, documentação (reconhecimento em streaming); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Certo. O modo streaming recebe o som aos pouquinhos, direto do microfone, e devolve o texto enquanto a pessoa fala. É o modo do ao vivo.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço do Google, pela internet, que transforma áudio em texto."},{"termo":"streaming","significado":"fluxo contínuo de áudio enviado e processado aos poucos, enquanto acontece."},{"termo":"gRPC","significado":"protocolo de comunicação entre sistemas que permite troca contínua de dados nos dois sentidos."}],"exemplo":"Para a legenda ao vivo do auditório, o técnico Emílio liga o microfone ao serviço do Google pelo modo streaming. As palavras do palestrante aparecem no telão enquanto ele fala."}},{"id":"aut.transcricao_ia.tempo_real.0028","subtopico":"transcricao_ia.reconhecimento_fala.tempo_real","tipo":"certo_errado","dificuldade":3,"enunciado":"No Google Cloud Speech-to-Text, a transcrição em tempo real de áudio captado ao vivo por microfone é feita pelo reconhecimento assíncrono, que devolve resultados à medida que a fala ocorre.","gabarito":"E","explicacao":"O tempo real usa o reconhecimento em fluxo (streaming, via gRPC), voltado à captura de áudio ao vivo. O assíncrono processa arquivos de até 480 minutos em segundo plano, com o resultado obtido depois. A afirmativa trocou o streaming pelo assíncrono.","fonte":"Google Cloud Speech-to-Text, documentação (métodos de reconhecimento); baralho Anki Câmara 2026, cargo 11 (Reconhecimento Automático de Fala)","mastigado":"Errado. Para o ao vivo, o Google usa o modo streaming. O assíncrono é para arquivos já gravados: processa em segundo plano e o resultado é buscado depois.","teSitua":{"termos":[{"termo":"Google Cloud Speech-to-Text","significado":"serviço do Google, pela internet, que transforma áudio em texto."},{"termo":"tempo real","significado":"ao vivo, com o texto aparecendo enquanto a pessoa ainda está falando."},{"termo":"reconhecimento assíncrono","significado":"modo em que o pedido é processado em segundo plano e o resultado é buscado depois, para áudios longos."}],"exemplo":"Mirela configurou a legenda do evento no modo assíncrono e o texto só apareceu depois que o palestrante terminou. Trocando para streaming, as palavras passaram a surgir em tempo real."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0002","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A transcrição automática é a saída bruta do sistema de ASR; a degravação é a passagem do registro oral para o texto escrito conforme as convenções do órgão; e a revisão humana confere o texto com o áudio.","gabarito":"C","explicacao":"As três etapas são distintas. A saída bruta do ASR não passa pelas convenções editoriais do órgão nem pela conferência com o áudio; a degravação aplica essas convenções (oradores, grafia, tratamento da oralidade); a revisão humana confere o texto com a gravação e corrige erros.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. São três coisas diferentes: a máquina entrega um texto cru; a degravação transforma a fala em texto do jeito que o órgão manda escrever; e a revisão humana é alguém ouvindo de novo o áudio para conferir se o texto bate.","teSitua":{"termos":[{"termo":"transcrição automática","significado":"texto produzido sozinho pelo computador a partir do áudio, sem nenhum tratamento ou correção humana."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"degravação","significado":"trabalho de passar uma fala gravada para texto escrito, seguindo as regras de forma do órgão que publica."},{"termo":"revisão humana","significado":"conferência feita por uma pessoa, que ouve o áudio e corrige o texto produzido."}],"exemplo":"O sistema da Câmara gera o texto cru da fala do deputado Paulo. Ana faz a degravação, identificando oradores e aplicando o padrão da Casa. Depois, Carlos revisa ouvindo o áudio trecho a trecho e corrige um nome que a máquina errou."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0003","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A degravação é a própria saída bruta do sistema de ASR, entregue sem tratamento editorial, e por isso se confunde com a transcrição automática.","gabarito":"E","explicacao":"A saída bruta do sistema de ASR é a transcrição automática. A degravação é a passagem do registro oral para o texto escrito conforme as convenções do órgão (identificação de oradores, regras de grafia, tratamento da oralidade). A afirmativa trocou a transcrição automática pela degravação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. O texto cru que a máquina entrega se chama transcrição automática. Degravação é outra coisa: é transformar a fala em texto seguindo o jeito de escrever do órgão, com nomes dos oradores e regras de grafia.","teSitua":{"termos":[{"termo":"degravação","significado":"trabalho de passar uma fala gravada para texto escrito, seguindo as regras de forma do órgão que publica."},{"termo":"saída bruta","significado":"resultado do jeito que o sistema entrega, sem correção nem ajuste nenhum."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"tratamento editorial","significado":"ajustes de forma feitos no texto para seguir o padrão de publicação, como grafia, pontuação e identificação de quem fala."},{"termo":"transcrição automática","significado":"texto produzido sozinho pelo computador a partir do áudio, sem tratamento humano."}],"exemplo":"Júlia recebe do sistema um texto sem nomes de oradores e com siglas erradas. Ela sabe que aquilo é só a transcrição automática: a degravação começa quando ela identifica cada deputado e aplica as regras de grafia do manual da Casa."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0004","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A degravação consiste na passagem do registro oral para o texto escrito segundo as convenções do órgão, o que a distingue da mera saída bruta produzida pelo reconhecedor de fala.","gabarito":"C","explicacao":"Degravação é a passagem do registro oral (áudio ou vídeo) para o texto escrito, seguindo as convenções do órgão, como identificação de oradores, regras de grafia e tratamento da oralidade. A saída bruta do ASR não passa por essas convenções.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Degravar é escrever a fala do jeito que o órgão manda, com as regras de forma dele. O texto que sai direto da máquina ainda não passou por esse cuidado, então não é a mesma coisa.","teSitua":{"termos":[{"termo":"degravação","significado":"trabalho de passar uma fala gravada para texto escrito, seguindo as regras de forma do órgão que publica."},{"termo":"registro oral","significado":"gravação em áudio ou vídeo de algo que foi falado, como um discurso em Plenário."},{"termo":"convenções do órgão","significado":"regras próprias de cada instituição sobre como escrever o texto: nomes de oradores, números, siglas e marcações."},{"termo":"saída bruta","significado":"resultado do jeito que o sistema entrega, sem correção nem ajuste nenhum."},{"termo":"reconhecedor de fala","significado":"programa que ouve o áudio e o converte em palavras escritas."}],"exemplo":"O reconhecedor de fala entrega o discurso da senadora Lúcia em um bloco corrido. Na degravação, Marcos separa as falas, coloca o nome de cada orador em destaque e escreve os números como manda o manual da Casa."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0005","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na produção de transcrições, a degravação é a etapa final de conferência do texto com o áudio, em que se corrigem os erros de reconhecimento antes da validação.","gabarito":"E","explicacao":"Conferir o texto com o áudio é a revisão humana, não a degravação. A degravação é a passagem do registro oral para o texto escrito conforme as convenções do órgão. A afirmativa trocou a revisão humana pela degravação.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Ouvir o áudio de novo para conferir e corrigir o texto é a revisão humana. A degravação é passar a fala para o papel no padrão do órgão. A frase misturou as duas etapas.","teSitua":{"termos":[{"termo":"degravação","significado":"trabalho de passar uma fala gravada para texto escrito, seguindo as regras de forma do órgão que publica."},{"termo":"erros de reconhecimento","significado":"palavras que a máquina entendeu errado ao converter a voz em texto."},{"termo":"validação","significado":"aprovação final do texto por uma pessoa responsável, antes de ele virar oficial."}],"exemplo":"Rita degrava a sessão aplicando o padrão da Casa. Só depois Tiago faz a revisão: ouve o áudio, nota que a máquina escreveu \\"reprovo\\" onde o deputado disse \\"aprovo\\" e corrige. Por fim, a chefe Helena valida o texto."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0006","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A revisão humana de uma transcrição confere o texto com o áudio e corrige erros de reconhecimento, de fidelidade e de forma antes da validação final.","gabarito":"C","explicacao":"A revisão humana é a conferência do texto com o áudio e a correção de erros de reconhecimento, de fidelidade e de forma, antes da validação final. É o que separa a saída bruta do ASR de um texto confiável.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. Na revisão, uma pessoa escuta a gravação e compara com o texto, consertando palavras trocadas, trechos que mudaram de sentido e problemas de forma. Só depois disso o texto segue para a aprovação final.","teSitua":{"termos":[{"termo":"revisão humana","significado":"conferência feita por uma pessoa, que ouve o áudio e corrige o texto produzido."},{"termo":"erros de reconhecimento","significado":"palavras que a máquina entendeu errado ao converter a voz em texto."},{"termo":"fidelidade","significado":"qualidade de o texto dizer exatamente o que o orador falou, sem mudar nem acrescentar ideias."},{"termo":"validação final","significado":"aprovação do texto por uma pessoa responsável, antes de ele ser publicado como oficial."}],"exemplo":"Na revisão do discurso do deputado Renato, Clara ouve o áudio e percebe que a máquina escreveu \\"seção\\" em vez de \\"sessão\\" e omitiu um \\"não\\". Ela corrige os dois pontos e envia o texto para a validação da coordenadora Marta."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0007","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":3,"enunciado":"A revisão humana de uma transcrição limita-se a aplicar as convenções editoriais do órgão ao texto bruto do ASR, dispensando a conferência com o áudio.","gabarito":"E","explicacao":"A revisão humana é justamente a conferência do texto com o áudio, para corrigir erros de reconhecimento, de fidelidade e de forma. Aplicar as convenções do órgão é tarefa da degravação e da edição; dispensar o áudio é o erro da afirmativa.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. O coração da revisão é escutar a gravação e comparar com o texto. Sem ouvir o áudio, o revisor não descobre o que a máquina entendeu errado. Ajustar o texto ao padrão do órgão é outra etapa.","teSitua":{"termos":[{"termo":"revisão humana","significado":"conferência feita por uma pessoa, que ouve o áudio e corrige o texto produzido."},{"termo":"convenções editoriais","significado":"regras do órgão sobre como o texto deve ser escrito e apresentado, como grafia de números e marcação de oradores."},{"termo":"texto bruto","significado":"texto do jeito que o sistema entregou, sem correção nem ajuste."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."}],"exemplo":"Pedro só formatou o texto da máquina, sem ouvir o áudio. Quando a revisora Lívia escutou a gravação, descobriu que o sistema tinha trocado o nome de um município citado pelo deputado. Sem a conferência com o áudio, o erro teria sido publicado."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0008","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":2,"enunciado":"A transcrição automática, por si só, não constitui degravação pronta, pois é a saída bruta do ASR, sem a identificação de oradores, as regras de grafia e o tratamento da oralidade exigidos pelo órgão.","gabarito":"C","explicacao":"Transcrição automática é a saída bruta do sistema de ASR, sem tratamento editorial. Degravação é a passagem do registro oral para o texto escrito seguindo as convenções do órgão (identificação de oradores, regras de grafia, tratamento da oralidade), e a revisão humana confere o texto com o áudio antes da validação. Logo, a transcrição automática não é uma degravação pronta.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Certo. O texto que sai da máquina é só o começo. Falta dizer quem está falando, seguir as regras de escrita do órgão e tratar as marcas da fala. Por isso ele ainda não é a degravação final.","teSitua":{"termos":[{"termo":"transcrição automática","significado":"texto produzido sozinho pelo computador a partir do áudio, sem tratamento humano."},{"termo":"degravação","significado":"trabalho de passar uma fala gravada para texto escrito, seguindo as regras de forma do órgão que publica."},{"termo":"saída bruta","significado":"resultado do jeito que o sistema entrega, sem correção nem ajuste nenhum."},{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"tratamento da oralidade","significado":"ajuste das marcas típicas da fala, como hesitações e repetições, para o texto escrito sem mudar o sentido."}],"exemplo":"A Comissão recebe o texto automático de uma audiência. Nele não aparecem os nomes de quem falou, e há muitos \\"é... é...\\". Bianca faz a degravação: marca cada orador, segue o manual e limpa as hesitações. Só então o texto vai para revisão."}},{"id":"aut.transcricao_ia.transcricao_degravacao.0009","subtopico":"transcricao_ia.degravacao_revisao.transcricao_degravacao","tipo":"certo_errado","dificuldade":3,"enunciado":"Quando produzida por sistema de ASR com diarização e pontuação automática, a transcrição automática já constitui degravação pronta, dispensando a aplicação das convenções do órgão e a revisão humana.","gabarito":"E","explicacao":"Mesmo com diarização e pontuação, a transcrição automática continua sendo a saída bruta do ASR, sem tratamento editorial. A degravação exige a aplicação das convenções do órgão, e a revisão humana confere o texto com o áudio antes da validação. A transcrição automática, por si só, não é degravação pronta.","fonte":"Reconhecimento de Fala, Transcrição e IA — baralho Anki Câmara 2026, cargo 11 (Degravação e Pós-processamento)","mastigado":"Errado. Mesmo que a máquina separe as vozes e coloque vírgulas, o texto dela ainda é cru. Falta aplicar as regras do órgão e uma pessoa conferir com o áudio. Recurso automático bom não substitui essas etapas.","teSitua":{"termos":[{"termo":"ASR","significado":"sigla em inglês de reconhecimento automático de fala, a tecnologia que transforma voz em texto."},{"termo":"diarização","significado":"separação automática do áudio por falante, indicando quem falou em cada trecho."},{"termo":"pontuação automática","significado":"recurso do sistema que coloca vírgulas, pontos e outros sinais no texto sem ajuda humana."},{"termo":"degravação","significado":"trabalho de passar uma fala gravada para texto escrito, seguindo as regras de forma do órgão que publica."},{"termo":"convenções do órgão","significado":"regras próprias de cada instituição sobre como escrever o texto: nomes de oradores, números, siglas e marcações."}],"exemplo":"O sistema novo da Assembleia separa as vozes como \\"Falante 1\\" e \\"Falante 2\\" e já pontua o texto. Mesmo assim, Gustavo precisa trocar os rótulos pelos nomes dos deputados, aplicar o manual e ouvir o áudio para corrigir erros antes da publicação."}}]`);export{e as default};